    /// One hand-back judged with a declared cost no disk holds, over a mirror
    /// that is `warm` (its target built into) or cold, by a runner that does
    /// not exist, so any run it reaches is an `error` and costs nothing. Its
    /// verdicts, what it said, whether anything was journaled, whether the
    /// mirror was synced, which happens only for a hand-back that goes on to
    /// run, and the diff its run was to be listed from (empty when none).
    fn judged_with_no_room(
        name: &str,
        warm: bool,
    ) -> (Vec<(u32, Verdict)>, String, bool, bool, String) {
        let base = crate::scratch::scratch(name);
        crate::gitwrite::init_on_main(&base).expect("a repository");
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(base.join("src/lib.rs"), KEYED_SOURCE).unwrap();
        crate::gitwrite::commit_paths(&base, &[String::from("src/lib.rs")], "base")
            .expect("commit");
        let mutants = [listed("BinaryOperator", "!=", (2, 7), (2, 9))];
        let (reach, seconds, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let store = base.join("verdicts");
        let red = Red::new();
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &store,
            red: &red,
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let nowhere = base.join("nowhere");
        let handback = Handback {
            runner: &nowhere,
            diff: None,
            disk: Some((u64::MAX, 0)),
        };
        // ITS OWN STATE, so the mirror is not inside the tree it copies.
        let state = crate::scratch::scratch(&format!("{name}-state"));
        if warm {
            // THE SCHEMA BUILD'S TARGET, which a hand-back's is seeded from.
            let target = schema_target(&state);
            std::fs::create_dir_all(&target).unwrap();
            std::fs::write(
                target.join("CACHEDIR.TAG"),
                "Signature: 8a477f597d28d172789f06886806bc55\n",
            )
            .unwrap();
        }
        let still = super::super::cover::source_digest(&base).unwrap();
        let mut out = Vec::new();
        let (verdicts, unviable) = judge_handbacks(
            &judging,
            (&handback, &base, &still, &state),
            &BTreeSet::from([0]),
            (&Schema::default(), &Reach::default()),
            &mut out,
        )
        .expect("no room degrades, it does not fail the call");
        assert_eq!(unviable, 0);
        let synced = state.join("classic").join("src").join("lib.rs").is_file();
        let listed_from =
            crate::fsio::read_to_string(state.join("classic-target.diff")).unwrap_or_default();
        (
            verdicts,
            String::from_utf8(out).unwrap(),
            store.exists(),
            synced,
            listed_from,
        )
    }

    /// A hand-back whose cold build the disk cannot hold is refused, said,
    /// and judged nothing (CLOUD-2882): no sync, no run, no journal line, and
    /// `no-room`, could-not-look and never an `error` (CLOUD-2253).
    ///
    /// Fails by: the build forced onto a full disk, which on #1276 failed and
    /// was recorded `unviable`, seen here as the mirror synced for a run; the
    /// refusal journaled, so a later sweep reused it; the refusal unsaid; or a
    /// disk shortfall read as a run that erred, which a census reported as
    /// five `error` verdicts with no cause kept.
    #[test]
    fn a_handback_the_disk_cannot_hold_is_refused_unjudged() {
        let (verdicts, said, journaled, synced, _) =
            judged_with_no_room("schema-handback-no-room", false);
        assert_eq!(verdicts, [(0, Verdict::NoRoom)], "{said}");
        assert!(
            !synced,
            "refused before the mirror was synced for a run: {said}"
        );
        assert!(said.contains("no room: its build needs"), "{said}");
        assert!(!journaled, "a refusal is journaled nowhere");
    }

    /// A warm mirror's hand-back runs however little room is left: its target
    /// already holds the build, so only the mutated crate rebuilds.
    ///
    /// Fails by: the cold cost charged on every run, which refused every
    /// hand-back in a container under ~10 GB free though each would have
    /// built, so the local mutant tier went red where CI's did not; seen here
    /// as the mirror never synced for its run.
    #[test]
    fn a_warm_mirror_hands_back_under_the_cold_cost() {
        let (verdicts, said, _, synced, _) = judged_with_no_room("schema-handback-warm", true);
        assert!(
            synced,
            "the warm mirror was synced and its run reached: {said}"
        );
        assert!(!said.contains("no room"), "{said}");
        // ITS RUNNER DOES NOT EXIST, SO THE RUN ERRED, AND WHY IS KEPT
        // (CLOUD-2253): a census's five hand-back errors left no cause.
        assert_eq!(verdicts, [(0, Verdict::Error)], "{said}");
        assert!(said.contains("errors kept under"), "{said}");
    }

    /// A hand-back builds into a target of its own, seeded from the schema
    /// build's, and nothing its build writes reaches the schema build's: a
    /// unit rustc rebuilds, a dep-info file or a fingerprint rewritten in
    /// place. Incremental state and fixtures are not seeded.
    ///
    /// Fails by: the hand-back building into the schema build's target, where
    /// its `classic` units overwrote the schema build's (the next schema build
    /// rebuilt every workspace crate, 1,050 s against 286 s, and a test binary
    /// built from `classic` recorded no reads); or a file cargo writes in place
    /// seeded as a link, so the hand-back's build rewrote the schema build's.
    #[test]
    fn a_handback_never_writes_the_schema_builds_target() {
        let state = crate::scratch::scratch("schema-handback-seed");
        let (schema, own) = (schema_target(&state), handback_target(&state));
        assert!(
            !own.starts_with(&schema) && !schema.starts_with(&own),
            "a hand-back builds into a target of its own"
        );
        let file = |dir: &std::path::Path, name: &str, text: &str| {
            let path = dir.join(name);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, text).unwrap();
        };
        file(
            &schema,
            "CACHEDIR.TAG",
            "Signature: 8a477f597d28d172789f06886806bc55\n",
        );
        for name in [
            "debug/deps/libdep-1.rlib",
            "debug/deps/libdep-1.d",
            "debug/deps/libwork-2.rlib",
            "debug/.fingerprint/dep-1/lib-dep",
            "debug/build/dep-3/output",
            "debug/incremental/work-2/s-1/query-cache.bin",
            "tmp/fixture/target/x",
        ] {
            file(&schema, name, "the schema build's");
        }
        seed_handback_target(&schema, &own);
        assert!(
            own.join("CACHEDIR.TAG").is_file(),
            "the seeded target is warm"
        );
        for name in [
            "debug/deps/libdep-1.rlib",
            "debug/deps/libdep-1.d",
            "debug/.fingerprint/dep-1/lib-dep",
            "debug/build/dep-3/output",
        ] {
            assert_eq!(
                std::fs::read_to_string(own.join(name)).unwrap(),
                "the schema build's",
                "{name} is seeded"
            );
        }
        assert!(
            !own.join("debug/incremental").exists(),
            "no incremental state"
        );
        assert!(!own.join("tmp").exists(), "no fixture");
        // THE HAND-BACK'S BUILD: rustc replaces a unit it rebuilds, and cargo
        // writes dep-info, fingerprints and a build script's output in place.
        let unit = own.join("debug/deps/libwork-2.rlib");
        std::fs::remove_file(&unit).unwrap();
        std::fs::write(&unit, "built from classic").unwrap();
        for name in [
            "debug/deps/libdep-1.d",
            "debug/.fingerprint/dep-1/lib-dep",
            "debug/build/dep-3/output",
        ] {
            std::fs::write(own.join(name), "built from classic").unwrap();
        }
        for name in [
            "debug/deps/libdep-1.rlib",
            "debug/deps/libdep-1.d",
            "debug/deps/libwork-2.rlib",
            "debug/.fingerprint/dep-1/lib-dep",
            "debug/build/dep-3/output",
        ] {
            assert_eq!(
                std::fs::read_to_string(schema.join(name)).unwrap(),
                "the schema build's",
                "{name} is the schema build's still"
            );
        }
    }

    /// A hand-back's room step removes the mirror's own former target, which
    /// no hand-back builds into and no collection ranks, and leaves its
    /// sources.
    ///
    /// Fails by: `classic/target` kept, 10.5 GB on #1276 left by builds before
    /// hand-backs had a target of their own.
    #[test]
    fn a_handback_removes_the_mirrors_former_target() {
        let state = crate::scratch::scratch("schema-handback-former-target");
        let tree = state.join("classic");
        std::fs::create_dir_all(tree.join("target/debug/deps")).unwrap();
        std::fs::write(tree.join("target/debug/deps/x-1"), "a former build").unwrap();
        std::fs::create_dir_all(tree.join("src")).unwrap();
        std::fs::write(tree.join("src/lib.rs"), "pub fn f() {}\n").unwrap();
        let nowhere = state.join("nowhere");
        let handback = Handback {
            runner: &nowhere,
            diff: None,
            disk: None,
        };
        handback_room(&handback, &tree).expect("no declared cost");
        assert!(
            !tree.join("target").exists(),
            "the former target is removed"
        );
        assert!(tree.join("src/lib.rs").is_file(), "its sources stay");
    }

    /// A hand-back's run is listed from its target's own line and nothing
    /// else (CLOUD-2911): the diff its run is handed spans line 2 of
    /// `src/lib.rs`, where the mutant starts, as the synced mirror holds it.
    ///
    /// Fails by: the run listed from the branch's diff or the whole workspace
    /// (no diff written, or another), where cargo-mutants 27.1.0 judges every
    /// field deletion `--re` cannot exclude beside the target under its filter
    /// (measured on `lease.rs`: 19 field deletions for one target, each
    /// printed MISSED); a hunk off by a line, or one spanning the file.
    #[test]
    fn a_handback_is_listed_from_its_targets_line_alone() {
        let (_, said, _, _, listed_from) = judged_with_no_room("schema-handback-own-line", true);
        assert_eq!(
            listed_from,
            "diff --git a/src/lib.rs b/src/lib.rs\n--- a/src/lib.rs\n+++ b/src/lib.rs\n\
             @@ -2,1 +2,1 @@\n-    a == b\n+    a == b\n",
            "{said}"
        );
    }

    /// A listed mutant of `fn f` in `src/lib.rs` whose function span is known,
    /// so it has a [`verdict_key`].
    fn keyed(replacement: &str) -> Listed {
        let mut mutant = listed("BinaryOperator", replacement, (2, 7), (2, 9));
        if let Some(function) = mutant.function.as_mut() {
            function.span = Some(Span {
                start: Position { line: 1, column: 1 },
                end: Position { line: 3, column: 2 },
            });
        }
        mutant
    }

    const KEYED_SOURCE: &str = "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n";

    /// Fails by: a reused hand-back verdict counted down (`-=` for `+=`), or
    /// a reused `unviable` counted by multiplication from zero (`*=` for
    /// `+=`), so the tally reports none.
    #[test]
    fn reused_handback_verdicts_are_counted_and_unviable_ones_tallied() {
        let base = crate::scratch::scratch("schema-handback-reused");
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(base.join("src/lib.rs"), KEYED_SOURCE).unwrap();
        let mutants = [keyed("!="), keyed("<"), keyed(">")];
        let digests = std::collections::BTreeMap::new();
        let key = |mutant: &Listed| verdict_key(&base, mutant, &BTreeSet::new(), &digests).unwrap();
        let cache: std::collections::BTreeMap<String, String> = [
            (key(&mutants[0]), String::from("caught")),
            (key(&mutants[1]), String::from("unviable")),
            (key(&mutants[2]), String::from("unviable")),
        ]
        .into();
        assert_eq!(cache.len(), 3, "the premise: one key per mutant");
        let (reach, seconds) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let store = base.join("verdicts");
        let red = Red::new();
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &store,
            red: &red,
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let nowhere = base.join("nowhere");
        let handback = Handback {
            runner: &nowhere,
            diff: Some(&nowhere),
            disk: None,
        };
        let mut out = Vec::new();
        let (verdicts, unviable) = judge_handbacks(
            &judging,
            (&handback, &base, "not-this-tree", &base),
            &BTreeSet::from([0, 1, 2]),
            (&Schema::default(), &Reach::default()),
            &mut out,
        )
        .unwrap();
        assert_eq!(verdicts, [(0, Verdict::Caught)]);
        assert_eq!(unviable, 2);
        let said = String::from_utf8(out).unwrap();
        assert!(
            said.contains("3 handed-back mutant(s) judged in place, 3 reused"),
            "{said}"
        );
    }

