    /// An error is owned by the mutant whose region holds its primary span;
    /// a warning, a non-compiler line, or an error outside every region is not.
    #[test]
    fn an_error_is_owned_by_its_primary_span() {
        let rendered = Rendered {
            text: String::new(),
            regions: vec![(10..20, vec![4]), (30..40, vec![5])],
            classic: Vec::new(),
            ..Rendered::default()
        };
        let schema = Schema {
            files: [(String::from("src/m.rs"), rendered)].into(),
            ..Schema::default()
        };
        let span = |primary: bool, at: u32| {
            format!("{{\"is_primary\":{primary},\"file_name\":\"src/m.rs\",\"byte_start\":{at}}}")
        };
        let line = |reason: &str, level: &str, message: &str, spans: &str| {
            format!(
                "{{\"reason\":\"{reason}\",\"message\":{{\"level\":\"{level}\",\"message\":\"{message}\",\"spans\":[{spans}]}}}}"
            )
        };
        let messages = [
            line(
                "compiler-message",
                "error",
                "e",
                &format!("{},{}", span(false, 35), span(true, 15)),
            ),
            line("compiler-message", "warning", "w", &span(true, 35)),
            line("build-finished", "error", "b", &span(true, 35)),
            line("compiler-message", "error", "stray", &span(true, 25)),
            String::from("not json"),
        ]
        .join("\n");
        let refused = unviable(&schema, &messages);
        assert_eq!(refused.owned, [4].into());
        let deconsted = Rendered {
            deconst: vec![(String::from("Prior::as_str"), vec![7, 8])],
            ..Rendered::default()
        };
        let schema = Schema {
            files: [
                (
                    String::from("src/m.rs"),
                    schema.files.into_values().next().unwrap(),
                ),
                (String::from("src/p.rs"), deconsted),
            ]
            .into(),
            ..Schema::default()
        };
        let caller = line(
            "compiler-message",
            "error",
            "cannot call non-const method `attribution::Prior::as_str` in constants",
            &span(true, 15),
        );
        let refused = unviable(&schema, &caller);
        assert_eq!(
            refused.reconst,
            [7, 8].into(),
            "inside mutant 4's region too"
        );
        assert!(refused.owned.is_empty());
        assert!(refuses_const_call(
            "cannot call non-const fn `as_str` in constant functions",
            "as_str"
        ));
        assert!(!refuses_const_call(
            "cannot call non-const fn `to_str` in constants",
            "as_str"
        ));
        assert!(!refuses_const_call(
            "mismatched types: `Prior::as_str`",
            "Prior::as_str"
        ));
        let refused = unviable(&schema, &messages);
        assert_eq!(refused.owned, [4].into());
        assert!(refused.reconst.is_empty());
        assert_eq!(refused.stray, vec![String::from("stray")]);
    }

    /// A phase too long for one argument is cut into runs that each fit, and
    /// together hold every case once.
    ///
    /// Fails by: a run past the cap, a case dropped or repeated, or an empty
    /// phase spending a run.
    #[test]
    fn a_phase_is_cut_into_runs_whose_filters_fit_one_argument() {
        // 100 bytes a case (`(binary_id(=batten::it) & test(=…)) | `, a
        // 63-byte name), so exactly 983 fill a run to the cap; without the
        // separator's three bytes, 1,045 would.
        let long = "x".repeat(59);
        let phase: BTreeSet<Case> = (0..1_967).map(|n| case(&format!("{long}{n:04}"))).collect();
        let runs = batches(&phase);
        assert_eq!(
            runs.iter().map(BTreeSet::len).collect::<Vec<_>>(),
            [983, 983, 1],
            "a run is filled to the cap and no further"
        );
        assert_eq!(
            runs.into_iter().flatten().collect::<BTreeSet<Case>>(),
            phase
        );
        assert!(batches(&BTreeSet::new()).is_empty());
        assert_eq!(batches(&[case("one")].into()).len(), 1);
    }

    /// Fails by: a filter past one argument's cap handed to the spawn (lap 25's
    /// `E2BIG`), the whole suite run when the observing cases' filter fits, or
    /// the bound read off the observing cases when every case runs.
    #[test]
    fn a_handback_filter_past_one_argument_runs_every_case() {
        let every: BTreeSet<Case> = (0..200)
            .map(|n| case(&format!("{}{n:03}", "x".repeat(600))))
            .collect();
        let few: BTreeSet<Case> = every.iter().take(3).cloned().collect();
        let (filter, ran) = handback_filter(Some(&few), &few, &every);
        let filter = filter.expect("a small observing set is filtered");
        assert!(filter.len() <= FILTER_BYTES && filter.contains(&few.first().unwrap().0));
        assert_eq!(ran, &few, "the run covers the observing cases");
        // 200 x ~610 bytes is past 96 KiB: no filter, and every case runs.
        let (filter, ran) = handback_filter(Some(&every), &every, &every);
        assert_eq!(filter, None, "an oversized filter is never handed over");
        assert_eq!(ran.len(), every.len());
        let sized =
            super::super::cover::filterset(&every.iter().map(|(n, _)| n.as_str()).collect());
        assert!(sized.len() > FILTER_BYTES, "the fixture is past the cap");
        // Unobserved: no filter, and the cases the caller chose.
        let (filter, ran) = handback_filter(None, &few, &every);
        assert_eq!((filter, ran), (None, &few));
    }

    /// Each listed mutant's [`shard_key`], taken one at a time: what
    /// [`shard_keys`] must answer over the whole listing (CLOUD-2789).
    fn shard_key_each(listing: &[Listed], site_keys: &[Option<String>]) -> Vec<String> {
        listing
            .iter()
            .zip(site_keys)
            .map(|(m, s)| shard_key(m, s.as_deref()))
            .collect()
    }

    /// T4 (CLOUD-2904): a mutant keeps its shard when another is listed
    /// before it, whether it has a site key or is sharded by its
    /// position-free name, and the shards still partition the listing.
    ///
    /// Fails by: a shard cut by listing position (every later mutant moves,
    /// and a census rerun importing its own shard's journal reuses nothing),
    /// a name keyed with its `:line:col`, or a mutant in two shards or none.
    #[test]
    fn a_mutant_keeps_its_shard_when_another_is_listed_before_it() {
        let root = crate::scratch::scratch("schema-shard-keys");
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/lib.rs"),
            "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\nfn g(a: u8) -> u8 {\n    a + 1\n}\n",
        )
        .unwrap();
        let mutant = |name: &str, genre: &str, with: &str, at: ((usize, usize), (usize, usize))| {
            let (from, to) = at;
            let site = Listed {
                name: name.to_owned(),
                ..listed(genre, with, from, to)
            };
            if from.0 <= 3 {
                in_function(site, (1, 1), (3, 2))
            } else {
                in_function(site, (4, 1), (6, 2))
            }
        };
        let listing = vec![
            mutant(
                "src/lib.rs:2:7: == with !=",
                "BinaryOperator",
                "!=",
                ((2, 7), (2, 9)),
            ),
            mutant(
                "src/lib.rs:2:7: == with <",
                "BinaryOperator",
                "<",
                ((2, 7), (2, 9)),
            ),
            mutant(
                "src/lib.rs:2:7: == with >",
                "BinaryOperator",
                ">",
                ((2, 7), (2, 9)),
            ),
            mutant(
                "src/lib.rs:5:7: + with -",
                "BinaryOperator",
                "-",
                ((5, 7), (5, 8)),
            ),
            mutant(
                "src/lib.rs:5:7: + with *",
                "BinaryOperator",
                "*",
                ((5, 7), (5, 8)),
            ),
            Listed {
                name: String::from("src/lib.rs:5:7: no site"),
                ..listed("FnValue", "0", (5, 5), (5, 10))
            },
        ];
        let shards = |listing: &[Listed]| {
            // THROUGH `shard_keys`, the slice's own caller's spelling, so a
            // listing whose keys came back empty is a case that fails here.
            let site_keys: Vec<Option<String>> =
                listing.iter().map(|m| site_key(&root, m)).collect();
            let keys = shard_keys(listing, &site_keys);
            // EACH MUTANT ITS OWN KEY (CLOUD-2789): one shared key repeated
            // keeps every mutant in one shard through an insert, so neither
            // the count nor the slices tell it from the real keys.
            assert_eq!(keys, shard_key_each(listing, &site_keys), "each its own");
            let ids: Vec<u32> = (0..u32::try_from(listing.len()).unwrap()).collect();
            let mut shard_of: std::collections::BTreeMap<String, usize> =
                std::collections::BTreeMap::new();
            for k in 0..4 {
                let scope = Scope {
                    shard: Some((k, 4)),
                    phase: Phase::Judge,
                };
                let (mine, _, _) =
                    scope.slice(&keys, ids.clone(), &BTreeSet::new(), &BTreeSet::new());
                for id in mine {
                    let name = listing[id as usize].name.clone();
                    assert!(shard_of.insert(name, k).is_none(), "in one shard only");
                }
            }
            assert_eq!(shard_of.len(), listing.len(), "every mutant in a shard");
            shard_of
        };
        let held = shards(&listing);
        let mut inserted = vec![mutant(
            "src/lib.rs:5:7: + with /",
            "BinaryOperator",
            "/",
            ((5, 7), (5, 8)),
        )];
        inserted.extend(listing.iter().cloned());
        let moved = shards(&inserted);
        for (name, k) in &held {
            assert_eq!(moved[name], *k, "{name} kept its shard");
        }
        assert_eq!(
            position_free("src/lib.rs:5:7: no site"),
            position_free("src/lib.rs:9:3: no site"),
            "a name sheds its position"
        );
        assert_eq!(position_free("a::b:7"), "a::b:7", "a lone number stays");
    }

    /// Fails by: the head segment read as a position (`at > 0` as `>=`), so
    /// a name opening on two numbers sheds its own path (CLOUD-2789).
    #[test]
    fn a_names_head_is_never_shed_as_a_position() {
        assert_eq!(
            position_free("5:7: x"),
            "5:7: x",
            "the head is the path, never a position, however it reads"
        );
    }

    /// Fails by: a listing's keys not each mutant's own [`shard_key`] in
    /// listing order, so `slice` reads another mutant's shard (CLOUD-2789).
    #[test]
    fn shard_keys_are_each_mutants_key_in_order() {
        let named = |name: &str| Listed {
            name: name.to_owned(),
            ..listed("FnValue", "0", (1, 1), (1, 2))
        };
        let mutants = [named("src/a.rs:1:1: x"), named("src/b.rs:2:2: y")];
        assert_eq!(
            shard_keys(&mutants, &[Some(String::from("site")), None]),
            ["site", "src/b.rs: y"]
        );
    }

    #[test]
    fn a_sweep_exit_maps_onto_the_contract_and_the_graver_one_wins() {
        use crate::exit::ExitCode;
        assert_eq!(exit_of(0), ExitCode::Success);
        assert_eq!(exit_of(2), ExitCode::Violation);
        assert_eq!(exit_of(3), ExitCode::Internal);
        assert_eq!(exit_of(1), ExitCode::Internal);
        for (a, b, graver) in [
            (ExitCode::Success, ExitCode::Violation, ExitCode::Violation),
            (ExitCode::Violation, ExitCode::Success, ExitCode::Violation),
            (ExitCode::Violation, ExitCode::Internal, ExitCode::Internal),
            (ExitCode::Usage, ExitCode::Usage, ExitCode::Usage),
        ] {
            assert_eq!(worse(a, b), graver, "{a:?} {b:?}");
        }
    }

    #[test]
    fn a_first_phase_stops_once_its_budget_is_spent_exactly() {
        let cases: BTreeSet<Case> = ["a", "b", "c"].map(case).into();
        let seconds = [("a", 1.0), ("b", 3.0), ("c", 5.0)]
            .map(|(name, time)| (case(name), time))
            .into();
        let (first, second) = phases(&cases, &BTreeSet::new(), &seconds);
        assert_eq!(first, ["a", "b"].map(case).into());
        assert_eq!(second, [case("c")].into());
    }

    #[test]
    fn a_cases_sources_are_its_module_or_its_test_target() {
        let dirs: std::collections::BTreeMap<String, String> = [
            (String::from("batten"), String::from("crates/batten")),
            (String::from("root"), String::new()),
        ]
        .into();
        let sources = |name: &str, binary: &str| case_sources(&dirs, name, binary);
        assert_eq!(sources("top", "root"), vec!["src/lib.rs"]);
        assert_eq!(
            sources("hook::tests::x", "batten"),
            vec!["crates/batten/src/hook.rs", "crates/batten/src/hook/mod.rs"]
        );
        assert_eq!(
            sources("mutate::schema::x", "batten"),
            vec![
                "crates/batten/src/mutate/schema.rs",
                "crates/batten/src/mutate/schema/mod.rs"
            ]
        );
        assert_eq!(
            sources("cli::a_case", "batten::it"),
            vec![
                "crates/batten/tests/it/cli.rs",
                "crates/batten/tests/it/common/mod.rs",
                "crates/batten/tests/it.rs"
            ]
        );
        assert_eq!(
            sources("x", "batten::bin/batten"),
            vec!["crates/batten/src/main.rs"]
        );
        assert!(sources("x", "nobody").is_empty());
    }

    fn in_function(mut mutant: Listed, from: (usize, usize), to: (usize, usize)) -> Listed {
        if let Some(function) = mutant.function.as_mut() {
            function.span = Some(Span {
                start: Position {
                    line: from.0,
                    column: from.1,
                },
                end: Position {
                    line: to.0,
                    column: to.1,
                },
            });
        }
        mutant
    }

    /// A scratch checkout of two packages and a lockfile: `p`, whose
    /// `src/lib.rs` holds one comparison to mutate, and `b` beside it.
    fn two_package_tree() -> std::path::PathBuf {
        let root = crate::scratch::scratch("schema-build-key");
        for (path, text) in [
            ("Cargo.toml", "[package]\nname = \"p\"\n"),
            (
                "src/lib.rs",
                "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n",
            ),
            ("b/Cargo.toml", "[package]\nname = \"b\"\n"),
            ("b/src/lib.rs", "pub fn g() {}\n"),
            ("Cargo.lock", "version = 4\n"),
        ] {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        }
        root
    }

    /// Every case's key holds what its record cannot name: the sources of
    /// each package the sweep never probed, the lockfile and manifests, the
    /// toolchain and the flags. An edit to any of them moves the pair key and
    /// drops the carried record, so the case runs again.
    ///
    /// Fails by: a helper crate's edit, a lockfile bump or a new compiler
    /// leaving a carried pass and a reused pair outcome in place, though the
    /// code the case runs is no longer the code it passed on.
    #[test]
    fn an_unprobed_package_or_the_lockfile_moves_every_case_key() {
        let root = two_package_tree();
        let ids: std::collections::BTreeMap<String, String> = [
            "Cargo.toml",
            "src/lib.rs",
            "b/Cargo.toml",
            "b/src/lib.rs",
            "Cargo.lock",
        ]
        .map(|path| (path.to_owned(), String::from("v1")))
        .into();
        let format = Format {
            probed: [String::from("src/lib.rs")].into(),
            ..Format::default()
        };
        let case = (String::from("t"), String::from("bin"));
        let mutant = in_function(
            listed("BinaryOperator", "!=", (2, 7), (2, 9)),
            (1, 1),
            (3, 2),
        );
        let digests = |ids: &std::collections::BTreeMap<String, String>, compiler: &[u8]| {
            under_build(
                [(case.clone(), String::from("d"))].into(),
                (
                    &sweep_build(&root, ids, &format, compiler),
                    &super::super::resume::unprobed_folds(&root, ids, &format),
                ),
            )
        };
        let held = digests(&ids, b"rustc 1");
        let pair = pair_key(&root, &mutant, &case, &held).unwrap();
        let edited = |path: &str| {
            let mut moved = ids.clone();
            moved.insert(path.to_owned(), String::from("v2"));
            digests(&moved, b"rustc 1")
        };
        let probed = edited("src/lib.rs");
        assert_eq!(
            probed, held,
            "a probed source is the record's own to key, by function"
        );
        for (why, now) in [
            ("an unprobed package's source", edited("b/src/lib.rs")),
            ("the lockfile", edited("Cargo.lock")),
            ("the toolchain", digests(&ids, b"rustc 2")),
        ] {
            assert_ne!(
                pair_key(&root, &mutant, &case, &now).unwrap(),
                pair,
                "{why}"
            );
            assert_ne!(
                verdict_key(&root, &mutant, &[case.clone()].into(), &now),
                verdict_key(&root, &mutant, &[case.clone()].into(), &held),
                "{why}"
            );
            let base = crate::scratch::scratch("schema-build-key-carry");
            let sealed = format!("D{}\n", held[&case]);
            record(&base, "t", "t", Some("0"), &[(DEPENDS, sealed.as_str())]);
            let recompute =
                |_: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
                 _: &std::collections::BTreeMap<Case, BTreeSet<String>>| {
                    now.clone()
                };
            assert_eq!(
                carry_forward(&base, "tree-2", &no_identity(), (&recompute, None), true).unwrap(),
                (0, 0),
                "{why} drops the carried record"
            );
            assert!(!base.join("t").exists(), "{why}");
        }
        let flagged = Format {
            flags: [(String::from("RUSTFLAGS"), String::from("-Cx"))].into(),
            ..format.clone()
        };
        assert_ne!(
            sweep_build(&root, &ids, &flagged, b"rustc 1"),
            sweep_build(&root, &ids, &format, b"rustc 1"),
            "the flags"
        );
        // AND THE CARRY ITSELF HOLDS when nothing it keys on moved.
        let base = crate::scratch::scratch("schema-build-key-held");
        let sealed = format!("D{}\n", held[&case]);
        record(&base, "t", "t", Some("0"), &[(DEPENDS, sealed.as_str())]);
        let recompute =
            |_: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
             _: &std::collections::BTreeMap<Case, BTreeSet<String>>| { held.clone() };
        assert_eq!(
            carry_forward(&base, "tree-2", &no_identity(), (&recompute, None), true).unwrap(),
            (1, 0)
        );
    }

    /// A site's key is its function's text and the mutation: two mutations
    /// of one site differ, a function moved whole keeps its key, and a
    /// verdict's key also moves with the reaching cases' files.
    #[test]
    fn a_key_follows_the_function_and_not_its_position() {
        let root = crate::scratch::scratch("schema-keys");
        let source = "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n";
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/lib.rs"), source).unwrap();
        let ne = in_function(
            listed("BinaryOperator", "!=", (2, 7), (2, 9)),
            (1, 1),
            (3, 2),
        );
        let lt = in_function(
            listed("BinaryOperator", "<", (2, 7), (2, 9)),
            (1, 1),
            (3, 2),
        );
        let key = site_key(&root, &ne).unwrap();
        assert_eq!(key.len(), 64);
        assert_ne!(Some(key.clone()), site_key(&root, &lt));
        assert_eq!(
            site_key(&root, &listed("BinaryOperator", "!=", (2, 7), (2, 9))),
            None
        );
        let dirs = [(String::from("p"), String::new())].into();
        let cases = [(String::from("x"), String::from("p"))].into();
        let none = std::collections::BTreeMap::new();
        let digests = case_digests(&root, &cases, &dirs, &none, &depends(&[]));
        let verdict = verdict_key(&root, &ne, &cases, &digests).unwrap();
        assert_eq!(verdict.len(), 64);
        assert_ne!(verdict, key);
        std::fs::write(root.join("src/lib.rs"), format!("\n{source}")).unwrap();
        let moved = in_function(
            listed("BinaryOperator", "!=", (3, 7), (3, 9)),
            (2, 1),
            (4, 2),
        );
        assert_eq!(site_key(&root, &moved), Some(key));
        let digests = case_digests(&root, &cases, &dirs, &none, &depends(&[]));
        assert_ne!(verdict_key(&root, &moved, &cases, &digests), Some(verdict));
    }

    /// A lap's reach run starts only the cases no record holds finished: the
    /// rest are filtered out before nextest starts them, none at all where
    /// every case is finished, and no filter where at least half must run or a
    /// name is one a filter cannot spell.
    ///
    /// Fails by: every listed case started for the recorder to skip (the T+1
    /// measurement over 82e566618 ran the whole suite, 1,891 s, to re-record
    /// 57 of 11,797 cases).
    #[test]
    fn a_lap_runs_only_the_cases_no_record_holds_finished() {
        let case = |name: &str| (name.to_owned(), String::from("batten::it"));
        let listed: BTreeSet<Case> = ["a::one", "a::two", "b::three", "b::four", "c::five"]
            .into_iter()
            .map(case)
            .collect();
        let finished: BTreeSet<Case> = ["a::one", "a::two", "b::three", "b::four"]
            .into_iter()
            .map(case)
            .collect();
        assert_eq!(
            run_filter(&listed, &finished, false).as_deref(),
            Some("(binary_id(=batten::it) & test(=c::five))"),
            "the one case no record holds finished"
        );
        assert_eq!(
            run_filter(&listed, &listed, false).as_deref(),
            Some("none()"),
            "no case where every one is finished"
        );
        let few: BTreeSet<Case> = ["a::one"].into_iter().map(case).collect();
        assert_eq!(
            run_filter(&listed, &few, false),
            None,
            "most must run: no filter"
        );
        let mut odd = listed.clone();
        odd.insert(case("c::six(\"x\")"));
        let mut most = finished.clone();
        most.insert(case("b::seven"));
        assert_eq!(
            run_filter(&odd, &most, false),
            None,
            "a name no filter spells"
        );
        // Under half by a hair: one of three is due, so twice it is still
        // fewer than the listed (CLOUD-2789).
        let three: BTreeSet<Case> = ["a::one", "a::two", "c::five"]
            .into_iter()
            .map(case)
            .collect();
        assert_eq!(
            run_filter(&three, &finished, false).as_deref(),
            Some("(binary_id(=batten::it) & test(=c::five))"),
            "one due of three is filtered"
        );
    }

    /// A DOUBLE RECORDING RUNS EVERY CASE, whatever records it found: its
    /// first pass is a witness for the second, which runs over cleared
    /// records, so a case whose finished record was carried in from another
    /// tree must run in the first pass too.
    ///
    /// Fails by: the lap's filter applied to the first pass, so a record this
    /// tree never made stood as the witness the second pass is judged against
    /// (bootstrap shard 5/8 at 34c6e4d1f survived the `!` before `twice()`).
    #[test]
    fn a_double_recording_runs_every_case_whatever_records_it_carried() {
        let case = |name: &str| (name.to_owned(), String::from("batten::it"));
        let listed: BTreeSet<Case> = ["a::one", "a::two", "b::three", "b::four", "c::five"]
            .into_iter()
            .map(case)
            .collect();
        let carried: BTreeSet<Case> = ["a::one", "a::two", "b::three", "b::four"]
            .into_iter()
            .map(case)
            .collect();
        assert_eq!(run_filter(&listed, &carried, true), None, "every case runs");
        assert_eq!(
            run_filter(&listed, &listed, true),
            None,
            "even with every case carried"
        );
        assert!(
            run_filter(&listed, &carried, false).is_some(),
            "a lap over the same records filters"
        );
    }

    /// A site's key reads its function as a key reads code (CLOUD-2904): a `//`
    /// comment and a blank line inside the function, before the site, keep
    /// the site's key; a statement added there moves it.
    ///
    /// Fails by: the function's raw text keyed, or the site's byte offset (the
    /// T+1 measurement over 82e566618: one comment inside `adjudicate`
    /// re-keyed every mutant of it, judged them afresh, and re-recorded every
    /// case that ran it).
    #[test]
    fn a_comment_inside_a_function_keeps_its_sites_keys() {
        let root = crate::scratch::scratch("schema-keys-comment");
        std::fs::create_dir_all(root.join("src")).unwrap();
        let key_of = |source: &str, line: usize, end: usize| {
            std::fs::write(root.join("src/lib.rs"), source).unwrap();
            site_key(
                &root,
                &in_function(
                    listed("BinaryOperator", "!=", (line, 7), (line, 9)),
                    (1, 1),
                    (end, 2),
                ),
            )
            .unwrap()
        };
        let held = key_of("fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n", 2, 3);
        let commented = key_of(
            "fn f(a: u8, b: u8) -> bool {\n    // why it compares\n\n    a == b\n}\n",
            4,
            5,
        );
        assert_eq!(
            commented, held,
            "a comment and a blank line keep the site's key"
        );
        let changed = key_of(
            "fn f(a: u8, b: u8) -> bool {\n    let _ = 0;\n    a == b\n}\n",
            3,
            4,
        );
        assert_ne!(changed, held, "a statement added moves it");
    }

    /// A case's digest moves with its own test and the helpers beside it,
    /// and with nothing else in its file: an edit to another test or to the
    /// code under test leaves it.
    ///
    /// Fails by: the file read whole (any edit moves every case), a helper
    /// left out (its edit moves nothing), or two tests sharing one digest.
    #[test]
    fn a_case_is_keyed_by_its_own_test_and_helpers() {
        let root = crate::scratch::scratch("schema-case-digests");
        std::fs::create_dir_all(root.join("src")).unwrap();
        let write = |code: &str, helper: &str, b: &str| {
            std::fs::write(
                root.join("src/lib.rs"),
                format!(
                    "pub fn code() -> u8 {{ {code} }}\n\
                     #[cfg(test)]\nmod tests {{\n\
                     fn helper() -> u8 {{ {helper} }}\n\
                     #[test]\nfn a() {{ assert_eq!(helper(), 1); }}\n\
                     #[test]\nfn b() {{ assert_eq!(super::code(), {b}); }}\n}}\n"
                ),
            )
            .unwrap();
        };
        let dirs = [(String::from("p"), String::new())].into();
        let cases: BTreeSet<Case> = ["tests::a", "tests::b"]
            .map(|name| (name.to_owned(), String::from("p")))
            .into();
        let digest = |name: &str| {
            case_digests(
                &root,
                &cases,
                &dirs,
                &std::collections::BTreeMap::new(),
                &depends(&[]),
            )[&(name.to_owned(), String::from("p"))]
                .clone()
        };
        write("1", "1", "1");
        let (a, b) = (digest("tests::a"), digest("tests::b"));
        assert_ne!(a, b);
        write("2", "1", "1");
        assert_eq!(
            (digest("tests::a"), digest("tests::b")),
            (a.clone(), b.clone())
        );
        write("2", "1", "2");
        assert_eq!(digest("tests::a"), a, "another test's edit");
        assert_ne!(digest("tests::b"), b);
        write("2", "3", "2");
        assert_ne!(digest("tests::a"), a, "a helper's edit");
    }

    /// Every function body that runs at run time gains a probe, numbered from
    /// the id given, and a `const fn`, a body-less declaration or a function
    /// in a const item does not; with no id, nothing is probed.
    #[test]
    fn every_runtime_function_body_gains_a_probe() {
        let source = "fn f(a: u8) -> u8 {\n    a\n}\nconst fn g() -> u8 {\n    1\n}\n\
                      trait T {\n    fn h(&self);\n    fn d(&self) {}\n}\n\
                      const C: u8 = { fn inner() -> u8 { 2 } inner() };\n";
        let rendered = render(source, &[], &BTreeSet::new(), Some(5));
        assert!(
            rendered
                .text
                .contains("fn f(a: u8) -> u8 {crate::__batten_fn(5);"),
            "{}",
            rendered.text
        );
        assert!(
            rendered
                .text
                .contains("fn d(&self) {crate::__batten_fn(6);}"),
            "{}",
            rendered.text
        );
        assert_eq!(rendered.probes.len(), 2, "{}", rendered.text);
        assert_eq!(rendered.probe_regions.len(), 2);
        let first = &rendered.probe_regions[0];
        assert_eq!(&rendered.text[first.clone()], "crate::__batten_fn(5);");
        let bare = render(source, &[], &BTreeSet::new(), None);
        assert_eq!(bare.text, source);
        assert!(bare.probes.is_empty());
    }

    /// The skeleton holds what no probe records: it moves with a type or a
    /// `const fn` body, and not with a probed function — body, signature, or
    /// the function being new — nor with a comment or whitespace. A probed
    /// function's own digest moves with its signature instead.
    ///
    /// Fails by: a probed signature left in the skeleton (every added helper
    /// moves every key), trivia hashed, or a signature in neither digest.
    #[test]
    fn the_skeleton_moves_with_what_no_probe_records() {
        let skeleton = |source: &str| render(source, &[], &BTreeSet::new(), Some(0)).skeleton;
        let probes = |source: &str| render(source, &[], &BTreeSet::new(), Some(0)).probes;
        let base = "struct S(u8);\nfn f() -> u8 {\n    1\n}\nconst fn g() -> u8 {\n    1\n}\n";
        let held = skeleton(base);
        assert_eq!(
            skeleton(&base.replace("    1\n}\nconst", "    2\n}\nconst")),
            held
        );
        assert_ne!(
            skeleton(&base.replace("struct S(u8)", "struct S(u16)")),
            held
        );
        let retyped = base.replace("fn f() -> u8", "fn f() -> u16");
        assert_eq!(skeleton(&retyped), held, "a probed signature is its own");
        assert_ne!(probes(&retyped), probes(base), "and moves its probe");
        assert_eq!(
            skeleton(&format!(
                "{base}/// helper\n#[inline]\nfn h(x: u8) -> u8 {{\n    x\n}}\n"
            )),
            held,
            "a new probed function moves no other key"
        );
        assert_eq!(
            skeleton(&base.replace("struct S(u8);", "// note\nstruct  S( u8 ) ;")),
            held,
            "trivia is not hashed"
        );
        assert_ne!(
            skeleton(&format!("{}2\n}}\n", &base[..base.len() - 4])),
            held
        );
        let unprobed = render(base, &[], &BTreeSet::new(), None).skeleton;
        assert_ne!(
            render(
                &base.replace("    1\n}\nconst", "    2\n}\nconst"),
                &[],
                &BTreeSet::new(),
                None
            )
            .skeleton,
            unprobed,
            "an unprobed file is whole"
        );
    }

    /// A case's digest moves with a function it executed and with nothing it
    /// did not, and every untraced case's moves with every non-Rust file.
    ///
    /// Fails by: the executed functions left out (a callee's edit reuses a
    /// stale kill), or another case's functions read into this one.
    #[test]
    fn a_case_moves_with_the_functions_it_executed() {
        let root = crate::scratch::scratch("schema-executed-digests");
        let dirs = std::collections::BTreeMap::new();
        let (one, two) = (case("one"), case("two"));
        let cases: BTreeSet<Case> = [one.clone(), two.clone()].into();
        let executed = [(one.clone(), [0].into()), (two.clone(), [1].into())].into();
        let digests = |probes: &[String], untraced: &str| {
            case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    untraced,
                    ..depends(probes)
                },
            )
        };
        let held = digests(&[String::from("a"), String::from("b")], "g");
        let moved = digests(&[String::from("a2"), String::from("b")], "g");
        assert_ne!(moved[&one], held[&one], "its callee changed");
        assert_eq!(moved[&two], held[&two], "not a function it ran");
        let global = digests(&[String::from("a"), String::from("b")], "h");
        assert!(cases.iter().all(|case| global[case] != held[case]));
    }

    /// A case's digest is one of the digests it ran, never of which of two
    /// identical functions it hit: a record read back by digest
    /// ([`carry_forward`]) holds every twin, and keys the same as sealed.
    ///
    /// Fails by: the twin's names left out of the sealed key, so the carry's
    /// recompute differs and the record is re-recorded with nothing changed
    /// (794 of 811 on #1276 across a one-function edit); or the twin's names
    /// unkeyed, so an edit to what it names moves no case that ran its body.
    #[test]
    fn a_case_keys_every_twin_of_what_it_ran() {
        let root = crate::scratch::scratch("schema-twin-digests");
        let dirs = std::collections::BTreeMap::new();
        let one = case("one");
        let cases: BTreeSet<Case> = [one.clone()].into();
        let probes = [String::from("a"), String::from("a")];
        let names = [BTreeSet::from([String::from("LIMIT")]), BTreeSet::new()];
        let digests = |ran: &[usize], limit: &str| {
            let executed: std::collections::BTreeMap<Case, BTreeSet<usize>> =
                [(one.clone(), ran.iter().copied().collect())].into();
            let items: std::collections::BTreeMap<String, BTreeSet<String>> =
                [(String::from("LIMIT"), BTreeSet::from([limit.to_owned()]))].into();
            case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    names: &names,
                    items: &items,
                    ..depends(&probes)
                },
            )[&one]
                .clone()
        };
        assert_eq!(
            digests(&[1], "1"),
            digests(&[0, 1], "1"),
            "as sealed, as carried"
        );
        assert_ne!(
            digests(&[1], "1"),
            digests(&[1], "2"),
            "its twin names LIMIT"
        );
    }

    /// A sweep's digests are taken once per case and inputs: the seal asks
    /// again for what the carry took, and only a case whose ran ids or read
    /// paths changed is computed again.
    ///
    /// Fails by: every case recomputed at the seal (820 s on #1276), or a
    /// case whose reads changed answered from what it held.
    #[test]
    fn a_sweep_takes_each_cases_digest_once_per_inputs() {
        let memo = DigestMemo::default();
        let (one, two) = (case("one"), case("two"));
        let asked = std::cell::RefCell::new(Vec::new());
        let take = |executed: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
                    read: &std::collections::BTreeMap<Case, BTreeSet<String>>| {
            memo.take(executed, read, |due| {
                asked.borrow_mut().extend(due.keys().cloned());
                due.iter()
                    .map(|(case, ids)| {
                        let touched = read.get(case).map(BTreeSet::len);
                        (case.clone(), format!("{ids:?}{touched:?}"))
                    })
                    .collect()
            })
        };
        let executed: std::collections::BTreeMap<Case, BTreeSet<usize>> =
            [(one.clone(), [0].into()), (two.clone(), [1].into())].into();
        let none = std::collections::BTreeMap::new();
        let first = take(&executed, &none);
        assert_eq!(asked.take(), vec![one.clone(), two.clone()]);
        assert_eq!(take(&executed, &none), first, "the seal reads the carry's");
        assert!(asked.take().is_empty(), "and computes none of them");
        let read = [(two.clone(), BTreeSet::from([String::from("f")]))].into();
        let moved = take(&executed, &read);
        assert_eq!(asked.take(), vec![two.clone()], "its reads moved");
        assert_eq!(moved[&one], first[&one]);
        assert_ne!(moved[&two], first[&two]);
    }

    /// No dependencies beyond a case's own text and `probes`: no names, no
    /// items, no case traced, no resources.
    fn depends(probes: &[String]) -> Depends<'_> {
        static ITEMS: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        static READ: std::collections::BTreeMap<Case, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        static IDS: std::collections::BTreeMap<String, String> = std::collections::BTreeMap::new();
        Depends {
            probes,
            names: &[],
            items: &ITEMS,
            mentions: &ITEMS,
            read: &READ,
            resources: &IDS,
            untraced: "",
            compiled: &NO_COMPILED,
            derived: None,
        }
    }

    /// An item added moves no case, and an item edited moves exactly the cases
    /// whose executed functions name it, a name a format string captures
    /// included.
    ///
    /// Fails by: a tree-wide skeleton in every key (the added item moves all
    /// three), a const read by no name (its edit moves nothing), or a captured
    /// `"{OTHER}"` missed.
    #[test]
    fn an_added_item_moves_no_case_and_an_edited_one_moves_the_cases_naming_it() {
        let root = crate::scratch::scratch("schema-item-digests");
        let dirs = std::collections::BTreeMap::new();
        let (a, b, c, d) = (case("a"), case("b"), case("c"), case("d"));
        let cases: BTreeSet<Case> = [a.clone(), b.clone(), c.clone(), d.clone()].into();
        let executed = [
            (a.clone(), [0].into()),
            (b.clone(), [1].into()),
            (c.clone(), [2].into()),
            (d.clone(), [3].into()),
        ]
        .into();
        let base = "const LIMIT: u8 = 1;\nconst OTHER: u8 = 2;\n\
                    pub fn uses_limit() -> u8 { LIMIT }\n\
                    pub fn uses_format() -> String { format!(\"{OTHER}\") }\n\
                    pub fn plain() -> u8 { 3 }\n\
                    pub const fn seed() -> u8 { 11 }\nconst CHAIN: u8 = seed();\n\
                    pub fn uses_chain() -> u8 { CHAIN }\n";
        let digests = |source: &str| {
            let rendered = render(source, &[], &BTreeSet::new(), Some(0));
            let mut items: std::collections::BTreeMap<String, BTreeSet<String>> =
                std::collections::BTreeMap::new();
            for (name, digest) in &rendered.items {
                items
                    .entry(name.clone())
                    .or_default()
                    .insert(digest.clone());
            }
            let mut mentions: std::collections::BTreeMap<String, BTreeSet<String>> =
                std::collections::BTreeMap::new();
            for (name, mentioned) in &rendered.mentions {
                mentions
                    .entry(name.clone())
                    .or_default()
                    .extend(mentioned.iter().cloned());
            }
            let depends = Depends {
                names: &rendered.names,
                items: &items,
                mentions: &mentions,
                ..depends(&rendered.probes)
            };
            case_digests(&root, &cases, &dirs, &executed, &depends)
        };
        let held = digests(base);
        let added = digests(&format!(
            "{base}pub fn added() -> u8 {{ 4 }}\nconst NEW: u8 = 5;\n"
        ));
        assert_eq!(added, held, "an added function and const move no case");
        let limit = digests(&base.replace("LIMIT: u8 = 1", "LIMIT: u8 = 9"));
        assert_ne!(limit[&a], held[&a], "a names LIMIT");
        assert_eq!(
            (limit[&b].clone(), limit[&c].clone()),
            (held[&b].clone(), held[&c].clone())
        );
        let other = digests(&base.replace("OTHER: u8 = 2", "OTHER: u8 = 9"));
        assert_ne!(other[&b], held[&b], "b captures OTHER in a format string");
        assert_eq!(
            (other[&a].clone(), other[&c].clone()),
            (held[&a].clone(), held[&c].clone())
        );
        let seeded = digests(&base.replace("{ 11 }", "{ 12 }"));
        assert_ne!(
            seeded[&d], held[&d],
            "d names CHAIN, whose value seed() makes"
        );
        assert_eq!(
            (seeded[&a].clone(), seeded[&b].clone(), seeded[&c].clone()),
            (held[&a].clone(), held[&b].clone(), held[&c].clone())
        );
    }

    /// Each case's digest over one rendered `source`, its items and mentions
    /// aggregated by name as the schema aggregates them, each case running
    /// the probe ids `executed` gives it.
    fn source_digests(
        cases: &BTreeSet<Case>,
        executed: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
        source: &str,
    ) -> std::collections::BTreeMap<Case, String> {
        let root = crate::scratch::scratch("schema-source-digests");
        let rendered = render(source, &[], &BTreeSet::new(), Some(0));
        let mut items: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, digest) in &rendered.items {
            items
                .entry(name.clone())
                .or_default()
                .insert(digest.clone());
        }
        let mut mentions: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, mentioned) in &rendered.mentions {
            mentions
                .entry(name.clone())
                .or_default()
                .extend(mentioned.iter().cloned());
        }
        let depends = Depends {
            names: &rendered.names,
            items: &items,
            mentions: &mentions,
            compiled: &rendered.compiled,
            derived: None,
            ..depends(&rendered.probes)
        };
        case_digests(
            &root,
            cases,
            &std::collections::BTreeMap::new(),
            executed,
            &depends,
        )
    }

    /// T1 (CLOUD-2904): an impl, a `use` or an item macro added moves the
    /// cases naming what it binds and no other. 304fa50b added
    /// `impl Known { fn of(..) }`; answering to its whole text, it joined the
    /// items of `String` and every case moved, so a census rerun reused 0.
    ///
    /// Fails by: an impl answering to its member bodies, a `use` to the path
    /// it imports from, or an item macro to the type and initialiser of what
    /// it binds (the first case moves); or any of them answering to nothing
    /// (the naming case holds).
    #[test]
    fn an_added_impl_use_or_item_macro_moves_only_the_cases_naming_what_it_binds() {
        let (plain, known, set, seen) = (case("plain"), case("known"), case("set"), case("seen"));
        let cases: BTreeSet<Case> =
            [plain.clone(), known.clone(), set.clone(), seen.clone()].into();
        let executed = [
            (plain.clone(), [0].into()),
            (known.clone(), [1].into()),
            (set.clone(), [2].into()),
            (seen.clone(), [3].into()),
        ]
        .into();
        let base = "pub fn plain(s: String) -> BTreeSet<String> { BTreeSet::from([s]) }\n\
                    pub fn names_known() -> usize { size_of::<Known>() }\n\
                    pub fn names_set() -> usize { size_of::<Set<u8>>() }\n\
                    pub fn names_seen() -> usize { SEEN.with(String::len) }\n";
        let held = source_digests(&cases, &executed, base);
        for (added, naming) in [
            (
                "impl Known { fn of(x: u32) -> String { x.to_string() } }\n",
                &known,
            ),
            ("use std::collections::BTreeSet as Set;\n", &set),
            (
                "thread_local! { static SEEN: String = String::new(); }\n",
                &seen,
            ),
        ] {
            let moved = source_digests(&cases, &executed, &format!("{base}{added}"));
            assert_eq!(
                moved[&plain], held[&plain],
                "names String and BTreeSet: {added}"
            );
            assert_ne!(moved[naming], held[naming], "names what it binds: {added}");
        }
    }

    /// T2 (CLOUD-2904, CLOUD-2927): a name is followed through the one
    /// definition its module says it names, so an edit one hop on moves the
    /// case naming it: `S` is a struct and an impl, the struct is its one
    /// definition in the module naming it, and an edit to the `C` the struct
    /// names moves the case naming `S`.
    ///
    /// Fails by: the one definition keyed but not followed (`C`'s or `B`'s
    /// edit reuses a stale verdict), or a definition dropped (a field added to
    /// `S` moves nothing).
    #[test]
    fn a_name_is_followed_through_one_definition_and_keyed_on_several() {
        let (f, g) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [f.clone(), g.clone()].into();
        let executed = [(f.clone(), [0].into()), (g.clone(), [1].into())].into();
        let base = "const A: u32 = B;\nconst B: u32 = 1;\n\
                    struct S { c: C }\nimpl S { const K: u32 = 0; }\nstruct C(u32);\n\
                    fn f() -> u32 { A }\nfn g(s: S) -> S { s }\n";
        let held = source_digests(&cases, &executed, base);
        let hop = source_digests(&cases, &executed, &base.replace("B: u32 = 1", "B: u32 = 9"));
        assert_ne!(hop[&f], held[&f], "A's one definition names B");
        let beyond = source_digests(&cases, &executed, &base.replace("C(u32)", "C(u64)"));
        // THE ONE DEFINITION ITS MODULE SAYS IS FOLLOWED (CLOUD-2927); a
        // name no path narrows is keyed on all and followed through none
        // ([`an_unresolved_mention_is_keyed_on_every_definition_and_followed_through_none`]).
        assert_ne!(
            beyond[&g], held[&g],
            "S's impl is no definition of S: its one struct is followed to C"
        );
        let own = source_digests(
            &cases,
            &executed,
            &base.replace("struct S { c: C }", "struct S { c: C, d: u8 }"),
        );
        assert_ne!(own[&g], held[&g], "keyed on S's own definitions");
    }

    /// CLOUD-2927 (a): a mention narrows through its module's `use` to the
    /// one definition it imports, and follows that one: two `Schema`s in two
    /// modules, each imported by one case's module, and an edit to either
    /// moves only the case importing it, an edit one hop on (the `C` the
    /// imported `Schema` names) included.
    ///
    /// Fails by: a mention resolved by its spelling alone, so an edit to
    /// `b`'s `Schema` moves the case importing `a`'s; or the imported
    /// definition keyed and not followed, so `C`'s edit reuses a stale verdict.
    #[test]
    fn a_mention_follows_the_one_definition_its_module_imports() {
        let (f, g) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [f.clone(), g.clone()].into();
        let executed = [(f.clone(), [0].into()), (g.clone(), [1].into())].into();
        let base = "mod a { pub struct C(pub u8); pub struct Schema { pub x: C } }\n\
                    mod b { pub struct Schema { pub y: u8 } }\n\
                    mod c { use super::a::Schema; pub fn f(s: Schema) -> u8 { s.x.0 } }\n\
                    mod d { use super::b::{Schema}; pub fn g(s: Schema) -> u8 { s.y } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(&cases, &executed, &base.replace("pub y: u8", "pub y: u16"));
        assert_eq!(other[&f], held[&f], "f imports a's Schema, not b's");
        assert_ne!(other[&g], held[&g], "g imports b's");
        let own = source_digests(
            &cases,
            &executed,
            &base.replace("pub x: C", "pub x: C, pub z: u8"),
        );
        assert_ne!(own[&f], held[&f], "f imports a's Schema");
        assert_eq!(own[&g], held[&g], "g does not");
        let hop = source_digests(&cases, &executed, &base.replace("C(pub u8)", "C(pub u16)"));
        assert_ne!(
            hop[&f], held[&f],
            "the one Schema f imports is followed to C"
        );
    }

    /// [`source_digests`] over several files, each rendered at its own scope
    /// ([`FileScope::of`]) with its probes numbered after the last file's, and
    /// `crates` recorded by name as [`write_schema`] records them.
    fn files_digests(
        cases: &BTreeSet<Case>,
        executed: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
        files: &[(&str, &str)],
        crates: &[(&str, &str)],
    ) -> std::collections::BTreeMap<Case, String> {
        let root = crate::scratch::scratch("schema-files-digests");
        let mut probes: Vec<String> = Vec::new();
        let mut names: Vec<BTreeSet<String>> = Vec::new();
        let mut compiled = Compiled::default();
        let mut items: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        let mut mentions: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (file, source) in files {
            let first = probes.len();
            let rendered = render_in(
                source,
                &[],
                &BTreeSet::new(),
                Some(first),
                &FileScope::of(file),
            );
            compiled.fold(&rendered.compiled, first);
            probes.extend(rendered.probes.iter().cloned());
            names.extend(rendered.names.iter().cloned());
            for (name, digest) in &rendered.items {
                items
                    .entry(name.clone())
                    .or_default()
                    .insert(digest.clone());
            }
            for (name, mentioned) in &rendered.mentions {
                mentions
                    .entry(name.clone())
                    .or_default()
                    .extend(mentioned.iter().cloned());
            }
        }
        for (name, dir) in crates {
            items
                .entry(format!("{CRATE_NAMED}{name}"))
                .or_default()
                .insert(format!("dir:{dir}"));
        }
        let depends = Depends {
            names: &names,
            items: &items,
            mentions: &mentions,
            compiled: &compiled,
            derived: None,
            ..depends(&probes)
        };
        case_digests(
            &root,
            cases,
            &std::collections::BTreeMap::new(),
            executed,
            &depends,
        )
    }

    /// CLOUD-2927 (c): a path resolves segment by segment to the one
    /// definition it names: through another workspace crate by name, a `use`
    /// of a module, and a glob beside an external crate's; and a path through
    /// a type names no free item.
    ///
    /// Fails by: any of these keyed on every `Schema` (or every `schema`) by
    /// spelling, so an edit to the other moves the case, or a path through
    /// the type `Holder` read as unknown, so the free `SCHEMA`'s edit does.
    #[test]
    fn a_path_resolves_through_crates_uses_and_globs_to_its_one_definition() {
        let cases_of =
            |names: &[&str]| -> BTreeSet<Case> { names.iter().map(|n| case(n)).collect() };
        let (by_path, by_other, by_use, by_type, by_glob) =
            (case("f"), case("g"), case("h"), case("k"), case("w"));
        let cases = cases_of(&["f", "g", "h", "k", "w"]);
        let executed = [
            (by_path.clone(), [0].into()),
            (by_other.clone(), [1].into()),
            (by_use.clone(), [2].into()),
            (by_type.clone(), [3].into()),
            (by_glob.clone(), [4].into()),
        ]
        .into();
        let core = "pub mod a { pub struct Schema { pub x: u8 } }\n\
                    pub mod b { pub struct Schema { pub y: u8 } }\n";
        let app = "use core_x::a;\n\
                   pub fn f(s: core_x::a::Schema) -> u8 { s.x }\n\
                   pub fn g(s: core_x::b::Schema) -> u8 { s.y }\n\
                   pub fn h(s: a::Schema) -> u8 { s.x }\n\
                   pub struct Holder;\npub const SCHEMA: u8 = 1;\n\
                   pub fn k() -> u8 { Holder::SCHEMA }\n\
                   pub mod sch { pub struct Schema { pub z: u8 } }\n\
                   mod e { use ext::*; use super::sch::*; pub fn w(s: Schema) -> u8 { s.z } }\n";
        let digests = |core: &str, app: &str| {
            files_digests(
                &cases,
                &executed,
                &[
                    ("crates/core/src/lib.rs", core),
                    ("crates/app/src/lib.rs", app),
                ],
                &[("core_x", "crates/core"), ("app", "crates/app")],
            )
        };
        let held = digests(core, app);
        let other = digests(&core.replace("pub y: u8", "pub y: u16"), app);
        assert_ne!(
            other[&by_other], held[&by_other],
            "g names core_x::b::Schema"
        );
        for (named, by) in [
            (&by_path, "core_x::a::"),
            (&by_use, "a use of core_x::a"),
            (&by_glob, "the sch glob"),
        ] {
            assert_eq!(
                other[named], held[named],
                "{by} names a Schema other than b's"
            );
        }
        let own = digests(&core.replace("pub x: u8", "pub x: u16"), app);
        assert_ne!(own[&by_path], held[&by_path], "f names core_x::a::Schema");
        assert_ne!(
            own[&by_use], held[&by_use],
            "h names it through a use of its module"
        );
        let free = digests(core, &app.replace("SCHEMA: u8 = 1", "SCHEMA: u8 = 2"));
        assert_eq!(
            free[&by_type], held[&by_type],
            "Holder::SCHEMA names no free SCHEMA"
        );
    }

    /// A workspace crate is named by a path's FIRST segment alone, as the
    /// extern prelude is reached: after `self::`, or past a module, the same
    /// name is no crate, so `self::core_x::a::Schema` names nothing of
    /// `core_x`'s while `core_x::a::Schema` does.
    ///
    /// Fails by: any segment a lookup misses read as a crate name (bootstrap
    /// shard 7/8 at 34c6e4d1f survived `index == 0 && relative` as `true` in
    /// `Resolver::path`), so an edit to that crate moves a case it never ran.
    #[test]
    fn a_crate_is_named_by_a_paths_first_segment_alone() {
        let (by_crate, by_self) = (case("f"), case("q"));
        let cases: BTreeSet<Case> = [by_crate.clone(), by_self.clone()].into();
        let executed = [
            (by_crate.clone(), [0].into()),
            (by_self.clone(), [1].into()),
        ]
        .into();
        let core = "pub mod a { pub struct Schema { pub x: u8 } }\n";
        let app = "pub fn f(s: core_x::a::Schema) -> u8 { 0 }\n\
                   pub fn q(s: self::core_x::a::Schema) -> u8 { 0 }\n";
        let digests = |core: &str| {
            files_digests(
                &cases,
                &executed,
                &[
                    ("crates/core/src/lib.rs", core),
                    ("crates/app/src/lib.rs", app),
                ],
                &[("core_x", "crates/core"), ("app", "crates/app")],
            )
        };
        let held = digests(core);
        let edited = digests(&core.replace("pub x: u8", "pub x: u16"));
        assert_ne!(
            edited[&by_crate], held[&by_crate],
            "the premise: core_x::a::Schema is core_x's"
        );
        assert_eq!(
            edited[&by_self], held[&by_self],
            "self::core_x names no crate"
        );
    }

    /// CLOUD-2927 (d): an impl is keyed for the type it is written for, as a
    /// path resolves its self type: an edit to `b::Schema`'s impl moves no
    /// case naming `a::Schema`, and one to `a::Schema`'s does.
    ///
    /// Fails by: every impl of a name keyed by spelling (the first edit moves
    /// `f`), or an impl dropped where its self type is the one named (the
    /// second does not).
    #[test]
    fn an_impl_is_keyed_for_the_type_its_self_type_names() {
        let named = case("f");
        let cases: BTreeSet<Case> = [named.clone()].into();
        let executed = [(named.clone(), [0].into())].into();
        let base = "mod a { pub struct Schema; impl Schema {} }\n\
                    mod b { pub struct Schema; impl Schema {} }\n\
                    mod c { use super::a::Schema; pub fn f(s: Schema) -> u8 { 0 } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(
            &cases,
            &executed,
            &base.replace(
                "mod b { pub struct Schema; impl Schema {} }",
                "mod b { pub struct Schema; impl<'x> Schema {} }",
            ),
        );
        assert_eq!(other[&named], held[&named], "b's impl is b::Schema's");
        let own = source_digests(
            &cases,
            &executed,
            &base.replace(
                "mod a { pub struct Schema; impl Schema {} }",
                "mod a { pub struct Schema; impl<'x> Schema {} }",
            ),
        );
        assert_ne!(own[&named], held[&named], "a's impl is the Schema f names");
    }

    /// CLOUD-2927 (e): a type-qualified associated name is keyed on the
    /// members of its type's impls, and a trait-qualified one on those of its
    /// trait's: `Schema::K` with `a::Schema` in scope is not `b::Schema::K`,
    /// and `<Schema as Tr>::L` is no other trait's `L`.
    ///
    /// Fails by: an associated name matched by spelling, so an edit to
    /// `b::Schema`'s `K` or to `Other`'s `L` moves a case naming neither; or
    /// the member it names dropped.
    #[test]
    fn a_qualified_associated_name_is_keyed_on_its_owners_members() {
        let (inherent, traited) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [inherent.clone(), traited.clone()].into();
        let executed = [
            (inherent.clone(), [0].into()),
            (traited.clone(), [1].into()),
        ]
        .into();
        let base = "mod t { pub trait Tr { const L: u8; } pub trait Other { const L: u8; } }\n\
                    mod a { pub struct Schema; impl Schema { pub const K: u8 = 1; } \
                    impl super::t::Tr for Schema { const L: u8 = 1; } }\n\
                    mod b { pub struct Schema; impl Schema { pub const K: u8 = 2; } \
                    impl super::t::Other for Schema { const L: u8 = 7; } }\n\
                    mod c { use super::a::Schema; pub fn f() -> u8 { Schema::K } \
                    pub fn g() -> u8 { <Schema as super::t::Tr>::L } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(&cases, &executed, &base.replace("K: u8 = 2", "K: u8 = 3"));
        assert_eq!(
            other[&inherent], held[&inherent],
            "b::Schema's K is not a::Schema's"
        );
        let own = source_digests(&cases, &executed, &base.replace("K: u8 = 1", "K: u8 = 4"));
        assert_ne!(
            own[&inherent], held[&inherent],
            "a::Schema's K is the one named"
        );
        let unrelated = source_digests(&cases, &executed, &base.replace("L: u8 = 7", "L: u8 = 8"));
        assert_eq!(
            unrelated[&traited], held[&traited],
            "b::Schema's Other::L is not a::Schema's Tr::L"
        );
        let named = source_digests(&cases, &executed, &base.replace("L: u8 = 1", "L: u8 = 5"));
        assert_ne!(
            named[&traited], held[&traited],
            "an impl of Tr's L is named"
        );
    }

    /// CLOUD-2927 (f): a name handed to a workspace `macro_rules!` that puts it
    /// where it is called resolves there, a `::` before anything but a `$`
    /// in its body included; one handed to a macro that pastes it after a
    /// `::` of its own is keyed on every definition it sees.
    ///
    /// Fails by: every non-std macro's tokens read as unknown, or any `::`
    /// in a body read as pasting (a mutant missed at 82e566618: `!=` for
    /// `==` before `DOLLAR` in [`macro_passes`]), so an edit to `b::LIMIT`
    /// moves the case handing `a::LIMIT` to `wrap!`; or a pasting macro's
    /// read as passing (the same edit leaves `qual!`'s case on a stale
    /// verdict).
    #[test]
    fn a_name_a_workspace_macro_passes_through_resolves_where_it_is_called() {
        let (wrapped, qualified) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [wrapped.clone(), qualified.clone()].into();
        let executed = [
            (wrapped.clone(), [0].into()),
            (qualified.clone(), [1].into()),
        ]
        .into();
        let base = "macro_rules! wrap { ($e:expr) => { core::convert::identity($e) } }\n\
                    macro_rules! qual { ($n:ident) => { crate::b::$n } }\n\
                    mod a { pub const LIMIT: u8 = 1; }\n\
                    mod b { pub const LIMIT: u8 = 2; }\n\
                    mod c { use super::a::LIMIT; pub fn f() -> u8 { wrap!(LIMIT) } \
                    pub fn g() -> u8 { qual!(LIMIT) } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 2", "LIMIT: u8 = 3"),
        );
        assert_eq!(
            other[&wrapped], held[&wrapped],
            "wrap! puts LIMIT where c imports a's"
        );
        assert_ne!(
            other[&qualified], held[&qualified],
            "qual! puts it under a path of its own"
        );
        let own = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 1", "LIMIT: u8 = 4"),
        );
        assert_ne!(
            own[&wrapped], held[&wrapped],
            "a::LIMIT is the one wrap! is handed"
        );
    }

    /// CLOUD-2927 (g): a path resolves through what its spelling adds:
    /// generic arguments (`W::<u8>::K`), a renamed `use` (`Alias` of
    /// `use super::a::W as Alias`), `Self` in an impl, and a leading `::`,
    /// which names an external crate's root.
    ///
    /// Fails by: any of these read as unknown, so an edit to `b`'s `K` (or
    /// to `a`'s `LIMIT`, for `::ext::LIMIT`) moves a case naming none of
    /// them; or the one named dropped.
    #[test]
    fn a_path_resolves_through_generics_renames_self_and_a_leading_root() {
        let (in_impl, generic, renamed, external) = (case("m"), case("f"), case("g"), case("k"));
        let cases: BTreeSet<Case> = [
            in_impl.clone(),
            generic.clone(),
            renamed.clone(),
            external.clone(),
        ]
        .into();
        let executed = [
            (in_impl.clone(), [0].into()),
            (generic.clone(), [1].into()),
            (renamed.clone(), [2].into()),
            (external.clone(), [3].into()),
        ]
        .into();
        let base = "mod a { pub struct W<T>(T); \
                    impl<T> W<T> { pub const K: u8 = 1; pub fn m() -> u8 { Self::K } } \
                    pub const LIMIT: u8 = 5; }\n\
                    mod b { pub struct W<T>(T); impl<T> W<T> { pub const K: u8 = 2; } }\n\
                    mod c { use super::a::W; pub fn f() -> u8 { W::<u8>::K } }\n\
                    mod d { use super::a::W as Alias; pub fn g() -> u8 { Alias::<u8>::K } }\n\
                    mod e { pub fn k() -> u8 { ::ext::LIMIT } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(&cases, &executed, &base.replace("K: u8 = 2", "K: u8 = 3"));
        for (named, by) in [
            (&in_impl, "Self"),
            (&generic, "W::<u8>"),
            (&renamed, "Alias"),
        ] {
            assert_eq!(other[named], held[named], "{by} is a::W, not b::W");
        }
        let own = source_digests(&cases, &executed, &base.replace("K: u8 = 1", "K: u8 = 4"));
        for (named, by) in [
            (&in_impl, "Self"),
            (&generic, "W::<u8>"),
            (&renamed, "Alias"),
        ] {
            assert_ne!(own[named], held[named], "{by} names a::W's K");
        }
        let limit = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 5", "LIMIT: u8 = 6"),
        );
        assert_eq!(
            limit[&external], held[&external],
            "::ext::LIMIT is no workspace LIMIT"
        );
    }

    /// A leading `::` before a WORKSPACE crate's name resolves in that crate,
    /// and a `self::` path from the module it is written in (CLOUD-2789).
    ///
    /// Fails by: `::core_x::a::Schema` read as unknown (so an edit to
    /// `core_x::b::Schema`, or to the app's own `a::Schema`, moves `f`), or
    /// `self::a::Schema` not resolved from `c` (so an edit to `c::a::Schema`
    /// leaves `g` on a stale verdict, or one to the app's top `a::Schema`
    /// moves it).
    #[test]
    fn a_leading_root_crate_and_a_self_path_resolve_to_their_one_definition() {
        let (rooted, selfed) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [rooted.clone(), selfed.clone()].into();
        let executed = [(rooted.clone(), [0].into()), (selfed.clone(), [1].into())].into();
        let core = "pub mod a { pub struct Schema { pub x: u8 } }\n\
                    pub mod b { pub struct Schema { pub y: u8 } }\n";
        let app = "pub mod a { pub struct Schema { pub q: u8 } }\n\
                   pub fn f(s: ::core_x::a::Schema) -> u8 { s.x }\n\
                   pub mod c { pub mod a { pub struct Schema { pub z: u8 } } \
                   pub fn g(s: self::a::Schema) -> u8 { s.z } }\n";
        let digests = |core: &str, app: &str| {
            files_digests(
                &cases,
                &executed,
                &[
                    ("crates/core/src/lib.rs", core),
                    ("crates/app/src/lib.rs", app),
                ],
                &[("core_x", "crates/core"), ("app", "crates/app")],
            )
        };
        let held = digests(core, app);
        let other = digests(&core.replace("pub y: u8", "pub y: u16"), app);
        assert_eq!(
            other[&rooted], held[&rooted],
            "::core_x::a is not core_x::b"
        );
        let top = digests(core, &app.replace("pub q: u8", "pub q: u16"));
        assert_eq!(
            top[&rooted], held[&rooted],
            "::core_x::a is not the app's a"
        );
        assert_eq!(
            top[&selfed], held[&selfed],
            "self::a in c is not the app's a"
        );
        let own = digests(&core.replace("pub x: u8", "pub x: u16"), app);
        assert_ne!(own[&rooted], held[&rooted], "f names core_x::a::Schema");
        let inner = digests(core, &app.replace("pub z: u8", "pub z: u16"));
        assert_ne!(inner[&selfed], held[&selfed], "g names c::a::Schema");
    }

    /// CLOUD-2927 (h): an item in a block is named from inside the block
    /// alone: a `const` block's own `LIMIT` answers the mention in it, and a
    /// mention outside the block resolves past it to the `LIMIT` its module
    /// imports.
    ///
    /// Fails by: a block's item read as having no home, so every `LIMIT` its
    /// module mentions is keyed on all of them (an edit to `b::LIMIT` moves
    /// `g`); or the block's own item not the one its block names.
    #[test]
    fn an_item_in_a_block_is_named_from_inside_its_block_alone() {
        let (through_value, outside, through_more) = (case("f"), case("g"), case("h"));
        let cases: BTreeSet<Case> =
            [through_value.clone(), outside.clone(), through_more.clone()].into();
        let executed = [
            (through_value.clone(), [0].into()),
            (outside.clone(), [1].into()),
            (through_more.clone(), [2].into()),
        ]
        .into();
        let base = "mod a { pub const LIMIT: u8 = 1; }\n\
                    mod b { pub const LIMIT: u8 = 2; }\n\
                    mod c { use super::a::LIMIT; \
                    pub const VALUE: u8 = { const LIMIT: u8 = 9; LIMIT }; \
                    pub const MORE: u8 = { const X: u8 = 1; X + LIMIT }; \
                    pub fn f() -> u8 { VALUE } pub fn g() -> u8 { LIMIT } \
                    pub fn h() -> u8 { MORE } }\n";
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 2", "LIMIT: u8 = 3"),
        );
        assert_eq!(other[&outside], held[&outside], "g names a::LIMIT");
        assert_eq!(
            other[&through_value], held[&through_value],
            "VALUE names its own LIMIT"
        );
        let own = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 9", "LIMIT: u8 = 8"),
        );
        assert_ne!(
            own[&through_value], held[&through_value],
            "the block's LIMIT is VALUE's"
        );
        let imported = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 1", "LIMIT: u8 = 4"),
        );
        assert_ne!(
            imported[&outside], held[&outside],
            "a::LIMIT is the one g names"
        );
        assert_ne!(
            imported[&through_more], held[&through_more],
            "MORE's block names its X and, past it, a::LIMIT"
        );
        assert_eq!(
            other[&through_more], held[&through_more],
            "and not b::LIMIT"
        );
    }

    /// CLOUD-2927: a renamed `use` of a module goes on in that module, and a
    /// chain of `use`s past the resolution depth is unknown, keyed on every
    /// definition it sees rather than resolved to a guess.
    ///
    /// Fails by: an alias read as a module of its own name (`alias::LIMIT`
    /// looked up in `a::alias`, which holds nothing, so an edit to
    /// `a::inner::LIMIT` reuses a stale verdict); or a chain past the depth
    /// resolved (a mutant missed at 82e566618: `depth - 1` in
    /// [`Resolver::module_of`], so an edit to `z::S` leaves `deep` stale).
    #[test]
    fn a_renamed_module_goes_on_in_its_module_and_a_deep_chain_is_unknown() {
        let (aliased, deep) = (case("f"), case("g"));
        let cases: BTreeSet<Case> = [aliased.clone(), deep.clone()].into();
        let executed = [(aliased.clone(), [0].into()), (deep.clone(), [1].into())].into();
        let mut chain = String::from(
            "mod m19 { pub mod inner { pub struct S; } pub use self::inner as next; }\n",
        );
        chain.extend((0..19).rev().map(|hop| {
            format!(
                "mod m{hop} {{ pub use super::m{}::next as next; }}\n",
                hop + 1
            )
        }));
        let base = format!(
            "mod a {{ pub mod inner {{ pub const LIMIT: u8 = 1; }} }}\n\
             mod b {{ pub const LIMIT: u8 = 2; }}\n\
             mod z {{ pub struct S; }}\n{chain}\
             mod c {{ use super::a::inner as alias; pub fn f() -> u8 {{ alias::LIMIT }} \
             pub fn g(s: super::m0::next::S) -> u8 {{ 0 }} }}\n"
        );
        let held = source_digests(&cases, &executed, &base);
        let own = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 1", "LIMIT: u8 = 3"),
        );
        assert_ne!(
            own[&aliased], held[&aliased],
            "alias is a::inner, whose LIMIT f names"
        );
        let other = source_digests(
            &cases,
            &executed,
            &base.replace("LIMIT: u8 = 2", "LIMIT: u8 = 4"),
        );
        assert_eq!(other[&aliased], held[&aliased], "and not b's");
        let unrelated = source_digests(
            &cases,
            &executed,
            &base.replace("mod z { pub struct S; }", "mod z { pub struct S(u8); }"),
        );
        assert_ne!(
            unrelated[&deep], held[&deep],
            "twenty hops of `use` is past the depth: every S is keyed"
        );
    }

    /// CLOUD-2927 (b): a mention no path narrows to one definition is keyed on
    /// every definition it sees and followed through none (owner ruling
    /// 2026-11-24): handed to a macro the workspace does not define, whose
    /// expansion no source read says, and in a module whose two `use`s each
    /// import a `Schema`.
    ///
    /// Fails by: a name in an unknown macro's tokens resolved, or two `use`s of one name
    /// narrowed to either, so an edit to the other `Schema` reuses a stale
    /// verdict; or an ambiguous mention followed, so `C`'s edit moves a case
    /// no path says names it.
    #[test]
    fn an_unresolved_mention_is_keyed_on_every_definition_and_followed_through_none() {
        let (h, k) = (case("h"), case("k"));
        let cases: BTreeSet<Case> = [h.clone(), k.clone()].into();
        let executed = [(h.clone(), [0].into()), (k.clone(), [1].into())].into();
        let base = "mod a { pub struct C(pub u8); pub struct Schema { pub x: C } }\n\
                    mod b { pub struct Schema { pub y: u8 } }\n\
                    mod e { pub fn h() -> u8 { ext_mac!(Schema) } }\n\
                    mod m { #[cfg(test)] use super::a::Schema; \
                    #[cfg(not(test))] use super::b::Schema; pub fn k(s: Schema) -> u8 { 0 } }\n";
        let held = source_digests(&cases, &executed, base);
        for (edit, from) in [
            ("pub x: C", "pub x: C, pub z: u8"),
            ("pub y: u8", "pub y: u16"),
        ] {
            let moved = source_digests(&cases, &executed, &base.replace(edit, from));
            assert_ne!(
                moved[&h], held[&h],
                "no source says where ext_mac! puts it: {from}"
            );
            assert_ne!(moved[&k], held[&k], "k's two uses import both: {from}");
        }
        let hop = source_digests(&cases, &executed, &base.replace("C(pub u8)", "C(pub u16)"));
        assert_eq!(
            hop[&h], held[&h],
            "keyed on every Schema, followed through none"
        );
        assert_eq!(
            hop[&k], held[&k],
            "keyed on every Schema, followed through none"
        );
    }

    /// T3 (CLOUD-2904): a `//!` edit at a file's head moves no case key, and
    /// neither does a whitespace edit; a `///` edit on a derived struct a probed
    /// function names moves that function's case, since derives compile outer
    /// doc text into run-time text (schemars descriptions, clap help).
    ///
    /// Fails by: an inner doc comment hashed into the `""` item every case
    /// carries (one word of a module doc moves every key in the sweep), an
    /// outer one skipped (a changed `--help` or schema description reuses a
    /// stale verdict), or whitespace hashed.
    #[test]
    fn a_module_doc_edit_moves_no_case_key_and_an_item_doc_edit_moves_its_cases() {
        let (names_s, plain) = (case("names_s"), case("plain"));
        let cases: BTreeSet<Case> = [names_s.clone(), plain.clone()].into();
        let executed = [(names_s.clone(), [0].into()), (plain.clone(), [1].into())].into();
        let base = "//! The module.\n#[derive(Parser)]\n/// The struct.\npub struct S;\n\
                    pub fn names_s() -> S { S }\npub fn plain() -> u8 { 3 }\n";
        let held = source_digests(&cases, &executed, base);
        let module = source_digests(&cases, &executed, &base.replace("The module", "A module"));
        assert_eq!(module, held, "a `//!` edit moves no case");
        let spaced = source_digests(
            &cases,
            &executed,
            &base.replace("pub struct S;", "pub  struct S ;"),
        );
        assert_eq!(spaced, held, "a whitespace edit moves no case");
        let item = source_digests(&cases, &executed, &base.replace("The struct", "A struct"));
        assert_ne!(
            item[&names_s], held[&names_s],
            "a `///` edit moves the case naming S"
        );
        assert_eq!(item[&plain], held[&plain], "and no other");
    }

    /// A module path with the block scopes it ends in dropped: a block's
    /// items resolve `self`, `super` and `crate` from the module around it.
    ///
    /// Fails by: any answer but that module (bootstrap shard 7/8 at
    /// 34c6e4d1f survived `enclosing_module` as `"xyzzy"`).
    #[test]
    fn a_block_scope_resolves_from_its_enclosing_module() {
        assert_eq!(enclosing_module("src::a"), "src::a");
        assert_eq!(enclosing_module("src::a::#f0::#g1"), "src::a");
        assert_eq!(enclosing_module("#f0::#g1"), "", "the crate root's blocks");
        assert_eq!(enclosing_module(""), "");
    }

    /// An item in an unscoped file is keyed by its bare name with no kind
    /// marked: with no home, a `use` binding's key is the name it binds.
    ///
    /// Fails by: a kind marked where there is no home (bootstrap shard 7/8 at
    /// 34c6e4d1f survived `free_keys`' `home.is_empty()` guard as `false`), so
    /// a bare mention of the binding finds no key.
    #[test]
    fn an_unscoped_use_binding_is_keyed_by_its_bare_name() {
        let binding = first_item("use a::b;\n");
        let keys = definitions(&binding, &FileScope::unscoped(), &BTreeSet::new());
        assert!(keys.iter().any(|key| key == "b"), "{keys:?}");
        assert!(
            keys.iter().all(|key| !key.contains(USE_BOUND)),
            "no kind without a home: {keys:?}"
        );
    }

    /// A name a `::` qualifies inside a macro's tokens is unknown, whichever
    /// macro holds it: a std macro passing its tokens through passes the
    /// whole path, which no bare name resolves.
    ///
    /// Fails by: the two-colon spelling of `::` not read as a qualifier
    /// (bootstrap shard 7/8 at 34c6e4d1f survived `||` as `&&` and `==` as
    /// `!=` in `passed_as_written`), so `LIMIT` in `vec![a::LIMIT]` reads as
    /// a bare `LIMIT` where `vec!` is called.
    #[test]
    fn a_qualified_name_in_a_macros_tokens_is_unknown() {
        let root = parsed("fn f() { vec![a::LIMIT, LIMIT]; }\n");
        let named: Vec<ra_ap_syntax::SyntaxToken> = root
            .descendants_with_tokens()
            .filter_map(ra_ap_syntax::NodeOrToken::into_token)
            .filter(|token| token.text() == "LIMIT")
            .collect();
        assert_eq!(named.len(), 2);
        assert_eq!(passed_as_written(&named[0]), format!("{WRITTEN}?"));
        assert_eq!(
            passed_as_written(&named[1]),
            "",
            "the premise: a bare name vec! passes is resolved as written"
        );
    }

    /// The first item of `source`, parsed as the schema parses a file.
    fn first_item(source: &str) -> ast::Item {
        batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
            .tree()
            .syntax()
            .descendants()
            .find_map(ast::Item::cast)
            .expect("an item")
    }

    /// CLOUD-2789: each visibility spelling keys its item where it is
    /// visible: none and `pub(self)` at its module, every restricted `pub(..)`
    /// at its package, `pub` workspace-wide.
    ///
    /// Fails by: `pub(self)` read as a package visibility, or a restricted
    /// form read as private, so a case naming it from a sibling module holds.
    #[test]
    fn each_visibility_spelling_keys_its_item_where_it_is_visible() {
        for (source, visible) in [
            ("fn a() {}", Visible::Module),
            ("pub(self) fn a() {}", Visible::Module),
            ("pub ( self ) fn a() {}", Visible::Module),
            ("pub(crate) fn a() {}", Visible::Package),
            ("pub(super) fn a() {}", Visible::Package),
            ("pub(in crate::m) fn a() {}", Visible::Package),
            ("pub fn a() {}", Visible::Workspace),
        ] {
            assert_eq!(visibility(&first_item(source)), visible, "{source}");
        }
    }

    /// CLOUD-2789: a private item of a module that `include!`s a file is keyed
    /// at its package, since the included text names it from a module its
    /// path does not say; the same item of a module that includes nothing is
    /// keyed at its module.
    ///
    /// Fails by: the widened set ignored, so a case in the included file never
    /// sees the private item it names.
    #[test]
    fn a_private_item_of_an_including_module_is_keyed_at_its_package() {
        let place = FileScope::of("crates/p/src/m.rs");
        let keys = |source: &str| {
            let root = batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
                .tree()
                .syntax()
                .clone();
            let widened = widened_modules(&root, &place);
            let helper = root
                .descendants()
                .filter_map(ast::Item::cast)
                .find(|item| matches!(item, ast::Item::Fn(_)))
                .expect("fn helper");
            definitions(&helper, &place, &widened)
        };
        assert_eq!(
            keys("include!(\"x.rs\");\nfn helper() {}\n"),
            [format!("helper{DEFINED_IN}crates/p")]
        );
        assert_eq!(
            keys("fn helper() {}\n"),
            [format!(
                "helper{DEFINED_IN}crates/p{DEFINED_IN}src::m{HOMED}crates/p{HOMED}src::m"
            )]
        );
    }

    /// CLOUD-2789: only a module held in ANOTHER file at a `#[path]` widens the
    /// module declaring it. A plain `mod other;` is the ordinary module tree,
    /// and an inline `#[path]` module holds its own items: neither compiles
    /// foreign code into the declaring module, so neither widens it.
    ///
    /// Fails by: either half of the `pathed` test alone widening, so every
    /// file declaring a child module keys its private items package-wide.
    #[test]
    fn only_an_out_of_line_path_module_widens_its_declaring_module() {
        let place = FileScope::of("crates/p/src/m.rs");
        let widened = |source: &str| {
            let root = batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
                .tree()
                .syntax()
                .clone();
            widened_modules(&root, &place)
        };
        assert!(widened("mod other;\nfn helper() {}\n").is_empty());
        assert!(widened("#[path = \"x.rs\"]\nmod inner {}\n").is_empty());
        assert_eq!(
            widened("#[path = \"x.rs\"]\nmod other;\n"),
            BTreeSet::from([String::from("src::m")])
        );
    }

    /// CLOUD-2789: a file directly in `tests/`, `examples/` or `benches/` is a
    /// crate root, scoped at that directory: the parent of the scope of a
    /// `common/mod.rs` beside it, as a `src/` file's own module is its stem.
    ///
    /// Fails by: such a root scoped under its own stem, a sibling of
    /// `common`'s scope rather than its parent.
    #[test]
    fn a_test_crate_root_is_scoped_at_its_directory() {
        for dir in ["tests", "examples", "benches"] {
            let root = FileScope::of(&format!("crates/p/{dir}/it.rs"));
            let common = FileScope::of(&format!("crates/p/{dir}/common/mod.rs"));
            assert_eq!(root.module_at(None), dir);
            assert_eq!(common.module_at(None), format!("{dir}::common"));
        }
        assert_eq!(FileScope::of("crates/p/src/m.rs").module_at(None), "src::m");
    }

    /// CLOUD-2789: a name in a string or in a macro's token tree is in an
    /// associated position, since neither is parsed into paths and either may
    /// name a method; a name a `let` binds is not.
    ///
    /// Fails by: only a string inside a token tree counted, so a method
    /// named in `m!(x.here())` or a format capture outside one is missed.
    #[test]
    fn a_string_or_a_token_tree_is_an_associated_position() {
        let token = |source: &str, hit: &dyn Fn(&ra_ap_syntax::SyntaxToken) -> bool| {
            batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
                .tree()
                .syntax()
                .descendants_with_tokens()
                .filter_map(ra_ap_syntax::NodeOrToken::into_token)
                .find(|t| hit(t))
                .expect("the token")
        };
        let named = |t: &ra_ap_syntax::SyntaxToken| t.text() == "here";
        let string = |t: &ra_ap_syntax::SyntaxToken| t.kind() == SyntaxKind::STRING;
        assert!(associated_position(&token(
            "fn f() { m!(x.here()); }",
            &named
        )));
        assert!(associated_position(&token(
            "fn f() { let s = \"{here}\"; }",
            &string
        )));
        assert!(!associated_position(&token(
            "fn f() { let here = 1; }",
            &named
        )));
    }

    /// CLOUD-2789: a case directory's `over` file names the tree the case ran
    /// over and is never read as a reach line, while a recorder file beside it
    /// is.
    ///
    /// Fails by: `over` read as reach, so a tree spelled in digits reaches a
    /// site the case never ran.
    #[test]
    fn a_case_over_file_is_never_read_as_reach() {
        let dir = crate::scratch::scratch("schema-over-not-reach").join("k");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("case"), "k\tbin").unwrap();
        std::fs::write(dir.join(DONE), "0").unwrap();
        std::fs::write(dir.join(OVER), "7").unwrap();
        std::fs::write(dir.join("probes"), "3\n").unwrap();
        let identity = Identity {
            probes: &[],
            sites: &[],
            mutant_fns: &std::collections::BTreeMap::new(),
            file_fns: &std::collections::BTreeMap::new(),
            classic: &BTreeSet::new(),
        };
        let reach = collect_dirs([dir], &identity).unwrap();
        assert_eq!(reach.sites.keys().copied().collect::<Vec<_>>(), [3]);
    }

    /// CLOUD-2789: a case directory's `read` listing and its `trace` are never
    /// read as reach lines, whatever they hold, while a recorder file beside
    /// them is.
    ///
    /// Fails by: either name dropped from the skip list (shard 1/8's
    /// `collect_dirs` survivor joins the two), so a listed path or a traced
    /// line spelled in digits reaches a site the case never ran.
    #[test]
    fn a_case_read_listing_and_trace_are_never_read_as_reach() {
        let dir = crate::scratch::scratch("schema-read-trace-not-reach").join("k");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("case"), "k\tbin").unwrap();
        std::fs::write(dir.join(DONE), "0").unwrap();
        std::fs::write(dir.join(READ), "5\nf6\n").unwrap();
        std::fs::write(dir.join(TRACE), "7\nf8\n").unwrap();
        std::fs::write(dir.join("probes"), "3\n").unwrap();
        let identity = Identity {
            probes: &[],
            sites: &[],
            mutant_fns: &std::collections::BTreeMap::new(),
            file_fns: &std::collections::BTreeMap::new(),
            classic: &BTreeSet::new(),
        };
        let reach = collect_dirs([dir], &identity).unwrap();
        assert_eq!(reach.sites.keys().copied().collect::<Vec<_>>(), [3]);
        assert!(
            reach.executed.is_empty(),
            "no `f` line is a recorder's here"
        );
    }

    /// CLOUD-2789: an unscoped file keys even a private item under its bare
    /// name, as before scoping, since its module is unknown.
    ///
    /// Fails by: [`FileScope::unscoped`] built without its flag (shard 1/8's
    /// field-deletion survivor), so the item is keyed at the root module of
    /// an empty package and a mention from the file's real module misses it.
    #[test]
    fn an_unscoped_file_keys_a_private_item_by_its_bare_name() {
        let helper = first_item("fn helper() {}\n");
        assert_eq!(
            definitions(&helper, &FileScope::unscoped(), &BTreeSet::new()),
            ["helper"]
        );
        assert_ne!(
            definitions(&helper, &FileScope::default(), &BTreeSet::new()),
            ["helper"],
            "the default scope is a module's, not unscoped"
        );
    }

    /// CLOUD-2789: a case directory's `untraced` file names why the case was
    /// not traced and is never read as a reach line, whatever it holds, while
    /// a recorder file beside it is.
    ///
    /// Fails by: `untraced` read as reach, so a reason spelled as a site or a
    /// probe reaches what the case never ran.
    #[test]
    fn a_case_untraced_file_is_never_read_as_reach() {
        let dir = crate::scratch::scratch("schema-untraced-not-reach").join("k");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("case"), "k\tbin").unwrap();
        std::fs::write(dir.join(DONE), "0").unwrap();
        std::fs::write(dir.join(UNTRACED), "7\nf9\n").unwrap();
        std::fs::write(dir.join("probes"), "3\n").unwrap();
        let identity = Identity {
            probes: &[],
            sites: &[],
            mutant_fns: &std::collections::BTreeMap::new(),
            file_fns: &std::collections::BTreeMap::new(),
            classic: &BTreeSet::new(),
        };
        let reach = collect_dirs([dir], &identity).unwrap();
        assert_eq!(reach.sites.keys().copied().collect::<Vec<_>>(), [3]);
        assert!(reach.executed.is_empty());
    }

    /// K1 (CLOUD-2904's key fix): a private item added to a module moves the cases whose
    /// functions name it from inside that module, and none naming its
    /// spelling from outside, where it is not visible. 1dc469d24 added a
    /// private `const fn covered` to `resume.rs`, and every case binding a
    /// `covered` anywhere in the workspace moved.
    ///
    /// Fails by: a name matched by spelling alone (the outside case moves), or
    /// a private item scoped too narrowly (the inside case holds).
    #[test]
    fn an_added_private_item_moves_no_case_outside_its_module() {
        let (outside, inside) = (case("segments"), case("lap"));
        let cases: BTreeSet<Case> = [outside.clone(), inside.clone()].into();
        let executed = [(outside.clone(), [0].into()), (inside.clone(), [1].into())].into();
        let base = |added: &str| {
            format!(
                "pub fn segments(c: &str) -> bool {{ covered(c) }}\n\
                 mod resume {{\n{added}    pub fn lap(held: usize) -> bool {{ covered(held, 0) }}\n}}\n"
            )
        };
        let held = source_digests(&cases, &executed, &base(""));
        let added = source_digests(
            &cases,
            &executed,
            &base("    const fn covered(h: usize, p: usize) -> bool { h > p }\n"),
        );
        assert_eq!(
            added[&outside], held[&outside],
            "covered is not visible here"
        );
        assert_ne!(
            added[&inside], held[&inside],
            "lap names covered in its module"
        );
    }

    /// K2 (CLOUD-2904's key fix): a method added moves the case that calls it and no
    /// case that only binds a local of its name. 6a5339e58 added
    /// `impl Host { fn here }`, and every case binding a local `here` moved.
    ///
    /// Fails by: an impl answering to its members' names in a free position
    /// (`anchor_at` moves), or not in an associated one (`caller` holds).
    #[test]
    fn an_added_method_moves_no_case_that_only_binds_a_local_of_its_name() {
        let (anchor, caller) = (case("anchor_at"), case("caller"));
        let cases: BTreeSet<Case> = [anchor.clone(), caller.clone()].into();
        let executed = [(anchor.clone(), [0].into()), (caller.clone(), [1].into())].into();
        let base = "pub fn anchor_at(here: &str) -> usize { here.len() }\n\
                    pub fn caller(h: &impl Here) -> usize { h.here() }\n";
        let held = source_digests(&cases, &executed, base);
        let added = source_digests(
            &cases,
            &executed,
            &format!("{base}impl Host {{ pub fn here(&self) -> usize {{ 1 }} }}\n"),
        );
        assert_eq!(
            added[&anchor], held[&anchor],
            "a local `here` is not the method"
        );
        assert_ne!(added[&caller], held[&caller], "`h.here()` may call it");
    }

    /// K3 (CLOUD-2904's key fix): a comment edit in a shared helper a case reaches moves
    /// no case, and a token edit does. 6df55d534 changed one comment in
    /// `pin_mise` and moved all 6,524 integration cases.
    ///
    /// Fails by: a reached helper hashed as text (the comment edit moves the
    /// digest), or its tokens dropped (the token edit holds).
    #[test]
    fn a_comment_edit_in_a_reached_shared_helper_moves_no_case() {
        let test = [String::from("fn t() { pin_mise(dir); }")];
        let common = |note: &str, value: &str| {
            format!(
                "pub fn pin_mise(dir: &Path) -> u8 {{\n    // {note}\n    let p = 1;\n    {value}\n}}\n"
            )
        };
        let base = common_reached(&common("the pin", "p"), &test);
        assert_eq!(
            base,
            common_reached(&common("the pinned toolchain", "p"), &test),
            "a comment edit moves nothing"
        );
        assert_ne!(
            base,
            common_reached(&common("the pin", "p + 1"), &test),
            "a token edit moves it"
        );
    }

    /// K4 (CLOUD-2904's key fix): a `use` takes by its leaf anything, and by
    /// its path before the leaf only a module or type: a case reaching only the
    /// `ROOT` that `use batten::surface::ROOT;` binds is not keyed on
    /// `fn batten`. `tests/it/common/mod.rs:48` pulled `fn batten`, and
    /// through it `pin_mise`, into every integration case.
    ///
    /// Fails by: a `use` always taken with every name it mentions (the body
    /// edit of `fn batten` moves the digest), or `fn batten` not taken where
    /// a case calls it.
    #[test]
    fn a_use_reached_by_its_leaf_takes_no_function_its_path_spells() {
        let common = |body: &str| {
            format!("use batten::surface::ROOT;\npub fn batten() -> u8 {{ {body} }}\n")
        };
        let rooted = [String::from("fn t() { let _ = ROOT; }")];
        assert_eq!(
            common_reached(&common("1"), &rooted),
            common_reached(&common("2"), &rooted),
            "a case touching only ROOT"
        );
        let called = [String::from("fn t() { batten(); }")];
        assert_ne!(
            common_reached(&common("1"), &called),
            common_reached(&common("2"), &called),
            "a case calling batten"
        );
    }

    /// K5 (CLOUD-2904's key fix): a chain through a skeleton item is followed where its
    /// mentions are made: `pub const LIMIT = super::helper()` in one module
    /// reaches the private `helper` of its parent, so editing `helper` moves
    /// the case naming `LIMIT` from a third. A private `LIMIT` elsewhere,
    /// invisible to that case, is no second definition of the name it uses.
    ///
    /// Fails by: a name with a definition in any module counted against every
    /// mention (`LIMIT` is not expanded and the case holds), or a mention
    /// scoped where the case is rather than where the item is (`helper`,
    /// private to the root, is not reached from `LIMIT`).
    #[test]
    fn an_edit_crossing_modules_through_a_skeleton_item_moves_the_case() {
        let (names, other) = (case("names_limit"), case("other"));
        let cases: BTreeSet<Case> = [names.clone(), other.clone()].into();
        let executed = [(names.clone(), [0].into()), (other.clone(), [1].into())].into();
        let source = |value: &str| {
            format!(
                "mod limits {{ pub const LIMIT: u8 = super::helper(); }}\n\
                 const fn helper() -> u8 {{ {value} }}\n\
                 mod elsewhere {{ const LIMIT: u8 = 7; }}\n\
                 mod third {{ pub fn names_limit() -> u8 {{ crate::limits::LIMIT }} }}\n\
                 pub fn other() -> u8 {{ 3 }}\n"
            )
        };
        let held = source_digests(&cases, &executed, &source("1"));
        let edited = source_digests(&cases, &executed, &source("2"));
        assert_ne!(edited[&names], held[&names], "LIMIT's value is helper's");
        assert_eq!(edited[&other], held[&other], "and no other case moves");
    }

    /// K6 (CLOUD-2904's key fix): a function moved whole moves no case that runs it, and
    /// an edit to it still does.
    ///
    /// Fails by: a case keyed on its probe digests in probe-id order, a
    /// function's position (both orders differ), or on none of them.
    #[test]
    fn pure_code_motion_of_an_executed_function_moves_no_case() {
        let runs = case("runs");
        let cases: BTreeSet<Case> = [runs.clone()].into();
        let executed = [(runs.clone(), [0, 1].into())].into();
        let first = |value: &str| format!("pub fn first() -> u8 {{ {value} }}\n");
        let second = "pub fn second() -> u8 { 2 }\n";
        let held = source_digests(&cases, &executed, &format!("{}{second}", first("1")));
        let moved = source_digests(&cases, &executed, &format!("{second}{}", first("1")));
        assert_eq!(moved, held, "the same functions, in another order");
        let edited = source_digests(&cases, &executed, &format!("{second}{}", first("3")));
        assert_ne!(edited[&runs], held[&runs], "an edit to one it ran");
    }

    /// Each case's digest over one `source` rendered where `place` says.
    fn placed_digests(
        cases: &BTreeSet<Case>,
        executed: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
        source: &str,
        place: &FileScope,
    ) -> std::collections::BTreeMap<Case, String> {
        let root = crate::scratch::scratch("schema-placed-digests");
        let rendered = render_in(source, &[], &BTreeSet::new(), Some(0), place);
        let mut items: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, digest) in &rendered.items {
            items
                .entry(name.clone())
                .or_default()
                .insert(digest.clone());
        }
        let mut mentions: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, mentioned) in &rendered.mentions {
            mentions
                .entry(name.clone())
                .or_default()
                .extend(mentioned.iter().cloned());
        }
        let depends = Depends {
            names: &rendered.names,
            items: &items,
            mentions: &mentions,
            compiled: &rendered.compiled,
            derived: None,
            ..depends(&rendered.probes)
        };
        case_digests(
            &root,
            cases,
            &std::collections::BTreeMap::new(),
            executed,
            &depends,
        )
    }

    /// R1 (CLOUD-2904's soundness review): a `use` a shared helper imports a
    /// trait by is taken though nothing names the trait, so an edit to the
    /// module it imports from moves the case calling the trait's method.
    ///
    /// Fails by: a named `use` taken only when its bound name is wanted (a
    /// trait called by method is never named, and the edit reuses a stale
    /// verdict).
    #[test]
    fn a_use_importing_a_trait_called_by_method_moves_the_case() {
        let test = [String::from("fn t() { greet(\"a\"); }")];
        let common = |body: &str| {
            format!(
                "mod ext {{\n    pub trait Shout {{ fn shout(&self) -> String; }}\n    \
                 impl Shout for str {{ fn shout(&self) -> String {{ {body} }} }}\n}}\n\
                 use self::ext::Shout;\npub fn greet(n: &str) -> String {{ n.shout() }}\n"
            )
        };
        assert_ne!(
            common_reached(&common("self.to_uppercase()"), &test),
            common_reached(&common("self.to_lowercase()"), &test),
            "the trait's impl is what `n.shout()` runs"
        );
    }

    /// R2 (CLOUD-2904's soundness review): a package whose files sit in
    /// modules their paths do not say is not scoped by module, so a private
    /// item is visible to its whole package; and what says so is a `#[path]`,
    /// plain, raw or under `cfg_attr`, or an `include!` no syntax resolves.
    ///
    /// Fails by: a private item scoped by a module path read off a moved
    /// file's path (the case naming it from elsewhere holds), or a layout
    /// misread as plain.
    #[test]
    fn a_package_whose_modules_move_is_not_scoped_by_module() {
        let names = case("names_helper");
        let cases: BTreeSet<Case> = [names.clone()].into();
        let executed = [(names.clone(), [0].into())].into();
        let source = |value: &str| {
            format!(
                "mod a {{ const fn helper() -> u8 {{ {value} }} }}\n\
                 mod b {{ pub fn names_helper() -> u8 {{ helper() }} }}\n"
            )
        };
        let flat = FileScope {
            flat: true,
            ..FileScope::default()
        };
        let held = placed_digests(&cases, &executed, &source("1"), &flat);
        let edited = placed_digests(&cases, &executed, &source("2"), &flat);
        assert_ne!(
            edited[&names], held[&names],
            "helper is visible package-wide"
        );
        for moved in [
            "#[path = \"x.rs\"]\nmod x;\n",
            "#[path = r\"x.rs\"]\nmod x;\n",
            "#[cfg_attr(test, path = \"x.rs\")]\nmod x;\n",
            "mod outer {\n    #[path = \"x.rs\"]\n    mod x;\n}\n",
            "include!(some_path());\n",
            "m! { include!(\"x.rs\"); }\n",
        ] {
            assert!(moves_modules(moved, "src/lib.rs"), "{moved}");
        }
        for plain in [
            "pub fn path() -> u8 { 1 }\n",
            "include!(\"x.rs\");\n",
            "include!(concat!(env!(\"OUT_DIR\"), \"/x.rs\"));\n",
            "const S: &str = \"#[path = \\\"x.rs\\\"]\";\n",
            "#[cfg_attr(test, derive(Debug))]\nstruct S;\nfn path() {}\n",
        ] {
            assert!(!moves_modules(plain, "src/lib.rs"), "{plain}");
        }
    }

    /// R2 (CLOUD-2904's soundness review): a `[lib]` or `[[bin]]` target at a
    /// path other than its default moves its crate root.
    ///
    /// Fails by: a custom root read as the default (its crate's modules are
    /// scoped from the wrong root), or a default path read as custom.
    #[test]
    fn a_custom_target_path_moves_the_crate_root() {
        let root = crate::scratch::scratch("schema-custom-target");
        let manifest = |extra: &str| {
            std::fs::create_dir_all(root.join("p")).unwrap();
            std::fs::write(
                root.join("p/Cargo.toml"),
                format!("[package]\nname = \"p\"\n{extra}"),
            )
            .unwrap();
        };
        manifest("[lib]\npath = \"src/lib.rs\"\n[[bin]]\nname = \"p\"\npath = \"src/main.rs\"\n");
        assert!(!custom_target(&root, "p"), "default paths");
        manifest("[[bin]]\nname = \"q\"\npath = \"src/bin/q.rs\"\n");
        assert!(!custom_target(&root, "p"), "a bin's default path");
        manifest("[lib]\npath = \"lib/root.rs\"\n");
        assert!(custom_target(&root, "p"), "a custom lib root");
        manifest("[[bin]]\nname = \"p\"\npath = \"tools/p.rs\"\n");
        assert!(custom_target(&root, "p"), "a custom bin root");
    }

    /// R3 (CLOUD-2904's soundness review): text that observes its position
    /// moves its key when it moves, and spacing inside a macro's token tree
    /// is keyed.
    ///
    /// Fails by: a helper calling `line!()` keyed by tokens alone (a line
    /// shift above it changes what it returns and moves nothing), a probed
    /// function doing the same, or `m!(a += b)` keyed as `m!(a + = b)`.
    #[test]
    fn text_that_observes_its_position_or_spacing_moves_its_key() {
        let test = [String::from("fn t() { here(); }")];
        let common = |prefix: &str| format!("{prefix}pub fn here() -> u32 {{ line!() }}\n");
        assert_ne!(
            common_reached(&common(""), &test),
            common_reached(&common("\n"), &test),
            "a line shift moves what line!() says"
        );
        let spaced = [String::from("fn t() { op(); }")];
        let joint = |op: &str| format!("pub fn op() -> u8 {{ m!(a {op} b) }}\n");
        assert_ne!(
            common_reached(&joint("+="), &spaced),
            common_reached(&joint("+ ="), &spaced),
            "spacing inside a token tree"
        );
        let runs = case("here");
        let cases: BTreeSet<Case> = [runs.clone()].into();
        let executed = [(runs.clone(), [0].into())].into();
        let probed = |prefix: &str| format!("{prefix}pub fn here() -> u32 {{ line!() }}\n");
        assert_ne!(
            source_digests(&cases, &executed, &probed(""))[&runs],
            source_digests(&cases, &executed, &probed("\n\n"))[&runs],
            "a probed function's line moves its digest"
        );
    }

    /// R4 (CLOUD-2904's soundness review): an item exporting its symbol and
    /// an item an `extern` block declares are visible workspace-wide, so an
    /// edit to a `no_mangle` static moves the case reading it through an
    /// `extern` declaration in another module.
    ///
    /// Fails by: a linked item scoped to its module (the reader holds).
    #[test]
    fn a_linked_symbol_is_visible_workspace_wide() {
        let reads = case("read");
        let cases: BTreeSet<Case> = [reads.clone()].into();
        let executed = [(reads.clone(), [0].into())].into();
        let source = |value: &str| {
            format!(
                "mod a {{ #[unsafe(no_mangle)] static TABLE: u8 = {value}; }}\n\
                 mod b {{\n    unsafe extern \"C\" {{ static TABLE: u8; }}\n    \
                 pub fn read() -> u8 {{ unsafe {{ TABLE }} }}\n}}\n"
            )
        };
        let held = source_digests(&cases, &executed, &source("1"));
        let edited = source_digests(&cases, &executed, &source("2"));
        assert_ne!(edited[&reads], held[&reads], "TABLE is one symbol");
    }

    /// R6 (CLOUD-2904's soundness review): a test file's own items besides
    /// its functions are keyed by what the test reaches, so an edit to a
    /// `const` a test names moves its text and an edit to one it does not
    /// leaves it.
    ///
    /// Fails by: only functions keyed (the `const` edit reuses a stale
    /// verdict), or every item keyed (an unreached `const` moves it).
    #[test]
    fn a_test_files_items_it_reaches_are_in_its_text() {
        let source = |limit: &str, other: &str| {
            format!(
                "const LIMIT: u8 = {limit};\nconst OTHER: u8 = {other};\n\
                 #[test]\nfn t() {{ assert_eq!(LIMIT, 1); }}\n"
            )
        };
        let held = test_texts(&source("1", "1"));
        assert_ne!(
            test_texts(&source("2", "1"))["t"],
            held["t"],
            "t names LIMIT"
        );
        assert_eq!(
            test_texts(&source("1", "2"))["t"],
            held["t"],
            "t names no OTHER"
        );
    }

    /// R7 (CLOUD-2904's soundness review): an impl in a shared module answers
    /// to every name in its self type, so a case naming `Holder` takes
    /// `impl Holder<Item>`.
    ///
    /// Fails by: an impl answering only to the alphabetically last name in
    /// its self type (`Item`), so an edit to `Holder`'s method moves nothing.
    #[test]
    fn a_shared_impl_answers_to_every_name_in_its_self_type() {
        let test = [String::from("fn t() { let _ = Holder::new(); }")];
        let common = |body: &str| {
            format!(
                "pub struct Item;\npub struct Holder<T>(T);\n\
                 impl Holder<Item> {{ pub fn new() -> Self {{ {body} }} }}\n"
            )
        };
        assert_ne!(
            common_reached(&common("Holder(Item)"), &test),
            common_reached(&common("todo!()"), &test),
            "the case calls Holder::new"
        );
    }

    /// R8 (CLOUD-2904's soundness review): a callback an attribute names by a
    /// string is a name, so an edit to serde's `default = "fallback"` moves
    /// the case naming the struct that reads it.
    ///
    /// Fails by: a string in an attribute naming nothing (the edit reuses a
    /// stale verdict).
    #[test]
    fn a_callback_an_attribute_names_by_string_is_a_name() {
        let reads = case("read");
        let cases: BTreeSet<Case> = [reads.clone()].into();
        let executed = [(reads.clone(), [0].into())].into();
        let source = |value: &str| {
            format!(
                "const fn fallback() -> u8 {{ {value} }}\n\
                 #[derive(Deserialize)]\npub struct S {{ #[serde(default = \"fallback\")] x: u8 }}\n\
                 pub fn read() -> Option<S> {{ None }}\n"
            )
        };
        let held = source_digests(&cases, &executed, &source("1"));
        let edited = source_digests(&cases, &executed, &source("2"));
        assert_ne!(edited[&reads], held[&reads], "S's default calls fallback");
    }

    /// R9 (CLOUD-2904's soundness review): an impl is keyed on the names of
    /// every method it defines, probed ones included, so overriding a default
    /// method the standard library calls unnamed moves the case using it.
    ///
    /// Fails by: a probed override cut from its impl's digest whole (adding
    /// `fold` changes what `sum()` runs and moves nothing).
    #[test]
    fn an_override_of_a_default_method_moves_the_impls_cases() {
        let sums = case("total");
        let cases: BTreeSet<Case> = [sums.clone()].into();
        let executed = [(sums.clone(), [0].into())].into();
        let source = |extra: &str| {
            format!(
                "pub fn total(c: Counter) -> u8 {{ c.sum() }}\npub struct Counter;\n\
                 impl Iterator for Counter {{\n    type Item = u8;\n    \
                 fn next(&mut self) -> Option<u8> {{ None }}\n{extra}}}\n"
            )
        };
        let held = source_digests(&cases, &executed, &source(""));
        let added = source_digests(
            &cases,
            &executed,
            &source("    fn fold<B, F: FnMut(B, u8) -> B>(self, init: B, _f: F) -> B { init }\n"),
        );
        assert_ne!(added[&sums], held[&sums], "sum() now runs the override");
    }

    /// R10 (CLOUD-2904's soundness review): an associated const answers to
    /// its impl's type too, so a case naming only the type moves when the
    /// const does: a generic function outside the workspace reads `T::K`.
    ///
    /// Fails by: an associated const reached only from an associated position
    /// (the case names `Unit` and no `K`, and the edit reuses a stale verdict).
    #[test]
    fn an_associated_const_answers_to_its_type() {
        let reads = case("read");
        let cases: BTreeSet<Case> = [reads.clone()].into();
        let executed = [(reads.clone(), [0].into())].into();
        let source = |value: &str| {
            format!(
                "pub fn read() -> u8 {{ external::<Unit>() }}\npub struct Unit;\n\
                 impl Limit for Unit {{ const K: u8 = {value}; }}\n"
            )
        };
        let held = source_digests(&cases, &executed, &source("1"));
        let edited = source_digests(&cases, &executed, &source("2"));
        assert_ne!(
            edited[&reads], held[&reads],
            "external::<Unit> reads Unit::K"
        );
    }

    /// Every item `source` holds, members and nested items included.
    fn every_item(source: &str) -> Vec<ast::Item> {
        batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
            .tree()
            .syntax()
            .descendants()
            .filter_map(ast::Item::cast)
            .collect()
    }

    /// CLOUD-2789: a macro's own name and a name in an attribute are written
    /// unknowably, each on its own: neither needs the other to be `?`.
    ///
    /// Fails by: the macro and attribute tests joined with `&&` (a mutant
    /// missed at 34c6e4d1f), so each reads as a bare name resolved in its
    /// own module.
    #[test]
    fn a_macros_name_and_an_attributes_are_each_written_unknowably() {
        let root = parsed("#[inline]\nfn f() { shout!(); }\n");
        let written = |name: &str| {
            let token = root
                .descendants_with_tokens()
                .filter_map(ra_ap_syntax::NodeOrToken::into_token)
                .find(|token| token.text() == name)
                .unwrap_or_else(|| panic!("{name} is written"));
            written_as(&token, "")
        };
        let unknown = format!("{WRITTEN}?");
        assert_eq!(written("shout"), unknown, "a macro's own name");
        assert_eq!(written("inline"), unknown, "a name in an attribute");
    }

    /// CLOUD-2789: in a std macro's tokens, a name after ONE `:` (a field
    /// value) and a name inside a nested group are each passed as written;
    /// only a `::` before it qualifies it.
    ///
    /// Fails by: the two `:` tests joined with `||`, so one `:` reads as a
    /// path; or a nested group not opened by a `!` read as a macro call's
    /// unknowable tokens (two mutants missed at 34c6e4d1f).
    #[test]
    fn a_field_value_and_a_grouped_name_in_a_std_macro_pass_as_written() {
        let root = parsed("fn f() { vec![S { a: value }, (inner), q::r]; }\n");
        let passed = |name: &str| {
            let token = root
                .descendants_with_tokens()
                .filter_map(ra_ap_syntax::NodeOrToken::into_token)
                .find(|token| token.text() == name)
                .unwrap_or_else(|| panic!("{name} is written"));
            passed_as_written(&token)
        };
        assert_eq!(passed("value"), "", "a field's value after one `:`");
        assert_eq!(passed("inner"), "", "a name in a nested group");
        assert_eq!(
            passed("r"),
            format!("{WRITTEN}?"),
            "a `::` qualifies its name"
        );
    }

    /// Fails by: a hand-back's cause kept for every verdict BUT the error
    /// (the comparison inverted, a mutant missed at 34c6e4d1f, CLOUD-2789),
    /// so a caught or missed run is said to have erred and an erring run
    /// keeps no cause to read.
    #[test]
    fn only_an_erring_handback_keeps_its_cause() {
        assert!(erred(Verdict::Error.name()));
        for verdict in [
            Verdict::Caught,
            Verdict::Missed,
            Verdict::Uncovered,
            Verdict::Timeout,
        ] {
            assert!(!erred(verdict.name()), "{}", verdict.name());
        }
    }

    /// CLOUD-2789: a glob `use` beside a module of the name it globs leaves
    /// the module alone answering to it: `a::K` in `c` is `c::a`'s `K`.
    ///
    /// Fails by: the glob's name unmarked (a mutant missed at 34c6e4d1f), so
    /// it is taken for a definition a path resolves through, `a` is
    /// ambiguous, and an edit to the root's `a::K` moves `g`.
    #[test]
    fn a_glob_uses_name_is_no_definition_a_path_resolves_through() {
        let calls = case("g");
        let cases: BTreeSet<Case> = [calls.clone()].into();
        let base = "mod a { pub const K: u8 = 1; }\n\
                    mod c { use super::a::*; mod a { pub const K: u8 = 2; } \
                    pub fn g() -> u8 { a::K } }\n";
        let executed = [(calls.clone(), [probe_of(base, "g")].into())].into();
        let held = source_digests(&cases, &executed, base);
        let other = source_digests(&cases, &executed, &base.replace("K: u8 = 1", "K: u8 = 3"));
        assert_eq!(other[&calls], held[&calls], "the root's a::K is not named");
        let own = source_digests(&cases, &executed, &base.replace("K: u8 = 2", "K: u8 = 4"));
        assert_ne!(own[&calls], held[&calls], "c::a::K is");
    }

    /// The parsed root of `source`.
    fn parsed(source: &str) -> SyntaxNode {
        batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
            .tree()
            .syntax()
            .clone()
    }

    /// A file's scope is its package and its module path, a crate root's
    /// being its directory, so every file of the crate sits in it or below.
    ///
    /// Fails by: a crate root read as a module of its own (a `src/bin/*.rs`,
    /// a `tests/*.rs` or a `build.rs` scoped apart from the files it holds),
    /// or `mod.rs`, `lib.rs` or `main.rs` read as a module name.
    #[test]
    fn a_files_scope_is_its_package_and_module_path() {
        let of = |file: &str| {
            let scope = FileScope::of(file);
            (scope.package, scope.module.join("::"))
        };
        let owned = |package: &str, module: &str| (package.to_owned(), module.to_owned());
        assert_eq!(
            of("crates/batten/src/lib.rs"),
            owned("crates/batten", "src")
        );
        assert_eq!(
            of("crates/batten/src/mutate/schema.rs"),
            owned("crates/batten", "src::mutate::schema")
        );
        assert_eq!(
            of("crates/batten/src/mutate/mod.rs"),
            owned("crates/batten", "src::mutate")
        );
        assert_eq!(
            of("crates/batten/src/bin/x.rs"),
            owned("crates/batten", "src::bin")
        );
        assert_eq!(of("tests/it/main.rs"), owned("", "tests::it"));
        assert_eq!(of("tests/primitives.rs"), owned("", "tests"));
        assert_eq!(of("build.rs"), owned("", ""));
        assert!(!FileScope::of("src/lib.rs").unscoped, "a source is scoped");
        assert!(FileScope::unscoped().unscoped, "an unscoped file is not");
    }

    /// An item's visibility is its modifier's, whitespace aside, except an
    /// impl, a macro or a linked symbol, which are workspace-wide.
    ///
    /// Fails by: an impl or macro scoped by its absent modifier, `pub` or
    /// `pub(self)` misread, whitespace in a modifier read, or an `extern`
    /// item or a `no_mangle` one scoped to its module.
    #[test]
    fn an_items_visibility_is_read_off_its_modifier_and_its_kind() {
        let visible: Vec<Visible> = items_of(
            "fn a() {}\npub fn b() {}\npub(crate) fn c() {}\npub(self) fn d() {}\n\
             pub ( super ) fn e() {}\nimpl S {}\nmacro_rules! m { () => {} }\n\
             #[unsafe(no_mangle)] fn f() {}\n",
        )
        .iter()
        .map(visibility)
        .collect();
        assert_eq!(
            visible,
            [
                Visible::Module,
                Visible::Workspace,
                Visible::Package,
                Visible::Module,
                Visible::Package,
                Visible::Workspace,
                Visible::Workspace,
                Visible::Workspace,
            ]
        );
        let declared = every_item("unsafe extern \"C\" { fn g(); }\n")
            .into_iter()
            .find(|item| matches!(item, ast::Item::Fn(_)))
            .unwrap();
        assert_eq!(visibility(&declared), Visible::Workspace);
    }

    /// A member of an impl or trait answers to its own name in an associated
    /// position only; an associated const answers to its impl's type too, a
    /// method and a free const do not; an impl or trait lists every member.
    ///
    /// Fails by: a member's name free, a member fn answering to its type, or
    /// a trait's members left out of its digest.
    #[test]
    fn a_members_names_are_associated_and_a_const_answers_to_its_type() {
        let items = every_item(
            "impl Tr for S { const K: u8 = 1; fn f() {} }\n\
             trait T { fn a(); const B: u8; }\nconst TOP: u8 = 2;\n",
        );
        let named = |name: &str| {
            items
                .iter()
                .find(|item| {
                    ast::AnyHasName::cast(item.syntax().clone())
                        .and_then(|named| ast::HasName::name(&named))
                        .is_some_and(|own| own.text() == name)
                })
                .unwrap()
        };
        let none: Vec<String> = Vec::new();
        assert_eq!(item_names(named("K")), none);
        assert_eq!(associated_names(named("K")), ["K"]);
        assert_eq!(
            owner_type_names(named("K"), ""),
            [format!("S{IMPL_DEFINED}"), format!("Tr{IMPL_DEFINED}")]
        );
        assert_eq!(owner_type_names(named("f"), ""), none);
        assert_eq!(owner_type_names(named("TOP"), ""), none);
        assert_eq!(member_names(named("T")), ["B", "a"]);
        let block = items
            .iter()
            .find(|item| matches!(item, ast::Item::Impl(_)))
            .unwrap();
        assert_eq!(member_names(block), ["K", "f"]);
    }

    /// A node's position is its line and column, both from zero.
    ///
    /// Fails by: a column counted from the wrong end of the line.
    #[test]
    fn a_nodes_position_is_its_line_and_column() {
        let items = items_of("fn a() {}\n  fn b() {}\n");
        assert_eq!(position_of(items[0].syntax()), "0:0");
        assert_eq!(position_of(items[1].syntax()), "1:2");
    }

    /// A module holding an `include!` or a `#[path]` module is widened, and
    /// no other: not one holding a plain `mod x;`, nor another macro call.
    ///
    /// Fails by: any macro read as an include, a plain `mod x;` read as a
    /// `#[path]` one, or a module needing both read as needing either.
    #[test]
    fn a_module_holding_an_include_or_a_path_module_is_widened() {
        let root = parsed(
            "mod a { include!(\"x.rs\"); }\nmod b {\n    #[path = \"y.rs\"]\n    mod y;\n}\n\
             mod c { mod z; }\nfn f() { other!(); }\n",
        );
        assert_eq!(
            widened_modules(&root, &FileScope::default()),
            BTreeSet::from([String::from("a"), String::from("b")])
        );
        let paths: Vec<Option<String>> =
            parsed("#[path = \"x.rs\"]\nmod x;\n#[path=\"y.rs\"]\nmod y;\n#[cfg(test)]\nmod z;\n")
                .descendants()
                .filter_map(ast::Attr::cast)
                .map(|attr| path_attr(&attr))
                .collect();
        assert_eq!(
            paths,
            [Some(String::from("x.rs")), Some(String::from("y.rs")), None]
        );
    }

    /// A mention carries the scope it is made in and how it is written, a
    /// nested `use` leaf with its list's prefix; an associated position, a
    /// string's capture and a nested `use` leaf make it associated too,
    /// scoped where a path qualifies it; a mention in a `macro_rules!` body
    /// or an unscoped file is bare.
    ///
    /// Fails by: a path's later segment, a nested `use` leaf or a capture
    /// read as free only, a call's name read as associated, or a macro body's
    /// or an unscoped file's mention scoped.
    #[test]
    fn a_mention_is_scoped_where_it_is_made_unless_nothing_scopes_it() {
        let root = parsed(
            "fn f() { helper(); Host::here(); use a::{b}; let s = \"{cap}\"; }\n\
             macro_rules! m { () => { inside() } }\n",
        );
        let scoped = mentions_in(&root, &FileScope::of("src/lib.rs"));
        // `f`'S BODY HOLDS A `use`, SO IT IS A SCOPE OF ITS OWN ([`block_label`]).
        let made = |name: &str| format!("{name}{MENTIONED_IN}{MENTIONED_IN}src::#f0");
        for expected in [
            made("helper"),
            format!("{ASSOCIATED}here{MENTIONED_IN}{MENTIONED_IN}src::#f0{WRITTEN}Host"),
            format!("{ASSOCIATED}b{MENTIONED_IN}{MENTIONED_IN}src::#f0{WRITTEN}a"),
            format!("b{MENTIONED_IN}{MENTIONED_IN}src::#f0{WRITTEN}a"),
            format!("{ASSOCIATED}cap"),
            String::from("inside"),
        ] {
            assert!(scoped.contains(&expected), "{expected:?} in {scoped:?}");
        }
        assert!(
            !scoped.contains(&format!("{ASSOCIATED}helper")),
            "a call's name is free"
        );
        assert!(!scoped.contains("helper"), "a function's mention is scoped");
        let bare = mentions_in(&root, &FileScope::unscoped());
        assert!(
            bare.contains("helper"),
            "an unscoped file's mention is bare"
        );
    }

    /// A string in an attribute names every word in it, an underscored one
    /// included; a string elsewhere names only its captures.
    ///
    /// Fails by: a plain string's words read as names, or a callback whose
    /// name starts with `_` dropped.
    #[test]
    fn an_attribute_strings_words_are_names_and_a_plain_strings_are_not() {
        let names = names_in(&parsed(
            "#[serde(default = \"_fallback\", with = \"a::b\")]\nstruct S;\n\
             fn f() { g(\"plain words\"); }\n",
        ));
        for name in ["_fallback", "a", "b"] {
            assert!(names.contains(name), "{name} in {names:?}");
        }
        assert!(!names.contains("plain"), "{names:?}");
    }

    /// Spacing is keyed inside a macro's token tree and nowhere else.
    ///
    /// Fails by: a gap marked outside a token tree (a reformatted function
    /// moves its key), or none inside one.
    #[test]
    fn spacing_is_keyed_inside_a_token_tree_only() {
        let text = |source: &str| keyed_text(items_of(source)[0].syntax());
        assert_eq!(
            text("fn f() { a + b }"),
            text("fn f(){a+b}"),
            "outside a token tree"
        );
        assert_ne!(
            text("fn f() { m!(a+b) }"),
            text("fn f() { m!(a + b) }"),
            "inside one"
        );
    }

    /// The files an `include!` or `#[path]` module names are found, nested
    /// paths both ways, and a package with a `#[path]` or a custom target
    /// root is not scoped by module, while one with a resolved `include!`
    /// alone is.
    ///
    /// Fails by: a file holding only an `include!` skipped, a nested
    /// `#[path]` read only one way, or a package needing either cause read as
    /// needing both.
    #[test]
    fn the_sources_a_layout_moves_are_found_and_their_packages_unscoped() {
        let root = crate::scratch::scratch("schema-layout");
        let write = |path: &str, text: &str| {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        };
        write(
            "p/src/lib.rs",
            "include!(\"gen.rs\");\nmod outer {\n    #[path = \"w.rs\"]\n    mod w;\n}\n",
        );
        write("q/src/lib.rs", "pub fn plain() {}\n");
        write(
            "r/Cargo.toml",
            "[package]\nname = \"r\"\n[lib]\npath = \"lib/root.rs\"\n",
        );
        write("r/src/lib.rs", "pub fn plain() {}\n");
        write("s/src/lib.rs", "include!(\"x.rs\");\n");
        let files: BTreeSet<String> = [
            "p/src/lib.rs",
            "q/src/lib.rs",
            "r/src/lib.rs",
            "s/src/lib.rs",
        ]
        .map(String::from)
        .into();
        assert_eq!(
            flat_packages(&root, &files),
            BTreeSet::from([String::from("p"), String::from("r")])
        );
        assert_eq!(
            included_sources(&root, &files),
            BTreeSet::from([
                String::from("p/src/gen.rs"),
                String::from("p/src/outer/w.rs"),
                String::from("p/src/w.rs"),
                String::from("s/src/x.rs"),
            ])
        );
    }

    /// A type a shared module defines is taken only when a case or a taken
    /// item names it, by any name or by a path's module or type segment.
    ///
    /// Fails by: a type no path names taken anyway, so an edit to it moves
    /// every case reaching the module.
    #[test]
    fn a_shared_type_nothing_names_is_not_taken() {
        let test = [String::from("fn t() { helper(); }")];
        let common =
            |field: &str| format!("pub struct Unused {{ x: {field} }}\npub fn helper() {{}}\n");
        assert_eq!(
            common_reached(&common("u8"), &test),
            common_reached(&common("u16"), &test)
        );
    }

    /// A sweep's tally counts the verdicts reused, the mutants a held kill
    /// pair decided and the case runs a recorded outcome decided.
    ///
    /// Fails by: a judged mutant's skipped runs or held kill not counted.
    #[test]
    fn a_tally_counts_what_was_decided_without_a_run() {
        let tally = Tally::default();
        tally
            .reused
            .fetch_add(2, std::sync::atomic::Ordering::Relaxed);
        tally.judged(Judged {
            verdict: Verdict::Caught,
            skipped: 3,
            held_kill: true,
            by_hang: false,
        });
        tally.judged(Judged::ran(Verdict::Missed, 1));
        assert_eq!(
            tally.line(9),
            "mutate schema: reused 2 of 9 verdict(s), 1 decided by a held kill pair, \
             and 4 case run(s) a recorded outcome decided"
        );
    }

    /// An impl is followed beside a name's own definition, never beside an
    /// associated name alone.
    ///
    /// Fails by: an associated name counted as the name's own definition, so
    /// a method name reached the one impl holding it, or the name's own
    /// definition not counted, so its one impl was never followed.
    #[test]
    fn an_impl_is_followed_only_beside_an_owned_definition() {
        let imp = format!("S{IMPL_DEFINED}");
        let member = format!("{ASSOCIATED}m");
        let items: std::collections::BTreeMap<String, BTreeSet<String>> =
            [(imp.clone(), ["impl S".to_owned()].into())].into();
        let owned = ["S", imp.as_str()];
        assert_eq!(
            followed(&[0, 1], &owned, &items).collect::<Vec<_>>(),
            [0, 1],
            "the type's one impl"
        );
        let associated = [member.as_str(), imp.as_str()];
        assert_eq!(
            followed(&[0, 1], &associated, &items).collect::<Vec<_>>(),
            [0],
            "a method name's impl"
        );
    }

    /// B16 (CLOUD-2904, round 3; CLOUD-2927): a type's impls are keyed
    /// without being followed, and its one definition is followed, so an edit
    /// the type's own definition reaches moves the case naming it and an edit
    /// only one of its impls' headers names does not.
    ///
    /// Fails by: every impl followed (the impls of common names join one
    /// component, and a `///` edit on any type in it re-keyed 97.6% of probed
    /// functions), or the type's own definition not followed.
    #[test]
    fn an_ambiguous_impl_is_keyed_but_not_followed() {
        let g = case("g");
        let cases: BTreeSet<Case> = [g.clone()].into();
        let executed = [(g.clone(), [0].into())].into();
        let source = |c: &str, d: &str| {
            format!(
                "pub fn g(s: S) -> S {{ s }}\npub struct S {{ c: C }}\n\
                 impl S {{ pub const K: u8 = 0; }}\nimpl Tr for S where D: Bound {{}}\n\
                 pub struct C({c});\npub struct D({d});\n"
            )
        };
        let held = source_digests(&cases, &executed, &source("u32", "u32"));
        let field = source_digests(&cases, &executed, &source("u64", "u32"));
        // S'S IMPLS ARE NO DEFINITION OF S (CLOUD-2927): its one struct is
        // followed to its field's type.
        assert_ne!(field[&g], held[&g], "S's field type, through S's struct");
        let bound = source_digests(&cases, &executed, &source("u32", "u64"));
        assert_eq!(
            bound[&g], held[&g],
            "a type only an impl's where clause names"
        );
    }

    /// B17 (CLOUD-2904, round 3): an item's position is keyed only when its
    /// own tokens observe it, so a line added above a module holding a case
    /// that reads `line!()` moves no case naming the module, while one above
    /// a `const` reading it moves the case naming the const.
    ///
    /// Fails by: an item keyed at its position for what a nested function
    /// observes (`mod tests` moved with every line above it, and 97.6% of
    /// probed functions with it), or a `const` reading `line!()` not keyed at
    /// its position.
    #[test]
    fn only_an_items_own_tokens_key_its_position() {
        let names = case("names");
        let cases: BTreeSet<Case> = [names.clone()].into();
        let executed = [(names.clone(), [0].into())].into();
        let module = |above: &str| {
            format!(
                "{above}pub fn names() -> u8 {{ tests::X }}\nmod tests {{\n    \
                 pub const X: u8 = 1;\n    fn t() {{ assert_eq!(line!(), 4); }}\n}}\n"
            )
        };
        assert_eq!(
            source_digests(&cases, &executed, &module(""))[&names],
            source_digests(&cases, &executed, &module("\n"))[&names],
            "the module observes nothing itself"
        );
        let constant = |above: &str| {
            format!("{above}pub fn names() -> u32 {{ L }}\nconst L: u32 = line!();\n")
        };
        assert_ne!(
            source_digests(&cases, &executed, &constant(""))[&names],
            source_digests(&cases, &executed, &constant("\n"))[&names],
            "the const reads its line"
        );
    }

    /// B18 (CLOUD-2904, round 3): a selection keys a function sharing a name
    /// the case calls on its tokens, so a comment in it moves nothing and a
    /// token edit does.
    ///
    /// Fails by: a same-named function keyed on its text (a comment in any
    /// `fn new` moved 97.5% of selection reaches), or not keyed at all.
    #[test]
    fn a_same_named_functions_comment_moves_no_selection() {
        let none = std::collections::BTreeMap::new();
        let ran: BTreeSet<String> = {
            let (root, format) = selection_tree("schema-select-same-base", SELECTED, "");
            let index = dependency_index(&root, &format).unwrap();
            ["run", "helper", "checks"]
                .iter()
                .flat_map(|name| index.digests_of(name))
                .collect()
        };
        let digest = |name: &str, body: &str| {
            let lib =
                format!("{SELECTED}mod other {{\n    pub fn helper() -> u8 {{\n{body}    }}\n}}\n");
            let (root, format) = selection_tree(name, &lib, "");
            let index = dependency_index(&root, &format).unwrap();
            let case = (String::from("tests::checks"), String::from("fix"));
            let cases = [(case.clone(), (ran.clone(), Some(BTreeSet::new())))].into();
            test_digests(&root, &index, &format.dirs, &cases, &none)
                .remove(&case)
                .unwrap()
        };
        let held = digest("schema-select-same-a", "        2\n");
        assert_eq!(
            digest("schema-select-same-b", "        // a note\n        2\n"),
            held,
            "a comment in a same-named function"
        );
        assert_ne!(
            digest("schema-select-same-c", "        3\n"),
            held,
            "a token edit in it"
        );
    }

    /// B19 (CLOUD-2904, round 3): only an `include!` macro call moves a
    /// package's modules; an identifier spelled `include` does not.
    ///
    /// Fails by: any `include` identifier read as an include (a field or a
    /// variable so named left `crates/batten` and `batten-core` with no module
    /// scoping), or a spaced `include !` call missed.
    #[test]
    fn only_an_include_macro_call_moves_modules() {
        assert!(!moves_modules(
            "pub struct S { include: bool }\npub fn f(s: S) -> bool { let include = s.include; include }\n",
            "src/lib.rs"
        ));
        assert!(moves_modules("include !(some_path());\n", "src/lib.rs"));
    }

    /// Each case's digest over a tree at a scratch root holding `files`, the
    /// first of them rendered and probed as the package's `src/lib.rs`, each
    /// case of package `fix` (at the root) running the probe ids `executed`
    /// gives it, and every path's content id from `resources`.
    fn tree_digests(
        name: &str,
        cases: &BTreeSet<Case>,
        executed: &std::collections::BTreeMap<Case, BTreeSet<usize>>,
        files: &[(&str, &str)],
        resources: &std::collections::BTreeMap<String, String>,
    ) -> std::collections::BTreeMap<Case, String> {
        stored_tree_digests(name, (cases, executed), files, resources, None)
    }

    /// [`tree_digests`] through the derived store `derived`.
    fn stored_tree_digests(
        name: &str,
        (cases, executed): (
            &BTreeSet<Case>,
            &std::collections::BTreeMap<Case, BTreeSet<usize>>,
        ),
        files: &[(&str, &str)],
        resources: &std::collections::BTreeMap<String, String>,
        derived: Option<&Derived>,
    ) -> std::collections::BTreeMap<Case, String> {
        let root = crate::scratch::scratch(name);
        for (path, text) in files {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        }
        let (lib, source) = files[0];
        let rendered = render_in(source, &[], &BTreeSet::new(), Some(0), &FileScope::of(lib));
        let mut items: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, digest) in &rendered.items {
            items
                .entry(name.clone())
                .or_default()
                .insert(digest.clone());
        }
        let mut mentions: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::new();
        for (name, mentioned) in &rendered.mentions {
            mentions
                .entry(name.clone())
                .or_default()
                .extend(mentioned.iter().cloned());
        }
        let read = std::collections::BTreeMap::new();
        let depends = Depends {
            probes: &rendered.probes,
            names: &rendered.names,
            items: &items,
            mentions: &mentions,
            read: &read,
            resources,
            untraced: "",
            compiled: &rendered.compiled,
            derived,
        };
        let dirs = [(String::from("fix"), String::new())].into();
        case_digests(&root, cases, &dirs, executed, &depends)
    }

    /// A sweep over a tree it has derived before parses no file, and one
    /// over a one-file edit parses that file alone; what it keys is the same
    /// with the store as without it. Parses are counted, never timed.
    ///
    /// Fails by: a test crate, a case's own texts or a file's mentions parsed
    /// again over unchanged bytes (~70 ms a case and 1,550 s of a carry on
    /// #1276), or a stored artifact keying a case differently from a fresh one.
    #[test]
    fn a_sweep_over_a_tree_it_derived_parses_no_file() {
        let root = crate::scratch::scratch("schema-derived-parses");
        let state = crate::scratch::scratch("schema-derived-state");
        let write = |path: &str, text: &str| {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        };
        write("src/lib.rs", "pub const LIMIT: u8 = 1;\npub fn f() {}\n");
        write("tests/it/main.rs", "mod a;\nmod b;\n");
        write(
            "tests/it/a.rs",
            "fn helper() -> u8 { fix::LIMIT }\n#[test]\nfn t() { assert_eq!(helper(), 1); }\n\
             #[test]\nfn v() { fix::f(); }\n",
        );
        write("tests/it/b.rs", "#[test]\nfn u() { fix::f(); }\n");
        let (t, u) = (
            (String::from("a::t"), String::from("fix::it")),
            (String::from("b::u"), String::from("fix::it")),
        );
        let cases: BTreeSet<Case> = [t.clone(), u.clone()].into();
        let executed = [(t.clone(), BTreeSet::new()), (u.clone(), BTreeSet::new())].into();
        let dirs = [(String::from("fix"), String::new())].into();
        let sweep = |store: Option<&Derived>| {
            let before = batten_facts::source::parses();
            let digests = case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    derived: store,
                    ..depends(&[])
                },
            );
            (digests, batten_facts::source::parses() - before)
        };
        let (first, parsed) = sweep(Some(&Derived::at(&state, "build")));
        assert!(parsed > 0, "a first sweep parses what it derives");
        let (again, reparsed) = sweep(Some(&Derived::at(&state, "build")));
        assert_eq!(reparsed, 0, "an unchanged tree parses no file");
        assert_eq!(again, first, "a stored artifact keys as a fresh one");
        assert_eq!(sweep(None).0, first, "and as no store at all");
        write("tests/it/b.rs", "#[test]\nfn u() { fix::f(); fix::f(); }\n");
        let (edited, parsed_edit) = sweep(Some(&Derived::at(&state, "build")));
        assert!(
            parsed_edit > 0 && parsed_edit < parsed,
            "the edited file alone: {parsed_edit} of {parsed}"
        );
        assert_eq!(edited[&t], first[&t]);
        assert_ne!(edited[&u], first[&u]);
        let (_, other_build) = sweep(Some(&Derived::at(&state, "another build")));
        assert_eq!(
            other_build, parsed,
            "another build derives every file afresh"
        );
    }

    /// The reach line counts the cases a run starts: none under `none()`, the
    /// unfinished ones under a naming filter, every listed one without a
    /// filter; and how many were finished before it.
    ///
    /// Fails by: the count read off the listing whatever the filter, so a
    /// relaunch that re-ran no finished case reported the whole suite.
    #[test]
    fn the_reach_line_counts_the_cases_a_run_starts() {
        let case = |name: &str| (name.to_owned(), String::from("fix"));
        let listed: BTreeSet<Case> = ["a", "b", "c", "d"].map(case).into();
        let finished: BTreeSet<Case> = ["a", "b", "c"].map(case).into();
        let line = |filter: Option<&str>| reach_starts_line(Some(&listed), filter, &finished);
        assert_eq!(
            line(Some("none()")),
            "mutate schema: reach runs 0 of 4 listed case(s), 3 finished before"
        );
        assert_eq!(
            line(Some("test(=d)")),
            "mutate schema: reach runs 1 of 4 listed case(s), 3 finished before"
        );
        assert_eq!(
            line(None),
            "mutate schema: reach runs 4 of 4 listed case(s), 3 finished before"
        );
        assert_eq!(
            reach_starts_line(None, None, &finished),
            "mutate schema: reach runs the whole suite, its cases unlisted"
        );
    }

    /// Two files are the same bytes only if both end together: a length that
    /// lies (procfs reports 0 for a file holding bytes) is read past, never
    /// trusted.
    ///
    /// Fails by: either stream's end taken as both ends (`&& -> ||`, which
    /// the sweep at b878238b4 found survived), so a file holding bytes
    /// matched an empty one of the same reported length.
    #[test]
    fn same_bytes_reads_past_a_length_that_lies() {
        if !cfg!(target_os = "linux") {
            return;
        }
        let empty = crate::scratch::scratch("schema-same-bytes-lying").join("empty");
        std::fs::write(&empty, "").unwrap();
        let lying = std::path::Path::new("/proc/self/cmdline");
        assert_eq!(
            std::fs::metadata(lying).unwrap().len(),
            0,
            "procfs reports 0"
        );
        assert!(!same_bytes(lying, &empty));
        assert!(!same_bytes(&empty, lying));
        assert!(same_bytes(&empty, &empty));
    }

    /// The finished cases are exactly the records a recorder would skip: each
    /// one done passing, by the case it names; a record unfinished, failed or
    /// naming no case is none.
    ///
    /// Fails by: a case answered that no record holds (the sweep at b878238b4
    /// found an added default case survived), which a relaunch's count of
    /// finished cases would then overstate.
    #[test]
    fn the_finished_cases_are_the_records_done_passing() {
        let base = crate::scratch::scratch("schema-finished-cases");
        let record = |dir: &str, case: Option<&str>, done: Option<&str>| {
            let at = base.join(dir);
            std::fs::create_dir_all(&at).unwrap();
            if let Some(case) = case {
                std::fs::write(at.join("case"), case).unwrap();
            }
            if let Some(code) = done {
                std::fs::write(at.join(DONE), code).unwrap();
            }
        };
        record("1", Some("a::passed\tfix::it"), Some("0"));
        record("2", Some("a::failed\tfix::it"), Some("101"));
        record("3", Some("a::running\tfix::it"), None);
        record("4", None, Some("0"));
        assert_eq!(
            finished_cases(&base),
            BTreeSet::from([(String::from("a::passed"), String::from("fix::it"))])
        );
    }

    /// `super` from a crate's root names no module: the path is unknown, never
    /// the root again.
    ///
    /// Fails by: the root's `super` read as the root (the guard on its arm
    /// dropped, which the sweep at b878238b4 found survived), so `super::x`
    /// at the top of a crate resolved to the crate's own `x`.
    #[test]
    fn super_from_a_crates_root_is_unknown() {
        let definitions_owned = [format!("x{HOMED}fix{HOMED}{MODULE_ITEM}")];
        let items: std::collections::BTreeMap<String, BTreeSet<String>> = definitions_owned
            .iter()
            .map(|definition| (definition.clone(), BTreeSet::from([String::from("i")])))
            .collect();
        let mentions = std::collections::BTreeMap::new();
        let definitions: Vec<&str> = definitions_owned.iter().map(String::as_str).collect();
        let by_base = std::collections::HashMap::from([("x", vec![0])]);
        let (globs, crates, macros) = (
            Globs::new(),
            std::collections::HashMap::new(),
            std::collections::HashMap::new(),
        );
        let index = Resolver::new(
            &by_base,
            &definitions,
            &items,
            &mentions,
            (&globs, &crates, &macros),
        );
        assert_eq!(
            index.path("fix", "", &["x"], 0),
            Place::Module("fix", String::from("x")),
            "`x` from the root is its module"
        );
        assert_eq!(index.path("fix", "", &["super", "x"], 0), Place::Unknown);
    }

    /// A stage's line names it and the seconds since its start, and the
    /// instant it answers starts the next stage.
    ///
    /// Fails by: a stage's line unsaid or unnamed, or the next stage timed
    /// from the sweep's start, so every line after the first carried the
    /// stages before it.
    #[test]
    fn a_stage_says_its_own_seconds_and_starts_the_next() {
        let mut out = Vec::new();
        let long_ago = std::time::Instant::now()
            .checked_sub(std::time::Duration::from_secs(90))
            .unwrap();
        let next = stage_took(&mut out, "copy", long_ago).unwrap();
        stage_took(&mut out, "render and build", next).unwrap();
        let said = String::from_utf8(out).unwrap();
        let lines: Vec<&str> = said.lines().collect();
        assert!(
            lines[0].starts_with("mutate schema: stage copy took 90."),
            "{said}"
        );
        assert_eq!(
            lines[1], "mutate schema: stage render and build took 0.0s",
            "{said}"
        );
    }

    /// A use binding imports by the one mention written where it is, in its
    /// own package and module, with a path: never one made in another
    /// package, and never one written with no path, though either names the
    /// same base and sorts first.
    ///
    /// Fails by: a mention matched on its package alone, or on its module and
    /// path alone (bootstrap shard 5/8 at 34c6e4d1f found `&& -> ||` here
    /// survived every fixture, whose use bindings held one mention each).
    #[test]
    fn a_use_imports_by_its_own_written_path_alone() {
        let binding = format!("zed{HOMED}fix{HOMED}src::a{USE_BOUND}");
        let own = format!("zed{MENTIONED_IN}fix{MENTIONED_IN}src::a{WRITTEN}super::b");
        let mentions = std::collections::BTreeMap::from([(
            binding.clone(),
            BTreeSet::from([
                own.clone(),
                format!("zed{MENTIONED_IN}fix{MENTIONED_IN}src::a"),
                format!("zed{MENTIONED_IN}aaa{MENTIONED_IN}src::a{WRITTEN}super::d"),
            ]),
        )]);
        let items = std::collections::BTreeMap::from([(
            binding.clone(),
            BTreeSet::from([String::from("u")]),
        )]);
        let definitions = vec![binding.as_str()];
        let by_base = std::collections::HashMap::from([("zed", vec![0])]);
        let (globs, crates, macros) = (
            Globs::new(),
            std::collections::HashMap::new(),
            std::collections::HashMap::new(),
        );
        let index = Resolver::new(
            &by_base,
            &definitions,
            &items,
            &mentions,
            (&globs, &crates, &macros),
        );
        assert_eq!(index.use_target(0, "zed"), Some(own.as_str()));
    }

    /// A chain of `use super::zed` bindings is followed through
    /// [`RESOLVE_DEPTH`] + 1 bindings to the definition at its end, and one
    /// binding longer is unknown.
    ///
    /// Fails by: the bound one short (`>=`, which bootstrap shard 5/8 at
    /// 34c6e4d1f found survived: its `pub use` chains resolved through
    /// modules, so no fixture reached the bound) or one long.
    #[test]
    fn a_use_chain_is_followed_to_its_bound_and_no_further() {
        let module = |depth: usize| format!("src{}", "::x".repeat(depth));
        let chain = |uses: usize| {
            let mut definitions_owned = vec![format!("zed{HOMED}fix{HOMED}{}", module(1))];
            let mut mentions = std::collections::BTreeMap::new();
            for depth in 2..=uses + 1 {
                let binding = format!("zed{HOMED}fix{HOMED}{}{USE_BOUND}", module(depth));
                mentions.insert(
                    binding.clone(),
                    BTreeSet::from([format!(
                        "zed{MENTIONED_IN}fix{MENTIONED_IN}{}{WRITTEN}super",
                        module(depth)
                    )]),
                );
                definitions_owned.push(binding);
            }
            let items: std::collections::BTreeMap<String, BTreeSet<String>> = definitions_owned
                .iter()
                .map(|definition| (definition.clone(), BTreeSet::from([String::from("i")])))
                .collect();
            let definitions: Vec<&str> = definitions_owned.iter().map(String::as_str).collect();
            let by_base =
                std::collections::HashMap::from([("zed", (0..definitions.len()).collect())]);
            let (globs, crates, macros) = (
                Globs::new(),
                std::collections::HashMap::new(),
                std::collections::HashMap::new(),
            );
            let index = Resolver::new(
                &by_base,
                &definitions,
                &items,
                &mentions,
                (&globs, &crates, &macros),
            );
            index.through_uses(Found::One(uses), "zed", 0)
        };
        assert_eq!(chain(1), Found::One(0), "one binding is followed");
        assert_eq!(
            chain(RESOLVE_DEPTH + 1),
            Found::One(0),
            "a chain the bound holds is followed to its end"
        );
        assert_eq!(
            chain(RESOLVE_DEPTH + 2),
            Found::Unknown,
            "one binding longer is unknown"
        );
    }

    /// A `use super::zed` in a module whose parent defines no `zed` imports
    /// nothing of the workspace: the binding resolves to nothing, which is
    /// certain, not to unknown, which is not.
    ///
    /// Fails by: the `Found::Nothing` arm deleted, so the binding falls to the
    /// catch-all and reads as unknown (a mutant uncovered at 34c6e4d1f).
    #[test]
    fn a_use_naming_nothing_resolves_to_nothing() {
        let binding = format!("zed{HOMED}fix{HOMED}src::x::x{USE_BOUND}");
        let mentions = std::collections::BTreeMap::from([(
            binding.clone(),
            BTreeSet::from([format!(
                "zed{MENTIONED_IN}fix{MENTIONED_IN}src::x::x{WRITTEN}super"
            )]),
        )]);
        let items: std::collections::BTreeMap<String, BTreeSet<String>> =
            std::collections::BTreeMap::from([(
                binding.clone(),
                BTreeSet::from([String::from("i")]),
            )]);
        let definitions = vec![binding.as_str()];
        let by_base = std::collections::HashMap::from([("zed", vec![0])]);
        let (globs, crates, macros) = (
            Globs::new(),
            std::collections::HashMap::new(),
            std::collections::HashMap::new(),
        );
        let index = Resolver::new(
            &by_base,
            &definitions,
            &items,
            &mentions,
            (&globs, &crates, &macros),
        );
        assert_eq!(index.through_uses(Found::One(0), "zed", 0), Found::Nothing);
    }

    /// A name found only through globs whose own paths are found through
    /// further globs costs two depths a level (a path, then the lookup it
    /// makes), so `src`'s globs `g1` .. `g8`, `g8` its one module, find `zed`
    /// in `src::g8`, and with a ninth the walk reaches [`RESOLVE_DEPTH`] and
    /// is unknown.
    ///
    /// Fails by: a path's lookup made at the path's own depth (`depth * 1`,
    /// which bootstrap shard 3/8 at 34c6e4d1f found survived: no fixture
    /// nested globs deep enough to reach the bound), so nine levels resolve.
    #[test]
    fn globs_found_through_globs_reach_the_depth_bound_two_a_level() {
        let lookup = |globs: usize| {
            let last = format!("g{globs}");
            let definitions_owned = [
                format!("{last}{HOMED}fix{HOMED}src{MODULE_ITEM}"),
                format!("zed{HOMED}fix{HOMED}src::{last}"),
            ];
            let items: std::collections::BTreeMap<String, BTreeSet<String>> = definitions_owned
                .iter()
                .map(|definition| (definition.clone(), BTreeSet::from([String::from("i")])))
                .collect();
            let mentions = std::collections::BTreeMap::new();
            let definitions: Vec<&str> = definitions_owned.iter().map(String::as_str).collect();
            let by_base =
                std::collections::HashMap::from([(last.as_str(), vec![0]), ("zed", vec![1])]);
            let raws: Vec<String> = (1..=globs).map(|level| format!("g{level}")).collect();
            let globs: Globs<'_> = std::collections::HashMap::from([(
                ("fix", "src"),
                raws.iter().map(String::as_str).collect(),
            )]);
            let (crates, macros) = (
                std::collections::HashMap::new(),
                std::collections::HashMap::new(),
            );
            let index = Resolver::new(
                &by_base,
                &definitions,
                &items,
                &mentions,
                (&globs, &crates, &macros),
            );
            let scope = format!("zed{MENTIONED_IN}fix{MENTIONED_IN}src");
            index.lookup(&scope, "zed", "fix", String::from("src"), 0)
        };
        assert_eq!(lookup(1), Found::One(1), "one glob is followed");
        assert_eq!(
            lookup(RESOLVE_DEPTH / 2),
            Found::One(1),
            "the deepest nesting the bound holds is followed"
        );
        assert_eq!(
            lookup(RESOLVE_DEPTH / 2 + 1),
            Found::Unknown,
            "one level deeper is unknown"
        );
    }

    /// A workspace crate's name is its crate only as a path's first segment
    /// and only where nothing before it is `self`, `super` or `crate`: `m::dep`
    /// and `super::dep` name nothing of the workspace though `dep` is a
    /// workspace crate, and `dep` alone is that crate's root.
    ///
    /// Fails by: a crate taken at any segment, or after `super` (`&& -> ||`,
    /// which bootstrap shard 3/8 at 34c6e4d1f found survived: its digest
    /// fixture held no workspace crate map).
    #[test]
    fn a_crate_name_is_its_crate_only_as_a_relative_paths_first_segment() {
        let definitions_owned = [format!("m{HOMED}fix{HOMED}src{MODULE_ITEM}")];
        let items: std::collections::BTreeMap<String, BTreeSet<String>> = definitions_owned
            .iter()
            .map(|definition| (definition.clone(), BTreeSet::from([String::from("i")])))
            .collect();
        let mentions = std::collections::BTreeMap::new();
        let definitions: Vec<&str> = definitions_owned.iter().map(String::as_str).collect();
        let by_base = std::collections::HashMap::from([("m", vec![0])]);
        let globs = Globs::new();
        let crates = std::collections::HashMap::from([("dep", Some("crates/dep"))]);
        let macros = std::collections::HashMap::new();
        let index = Resolver::new(
            &by_base,
            &definitions,
            &items,
            &mentions,
            (&globs, &crates, &macros),
        );
        assert_eq!(
            index.path("fix", "src", &["dep"], 0),
            Place::Module("crates/dep", String::from("src")),
            "a first segment naming a workspace crate is its root"
        );
        assert_eq!(
            index.path("fix", "src", &["m", "dep"], 0),
            Place::Nothing,
            "a later segment is looked up where the path has reached"
        );
        assert_eq!(
            index.path("fix", "src::m", &["super", "dep"], 0),
            Place::Nothing,
            "after `super` it is looked up in the parent"
        );
    }

    /// The derived store keeps what the current build reads and nothing else:
    /// once a run has derived over the whole tree, another version's directory
    /// and the artifact of a file's former bytes are gone, and a later run over
    /// the same tree derives nothing afresh.
    ///
    /// Fails by: an old version's directory surviving (2.3 GB each on #1276, a
    /// judge's container held 6.9 GB of them), an artifact of former bytes
    /// surviving in the current one, or an artifact the run only read removed,
    /// so the next run parses again what it had.
    #[test]
    fn the_derived_store_keeps_only_what_the_current_build_reads() {
        let root = crate::scratch::scratch("schema-derived-bound");
        let state = crate::scratch::scratch("schema-derived-bound-state");
        let write = |file: &str, text: &str| {
            let path = root.join(file);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, text).unwrap();
        };
        write("src/lib.rs", "pub fn f() {}\n");
        write("tests/it/a.rs", "#[test]\nfn t() { fix::f(); }\n");
        write("tests/it/b.rs", "#[test]\nfn u() { fix::f(); }\n");
        let (t, u) = (
            (String::from("a::t"), String::from("fix::it")),
            (String::from("b::u"), String::from("fix::it")),
        );
        let cases: BTreeSet<Case> = [t.clone(), u.clone()].into();
        let executed = [(t, BTreeSet::new()), (u, BTreeSet::new())].into();
        let dirs = [(String::from("fix"), String::new())].into();
        let sweep = |store: &Derived| {
            let before = batten_facts::source::parses();
            let digests = case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    derived: Some(store),
                    ..depends(&[])
                },
            );
            (digests, batten_facts::source::parses() - before)
        };
        let artifacts = |store: &Derived| std::fs::read_dir(&store.dir).map_or(0, Iterator::count);
        let old = Derived::at(&state, "a former build");
        sweep(&old);
        let first = Derived::at(&state, "build");
        assert_eq!(first.drop_other_versions(), 1, "the former build's version");
        assert!(!old.dir.exists(), "removed before the run derives");
        sweep(&old);
        sweep(&first);
        let whole = artifacts(&first);
        assert!(whole > 0, "a first run keeps what it derives");
        write("tests/it/b.rs", "#[test]\nfn u() { fix::f(); fix::f(); }\n");
        let edited = Derived::at(&state, "build");
        let (keyed, _) = sweep(&edited);
        assert!(artifacts(&edited) > whole, "the edit derived b.rs afresh");
        edited.retain_touched();
        assert!(!old.dir.exists(), "another version's directory is removed");
        assert_eq!(
            artifacts(&edited),
            whole,
            "the artifacts of b.rs's former bytes are removed"
        );
        assert_eq!(
            sweep(&Derived::at(&state, "build")),
            (keyed, 0),
            "nothing the run read is removed, and every case keys as it did"
        );
    }

    /// A warm sweep derives no case's digest; one over a probe whose digest
    /// moved derives the cases that ran it alone; one over an edited test file
    /// derives the cases whose reads include it alone. Derivations are counted,
    /// never timed, and a digest taken from the store is the one derived.
    ///
    /// Fails by: every case derived afresh on every sweep (~50 ms a case, and
    /// 1,550 s of a null re-run's carry on #1276), or a case taken from the
    /// store over an input that moved.
    #[test]
    fn a_warm_sweep_derives_no_case_and_an_edit_only_its_readers() {
        let root = crate::scratch::scratch("schema-case-memo");
        let state = crate::scratch::scratch("schema-case-memo-state");
        let write = |path: &str, text: &str| {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        };
        write("src/lib.rs", "pub fn f() {}\npub fn g() {}\n");
        write("tests/it/main.rs", "mod a;\n");
        write(
            "tests/it/a.rs",
            "#[test]\nfn t() { fix::f(); }\n#[test]\nfn u() { fix::g(); }\n",
        );
        write("tests/other.rs", "#[test]\nfn w() { fix::f(); }\n");
        let case = |name: &str, binary: &str| (name.to_owned(), binary.to_owned());
        let (t, u, w) = (
            case("a::t", "fix::it"),
            case("a::u", "fix::it"),
            case("w", "fix::other"),
        );
        let cases: BTreeSet<Case> = [t.clone(), u.clone(), w.clone()].into();
        let executed = [
            (t.clone(), [0].into()),
            (u.clone(), [1].into()),
            (w.clone(), BTreeSet::new()),
        ]
        .into();
        let dirs = [(String::from("fix"), String::new())].into();
        let sweep = |probes: &[String], store: Option<&Derived>| {
            let before = case_derivations();
            let digests = case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    derived: store,
                    ..depends(probes)
                },
            );
            (digests, case_derivations() - before)
        };
        let held = [String::from("f"), String::from("g")];
        let (first, derived_first) = sweep(&held, Some(&Derived::at(&state, "build")));
        assert_eq!(derived_first, 3, "a cold sweep derives every case");
        let (warm, derived_warm) = sweep(&held, Some(&Derived::at(&state, "build")));
        assert_eq!(derived_warm, 0, "a warm sweep derives no case");
        assert_eq!(warm, first, "the stored digests are the derived ones");
        assert_eq!(sweep(&held, None).0, first, "and the ones no store takes");
        let moved = [String::from("f"), String::from("g2")];
        let (probed, derived_probed) = sweep(&moved, Some(&Derived::at(&state, "build")));
        assert_eq!(derived_probed, 1, "the case that ran the moved probe alone");
        assert_ne!(probed[&u], first[&u]);
        assert_eq!((&probed[&t], &probed[&w]), (&first[&t], &first[&w]));
        write(
            "tests/other.rs",
            "#[test]\nfn w() { fix::f(); fix::f(); }\n",
        );
        let (edited, derived_edited) = sweep(&held, Some(&Derived::at(&state, "build")));
        assert_eq!(
            derived_edited, 1,
            "the case whose reads include the file alone"
        );
        assert_ne!(edited[&w], first[&w]);
        assert_eq!((&edited[&t], &edited[&u]), (&first[&t], &first[&u]));
        // ITEM BY ITEM WITHIN ONE CRATE: one test's body moves that test
        // alone, and a test added beside it moves none.
        write(
            "tests/it/a.rs",
            "#[test]\nfn t() { fix::f(); fix::f(); }\n#[test]\nfn u() { fix::g(); }\n",
        );
        let (body, derived_body) = sweep(&held, Some(&Derived::at(&state, "build")));
        assert_eq!(derived_body, 1, "the edited test alone");
        assert_ne!(body[&t], first[&t]);
        assert_eq!(body[&u], first[&u]);
        write(
            "tests/it/a.rs",
            "#[test]\nfn t() { fix::f(); fix::f(); }\n#[test]\nfn u() { fix::g(); }\n\
             #[test]\nfn x() { fix::g(); }\n",
        );
        let (added, derived_added) = sweep(&held, Some(&Derived::at(&state, "build")));
        assert_eq!(derived_added, 0, "a test added beside them moves no case");
        assert_eq!((&added[&t], &added[&u]), (&body[&t], &body[&u]));
    }

    /// A case with no own text reads its test crate whole, and a warm sweep
    /// takes its digest from the store like any other.
    ///
    /// Fails by: a kept whole read re-derived item by item, which never equals
    /// what it kept, so every such case is derived afresh on every sweep
    /// (CLOUD-2789).
    #[test]
    fn a_warm_sweep_takes_a_whole_crate_read_from_the_store() {
        let root = crate::scratch::scratch("schema-case-memo-whole");
        let state = crate::scratch::scratch("schema-case-memo-whole-state");
        let write = |path: &str, text: &str| {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        };
        write("src/lib.rs", "pub fn f() {}\n");
        write("tests/it/main.rs", "mod a;\n");
        write("tests/it/a.rs", "#[test]\nfn t() { fix::f(); }\n");
        // `gone` names no test in the crate's text: it has no own text.
        let gone = (String::from("a::gone"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [gone.clone()].into();
        let executed = [(gone.clone(), [0].into())].into();
        let dirs = [(String::from("fix"), String::new())].into();
        let probes = [String::from("f")];
        let sweep = || {
            let before = case_derivations();
            let digests = case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    derived: Some(&Derived::at(&state, "build")),
                    ..depends(&probes)
                },
            );
            (digests, case_derivations() - before)
        };
        let (cold, derived_cold) = sweep();
        assert_eq!(derived_cold, 1, "a cold sweep derives it");
        let (warm, derived_warm) = sweep();
        assert_eq!(derived_warm, 0, "a warm sweep takes it from the store");
        assert_eq!(warm, cold);
    }

    /// A kept case entry holds only while what it read of its test crate
    /// holds: an edit to a sibling module the case calls, which leaves the
    /// case's own sources and so its key unmoved, moves its digest through the
    /// store as it does with none.
    ///
    /// Fails by: the test crate never indexed (`CaseKeys::index` answering
    /// `None`), so every kept entry reads the crate as absent, holds, and a
    /// sibling module's edit reuses a stale digest (a mutant this suite
    /// missed at fe80fb54b).
    #[test]
    fn a_kept_case_entry_holds_only_while_its_crate_reads_hold() {
        let root = crate::scratch::scratch("schema-case-memo-sibling");
        let state = crate::scratch::scratch("schema-case-memo-sibling-state");
        let write = |path: &str, text: &str| {
            let at = root.join(path);
            std::fs::create_dir_all(at.parent().unwrap()).unwrap();
            std::fs::write(at, text).unwrap();
        };
        write("src/lib.rs", "pub fn f() {}\n");
        write("tests/it/main.rs", "mod a;\nmod helper;\n");
        write("tests/it/a.rs", "#[test]\nfn t() { crate::helper::h(); }\n");
        write("tests/it/helper.rs", "pub fn h() { fix::f(); }\n");
        let t = (String::from("a::t"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [t.clone()].into();
        let executed = [(t.clone(), [0].into())].into();
        let dirs = [(String::from("fix"), String::new())].into();
        let probes = [String::from("f")];
        let sweep = |store: Option<&Derived>| {
            let before = case_derivations();
            let digests = case_digests(
                &root,
                &cases,
                &dirs,
                &executed,
                &Depends {
                    derived: store,
                    ..depends(&probes)
                },
            );
            (digests, case_derivations() - before)
        };
        let (first, _) = sweep(Some(&Derived::at(&state, "build")));
        write("tests/it/helper.rs", "pub fn h() { fix::f(); fix::f(); }\n");
        let (edited, derived) = sweep(Some(&Derived::at(&state, "build")));
        assert_ne!(
            edited[&t], first[&t],
            "the sibling module the case calls moved"
        );
        assert_eq!(edited, sweep(None).0, "the store keys as no store does");
        assert_eq!(derived, 1, "the kept entry no longer holds");
    }

    /// S1 (CLOUD-2904, round 3): a file an `include_str!` reads at compile
    /// time is keyed by content, for the function holding the include and for
    /// the item holding it a case reaches.
    ///
    /// Fails by: an include's target unkeyed (an edited `.rego` preset that a
    /// function `include_str!`s reuses a stale verdict).
    #[test]
    fn a_file_an_include_reads_keys_the_cases_reaching_it() {
        let (runs, names) = (case("preset"), case("names"));
        let cases: BTreeSet<Case> = [runs.clone(), names.clone()].into();
        let executed = [(runs.clone(), [0].into()), (names.clone(), [1].into())].into();
        let lib = "pub fn preset() -> &'static str { include_str!(\"policy/a.rego\") }\n\
                   pub fn names() -> &'static str { TEXT }\n\
                   const TEXT: &str = include_str!(\"b.txt\");\n";
        let ids = |a: &str, b: &str| -> std::collections::BTreeMap<String, String> {
            [
                (String::from("src/policy/a.rego"), a.to_owned()),
                (String::from("src/b.txt"), b.to_owned()),
            ]
            .into()
        };
        let digests = |label: &str, a: &str, b: &str| {
            tree_digests(label, &cases, &executed, &[("src/lib.rs", lib)], &ids(a, b))
        };
        let held = digests("schema-include-a", "1", "1");
        let preset = digests("schema-include-b", "2", "1");
        assert_ne!(preset[&runs], held[&runs], "the function's include");
        assert_eq!(preset[&names], held[&names], "no include of names'");
        let text = digests("schema-include-c", "1", "2");
        assert_ne!(text[&names], held[&names], "the const's include");
    }

    /// S2 (CLOUD-2904, round 3): every other file of an integration case's
    /// test crate is keyed by what the case reaches in it: a sibling module it
    /// calls into, and the crate root's attribute-registered items.
    ///
    /// Fails by: `common/mod.rs` the only shared file (an edit to the sibling
    /// `claim.rs` a case calls, or to `main.rs`'s `#[global_allocator]`, reuses
    /// a stale verdict).
    #[test]
    fn a_sibling_module_a_case_calls_keys_the_case() {
        let plans = (String::from("plan::plans"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [plans.clone()].into();
        let executed = [(plans.clone(), BTreeSet::new())].into();
        let none = std::collections::BTreeMap::new();
        let tree = |label: &str, check: &str, alloc: &str| {
            let main = format!(
                "mod claim;\nmod plan;\n#[global_allocator]\nstatic ALLOC: Alloc = Alloc({alloc});\n"
            );
            let claim =
                format!("pub fn check() -> u8 {{ {check} }}\npub fn unused() -> u8 {{ 0 }}\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", &main),
                    ("tests/it/claim.rs", &claim),
                    (
                        "tests/it/plan.rs",
                        "#[test]\nfn plans() { assert_eq!(crate::claim::check(), 1); }\n",
                    ),
                ],
                &none,
            )[&plans]
                .clone()
        };
        let held = tree("schema-sibling-a", "1", "1");
        assert_ne!(tree("schema-sibling-b", "2", "1"), held, "claim::check");
        assert_ne!(
            tree("schema-sibling-c", "1", "2"),
            held,
            "the global allocator"
        );
    }

    /// R4-13 (CLOUD-2904, round 4): a case that runs a `#[track_caller]`
    /// function keys the position of the functions that call it, and no
    /// other function's.
    ///
    /// Fails by: every function the case ran keyed at its position once one
    /// observer ran, so a line above any of them re-keyed the case.
    #[test]
    fn only_a_callers_position_is_keyed_for_an_observer() {
        let case = case("observed");
        let cases: BTreeSet<Case> = [case.clone()].into();
        let executed = [(case.clone(), [0, 1, 2].into())].into();
        let none = std::collections::BTreeMap::new();
        let lib = |above_caller: &str, above_other: &str| {
            format!(
                "#[track_caller]\npub fn check() {{}}\n{above_caller}pub fn caller() {{ check() }}\n\
                 {above_other}pub fn other() {{}}\n"
            )
        };
        let digest = |label: &str, source: &str| {
            tree_digests(label, &cases, &executed, &[("src/lib.rs", source)], &none)[&case].clone()
        };
        let held = digest("schema-r4-13-a", &lib("", ""));
        assert_eq!(
            digest("schema-r4-13-b", &lib("", "\n")),
            held,
            "a function calling no observer"
        );
        assert_ne!(
            digest("schema-r4-13-c", &lib("\n", "")),
            held,
            "the observer's caller"
        );
        let expanded = |above_caller: &str, above_other: &str| {
            format!(
                "macro_rules! here {{ () => {{ line!() }} }}\n{above_caller}\
                 pub fn caller() -> u32 {{ here!() }}\n{above_other}pub fn other() {{}}\n"
            )
        };
        let two: BTreeSet<Case> = cases.clone();
        let ran = [(case.clone(), [0, 1].into())].into();
        let by_macro = |label: &str, source: &str| {
            tree_digests(label, &two, &ran, &[("src/lib.rs", source)], &none)[&case].clone()
        };
        let held = by_macro("schema-r4-13-d", &expanded("", ""));
        assert_eq!(
            by_macro("schema-r4-13-e", &expanded("", "\n")),
            held,
            "a function expanding no position macro"
        );
        assert_ne!(
            by_macro("schema-r4-13-f", &expanded("\n", "")),
            held,
            "a caller of a macro expanding line!"
        );
    }

    /// R4-14 (CLOUD-2904, round 4): a function's probe digest is its keyed
    /// text, so a `//` comment in a function a case ran moves neither.
    ///
    /// Fails by: the probe digest taken over the function's raw text.
    #[test]
    fn a_comment_in_a_ran_function_moves_no_probe_and_no_case() {
        let case = case("ran");
        let cases: BTreeSet<Case> = [case.clone()].into();
        let executed = [(case.clone(), [0].into())].into();
        let none = std::collections::BTreeMap::new();
        let lib = |note: &str| format!("pub fn f() -> u8 {{\n    // {note}\n    1\n}}\n");
        let render = |source: &str| {
            render_in(
                source,
                &[],
                &BTreeSet::new(),
                Some(0),
                &FileScope::of("src/lib.rs"),
            )
        };
        assert_eq!(render(&lib("one")).probes, render(&lib("two")).probes);
        let digest = |label: &str, note: &str| {
            tree_digests(
                label,
                &cases,
                &executed,
                &[("src/lib.rs", &lib(note))],
                &none,
            )[&case]
                .clone()
        };
        assert_eq!(
            digest("schema-r4-14-a", "one"),
            digest("schema-r4-14-b", "two")
        );
    }

    /// R4-8 (CLOUD-2904, round 4): an integration case that runs a
    /// `#[track_caller]` function keys where its own text calls it from.
    ///
    /// Fails by: caller positions keyed only for probed callers, so a line
    /// added above the test in its unprobed file moves no key while the
    /// location the observer reports moved.
    #[test]
    fn an_unprobed_caller_of_an_observer_keys_its_position() {
        let case = (String::from("o::t"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [case.clone()].into();
        let executed = [(case.clone(), [0].into())].into();
        let none = std::collections::BTreeMap::new();
        let digest = |label: &str, above: &str| {
            let test = format!("{above}#[test]\nfn t() {{ fix::check(); }}\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "#[track_caller]\npub fn check() {}\n"),
                    ("tests/it/main.rs", "mod o;\n"),
                    ("tests/it/o.rs", &test),
                ],
                &none,
            )[&case]
                .clone()
        };
        assert_ne!(digest("schema-r4-8-a", ""), digest("schema-r4-8-b", "\n"));
    }

    /// An integration case's held entry in the derived store holds only while
    /// its unprobed callers sit where they sat: a line added above the test
    /// keys it as afresh, and as with no store at all.
    ///
    /// Fails by: a held entry checked without its callers' position
    /// (`CaseKeys::callers` answering nothing, which the sweep at 9eb88c0a3
    /// reported uncovered: every caller-position case keyed with no store),
    /// so the moved `Location::caller()` kept the entry's old digest.
    #[test]
    fn a_stored_entry_holds_only_while_its_callers_sit_where_they_sat() {
        let case = (String::from("o::t"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [case.clone()].into();
        let executed = [(case.clone(), [0].into())].into();
        let none = std::collections::BTreeMap::new();
        let state = crate::scratch::scratch("schema-stored-callers-state");
        let digest = |above: &str, derived: Option<&Derived>| {
            let test = format!("{above}#[test]\nfn t() {{ fix::check(); }}\n");
            stored_tree_digests(
                "schema-stored-callers",
                (&cases, &executed),
                &[
                    ("src/lib.rs", "#[track_caller]\npub fn check() {}\n"),
                    ("tests/it/main.rs", "mod o;\n"),
                    ("tests/it/o.rs", &test),
                ],
                &none,
                derived,
            )[&case]
                .clone()
        };
        let held = digest("", Some(&Derived::at(&state, "build")));
        assert_eq!(held, digest("", None), "a stored entry keys as a fresh one");
        assert_eq!(
            digest("", Some(&Derived::at(&state, "build"))),
            held,
            "and holds over the same tree"
        );
        let moved = digest("\n", Some(&Derived::at(&state, "build")));
        assert_ne!(moved, held, "a caller moved by a line");
        assert_eq!(moved, digest("\n", None), "keyed as afresh");
    }

    /// S12 (CLOUD-2904, round 4 #20): a package's build script and the file
    /// it `#[path]`-includes are keyed in the tokens every case carries.
    ///
    /// Fails by: an edit to `build.rs`, or to the module it includes, leaving
    /// every case's key where it was while the build it shapes changed.
    #[test]
    fn a_build_script_and_its_path_module_key_every_case() {
        let schema = |label: &str, script: &str, support: &str| {
            let root = crate::scratch::scratch(label);
            let files = [
                ("p/Cargo.toml", "[package]\nname = \"p\"\n"),
                ("p/src/lib.rs", "pub fn f() {}\n"),
                (
                    "p/build.rs",
                    &format!(
                        "#[path = \"build_support.rs\"]\nmod support;\nfn main() {{ {script} }}\n"
                    ),
                ),
                (
                    "p/build_support.rs",
                    &format!("pub fn s() -> u8 {{ {support} }}\n"),
                ),
            ];
            for (path, text) in files {
                std::fs::create_dir_all(root.join(path).parent().unwrap()).unwrap();
                std::fs::write(root.join(path), text).unwrap();
            }
            let mut mutant = listed("FnValue", "()", (1, 1), (1, 2));
            mutant.file = String::from("p/src/lib.rs");
            let work = root.join("work");
            for (path, text) in files {
                std::fs::create_dir_all(work.join(path).parent().unwrap()).unwrap();
                std::fs::write(work.join(path), text).unwrap();
            }
            write_schema(&root, &work, &[mutant], &BTreeSet::new(), &BTreeSet::new())
                .unwrap()
                .items
                .get("")
                .cloned()
                .unwrap_or_default()
        };
        let held = schema("schema-s12-a", "", "1");
        assert_ne!(schema("schema-s12-b", "let _ = 1;", "1"), held, "build.rs");
        assert_ne!(schema("schema-s12-c", "", "2"), held, "its #[path] module");
    }

    /// R4-15 (CLOUD-2904, round 4): a foreign trait or a method name joins
    /// no two types, so a case using one type is not keyed on another that
    /// implements the same trait or has a method of the same name.
    ///
    /// Fails by: every impl under a name followed however many there are,
    /// which joined the workspace into one component (`Clone`, `.as_str()`)
    /// and keyed 91% of probed functions on `Compiled`.
    #[test]
    fn a_shared_trait_or_method_name_joins_no_two_types() {
        let run = case("run");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [0].into())].into();
        let none = std::collections::BTreeMap::new();
        let lib = |cloned: &str, shouted: &str, shown: &str| {
            format!(
                "pub fn run() -> u8 {{ A.shout() }}\n#[derive(Clone)]\npub struct A;\n\
                 impl Shown for A {{}}\npub trait Shown {{ const K: u8 = {shown}; }}\n\
                 pub struct B {{ {cloned} }}\nimpl Clone for B {{ fn clone(&self) -> Self {{ B {{}} }} }}\n\
                 pub struct C {{ {shouted} }}\nimpl C {{ pub fn shout(&self) -> u8 {{ 2 }} }}\n\
                 pub trait Loud {{ fn shout(&self) -> u8; }}\n"
            )
        };
        let digest = |label: &str, cloned: &str, shouted: &str, shown: &str| {
            tree_digests(
                label,
                &cases,
                &executed,
                &[("src/lib.rs", &lib(cloned, shouted, shown))],
                &none,
            )[&run]
                .clone()
        };
        let held = digest("schema-r4-15-a", "", "", "1");
        assert_eq!(
            digest("schema-r4-15-b", "pub v: u8", "", "1"),
            held,
            "a type whose impl of a trait the case's type derives"
        );
        assert_eq!(
            digest("schema-r4-15-c", "", "pub v: u8", "1"),
            held,
            "a type whose one impl has a method the case calls by name"
        );
    }

    /// R4b-5 (CLOUD-2904, round 4b): a case keys the includes of the test
    /// crate items it reaches, never every include the crate makes.
    ///
    /// Fails by: each case of a binary keyed on the crate's include union, so
    /// one edited fixture re-keyed every case of `tests/it`.
    #[test]
    fn a_case_keys_only_the_includes_it_reaches() {
        let (reads, other) = (
            (String::from("a::reads"), String::from("fix::it")),
            (String::from("b::other"), String::from("fix::it")),
        );
        let cases: BTreeSet<Case> = [reads.clone(), other.clone()].into();
        let executed = [
            (reads.clone(), BTreeSet::new()),
            (other.clone(), BTreeSet::new()),
        ]
        .into();
        let digests = |label: &str, id: &str| {
            let ids = [(String::from("tests/it/data.txt"), id.to_owned())].into();
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod a;\nmod b;\n"),
                    (
                        "tests/it/a.rs",
                        "#[test]\nfn reads() { assert_eq!(include_str!(\"data.txt\"), \"x\"); }\n",
                    ),
                    ("tests/it/b.rs", "#[test]\nfn other() {}\n"),
                ],
                &ids,
            )
        };
        let (held, moved) = (
            digests("schema-r4b-5-a", "1"),
            digests("schema-r4b-5-b", "2"),
        );
        assert_ne!(held[&reads], moved[&reads], "the case reading it");
        assert_eq!(held[&other], moved[&other], "a case reaching no include");
    }

    /// R4b-1 (CLOUD-2904, round 4b): a found case walks from what the test
    /// crate helpers it reaches name, so a helper naming a `const` of the
    /// crate under test keys it.
    ///
    /// Fails by: only an unfound case walking from its crate's names.
    #[test]
    fn a_found_case_walks_from_its_helpers_names() {
        let tree = |label: &str, value: &str| {
            let lib = format!("pub const LIMIT: u8 = {value};\npub fn f() {{}}\n");
            crate_case(
                label,
                ("n::inner::t", "fix::it"),
                &[
                    ("src/lib.rs", &lib),
                    ("tests/it/main.rs", "mod n;\n"),
                    (
                        "tests/it/n.rs",
                        "fn helper() -> u8 { fix::LIMIT }\nmod inner {\n    #[test]\n    \
                         fn t() { assert_eq!(super::helper(), 1); }\n}\n",
                    ),
                ],
                &[],
            )
        };
        assert_ne!(tree("schema-r4b-1-a", "1"), tree("schema-r4b-1-b", "2"));
    }

    /// R4b-4, R4b-2 (CLOUD-2904, round 4b): an `OUT_DIR` include keys the
    /// lockfile its build dependencies are pinned in, and an include no syntax
    /// names keys every file, Rust included.
    ///
    /// Fails by: a build's output left to a build key that reads only
    /// `build.rs`, or `?` keyed on the non-Rust files alone.
    #[test]
    fn a_built_or_unnamed_include_keys_what_makes_it() {
        let tree = |label: &str, body: &str, ids: &[(&str, &str)]| {
            let test = format!("#[test]\nfn t() {{ {body} }}\n");
            crate_case(
                label,
                ("g::t", "fix::it"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod g;\n"),
                    ("tests/it/g.rs", &test),
                ],
                ids,
            )
        };
        let built = "let _ = include_bytes!(concat!(env!(\"OUT_DIR\"), \"/t.bin\"));";
        assert_ne!(
            tree("schema-r4b-4-a", built, &[("Cargo.lock", "1")]),
            tree("schema-r4b-4-b", built, &[("Cargo.lock", "2")]),
            "the lockfile under an OUT_DIR include"
        );
        let unnamed = "let _ = include!(concat!(\"../../\", \"fixtures/gen.rs\"));";
        assert_ne!(
            tree("schema-r4b-2-a", unnamed, &[("fixtures/gen.rs", "1")]),
            tree("schema-r4b-2-b", unnamed, &[("fixtures/gen.rs", "2")]),
            "a .rs file under an unnamed include"
        );
        let probed = render_in(
            "pub fn f() -> &'static [u8] { include_bytes!(concat!(env!(\"OUT_DIR\"), \"/t.bin\")) }\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("crates/p/src/lib.rs"),
        );
        assert_eq!(
            probed.compiled.probe_includes,
            [(0, [built_target("crates/p/src/lib.rs")].into())].into(),
            "a probed function's OUT_DIR include"
        );
    }

    /// R4b-3 (CLOUD-2904, round 4b): a `#[cfg_attr(.., path = ..)]` module, a
    /// raw-string `#[path]` and a module a macro declares are in the crate.
    ///
    /// Fails by: `#[path]` read as text, which names no file in a `cfg_attr`
    /// or a raw string, or a macro's module in no walk.
    #[test]
    fn a_test_crates_conditional_raw_and_macro_modules_are_read() {
        let root = crate::scratch::scratch("schema-r4b-3");
        let files = [
            (
                "tests/pm.rs",
                "#[cfg_attr(unix, path = \"shared/a.rs\")]\nmod a;\n#[path = r\"shared/b.rs\"]\nmod b;\n",
            ),
            ("tests/shared/a.rs", ""),
            ("tests/shared/b.rs", ""),
            ("tests/mm.rs", "declare!(hidden);\n"),
            ("tests/elsewhere/hidden.rs", ""),
        ];
        for (path, text) in files {
            std::fs::create_dir_all(root.join(path).parent().unwrap()).unwrap();
            std::fs::write(root.join(path), text).unwrap();
        }
        let dirs = [(String::from("fix"), String::new())].into();
        let pm = crate_sources(&root, &dirs, "fix::pm", None).unwrap();
        assert!(pm.contains(&String::from("tests/shared/a.rs")), "{pm:?}");
        assert!(pm.contains(&String::from("tests/shared/b.rs")), "{pm:?}");
        let mm = crate_sources(&root, &dirs, "fix::mm", None).unwrap();
        assert!(
            mm.contains(&String::from("tests/elsewhere/hidden.rs")),
            "{mm:?}"
        );
    }

    /// R4b-6 (CLOUD-2904, round 4b): a marker is a macro call's tokens, so a
    /// name ending in `line` compared with `!=` observes nothing.
    ///
    /// Fails by: markers found in run-together code text, where `aline != x`
    /// reads as `line!` and keys its item at its position.
    #[test]
    fn a_name_ending_in_a_marker_observes_nothing() {
        let source = "pub fn f(aline: u8, x: u8) -> bool { aline != x }\n\
                      pub const C: bool = { let column = 1; column != 2 };\n";
        let render = |text: &str| {
            render_in(
                text,
                &[],
                &BTreeSet::new(),
                Some(0),
                &FileScope::of("src/lib.rs"),
            )
        };
        let held = render(source);
        assert!(held.compiled.observing.is_empty(), "{:?}", held.compiled);
        let moved = render(&format!("\n{source}"));
        assert_eq!(moved.items, held.items, "an item's digest");
        assert_eq!(moved.probes, held.probes, "a function's digest");
    }

