    /// Fails by: a build output read from another package's `OUT_DIR`, or
    /// from a build directory with none (CLOUD-2904).
    #[test]
    fn a_packages_build_output_is_its_own_out_dir() {
        let target = crate::scratch::scratch("schema-built-outputs");
        let write = |path: &str, text: &str| {
            std::fs::create_dir_all(target.join(path).parent().unwrap()).unwrap();
            std::fs::write(target.join(path), text).unwrap();
        };
        write("debug/build/p-abc/out/x.bin", "1");
        write("debug/build/q-def/out/y.bin", "1");
        write("debug/build/p-zzz/output", "1");
        let packages = [(String::from("p"), String::from("crates/p"))].into();
        let held = built_outputs(&target, &packages);
        assert_eq!(held.len(), 1, "{held:?}");
        write("debug/build/q-def/out/y.bin", "2");
        assert_eq!(built_outputs(&target, &packages), held, "another package's");
        write("debug/build/p-abc/out/x.bin", "2");
        assert_ne!(built_outputs(&target, &packages), held, "its own");
    }

    /// Fails by: a source directory named `target` below the root left out of
    /// a tree read without git, or the root's own `target` read (CLOUD-2904).
    #[test]
    fn a_tree_without_git_reads_all_but_its_roots_target() {
        let root = crate::scratch::scratch("schema-tree-rust-files");
        for path in ["src/target/a.rs", "target/b.rs"] {
            std::fs::create_dir_all(root.join(path).parent().unwrap()).unwrap();
            std::fs::write(root.join(path), "").unwrap();
        }
        let files = tree_rust_files(&root).unwrap();
        assert!(
            files.contains(&String::from("src/target/a.rs")),
            "{files:?}"
        );
        assert!(!files.contains(&String::from("target/b.rs")), "{files:?}");
    }

    /// A name with several definitions keys every one of them, but a case
    /// that names it is not walked on through what they mention (owner
    /// ruling 2026-11-24): an edit reached only through such a name moves no
    /// case naming it, and a doc edit on one of its impls none either.
    ///
    /// Fails by: a type and its impl followed (D244, D264), so an edit to a
    /// field's type re-keyed every case that names the type; or the type's
    /// own definitions left unkeyed.
    #[test]
    fn a_name_with_several_definitions_is_keyed_but_not_followed() {
        let tree = |label: &str, lib: &str| {
            crate_case(
                label,
                ("g::t", "fix::it"),
                &[
                    ("src/lib.rs", lib),
                    ("tests/it/main.rs", "mod g;\n"),
                    (
                        "tests/it/g.rs",
                        "#[test]\nfn t() { let _held: Option<fix::T> = None; }\n",
                    ),
                ],
                &[],
            )
        };
        let lib = |field: &str, doc: &str, body: &str| {
            format!(
                "pub struct T {{ pub u: U, pub n: {body} }}\n{doc}impl T {{ pub fn m(&self) {{}} }}\n\
                 pub struct U({field});\n"
            )
        };
        let held = tree("schema-multi-held", &lib("u8", "", "u8"));
        assert_eq!(
            tree("schema-multi-field", &lib("u16", "", "u8")),
            held,
            "U is reached only through T, which answers to two items"
        );
        assert_eq!(
            tree("schema-multi-doc", &lib("u8", "/// The methods.\n", "u8")),
            held,
            "a doc edit on one of T's impls"
        );
        assert_ne!(
            tree("schema-multi-own", &lib("u8", "", "u16")),
            held,
            "T's own definition is keyed"
        );
    }

    /// A doc comment moves no item's digest, unless a derive or an attribute
    /// macro on an enclosing item can read it, as clap reads help text.
    ///
    /// Fails by: `///` keyed as code (it lexes as `OUTER_DOC_COMMENT`, not
    /// `COMMENT`), so a doc edit on an impl re-keyed every case reaching it;
    /// or a derive's doc input left unkeyed.
    #[test]
    fn a_doc_comment_is_keyed_only_where_a_macro_reads_it() {
        let digests = |source: &str| {
            render_in(
                source,
                &[],
                &BTreeSet::new(),
                Some(0),
                &FileScope::of("src/lib.rs"),
            )
            .items
        };
        let plain = |doc: &str| format!("{doc}pub struct Plain(u8);\n{doc}impl Plain {{}}\n");
        assert_eq!(digests(&plain("")), digests(&plain("/// Said.\n")));
        let derived =
            |doc: &str| format!("#[derive(Parser)]\n{doc}pub struct Args {{ pub n: u8 }}\n");
        assert_ne!(
            digests(&derived("/// One help text.\n")),
            digests(&derived("/// Another help text.\n")),
            "a derive reads it"
        );
    }

    /// Fails by: a type's one impl left unfollowed, or a method name's impl
    /// followed for a declaration the name also has (CLOUD-2904).
    #[test]
    fn an_impl_is_followed_under_its_types_name_alone() {
        let follow = |names: [&str; 2]| -> Vec<usize> {
            let definitions: Vec<&str> = names.to_vec();
            let items: std::collections::BTreeMap<String, BTreeSet<String>> =
                [(names[0].to_owned(), [String::from("d")].into())].into();
            followed(&[0, 1], &definitions, &items).collect()
        };
        let impl_of = |name: &str| format!("{name}{IMPL_DEFINED}");
        let typed = impl_of("A");
        assert_eq!(follow(["A", &typed]), [0, 1], "a type and its impl");
        let method = format!("{ASSOCIATED}m");
        let method_impl = impl_of(&method);
        assert_eq!(follow([&method, &method_impl]), [0], "a method and an impl");
    }

    /// One integration case's digest over `files`, with `src/lib.rs` the
    /// probed source and the case running nothing probed.
    fn crate_case(
        label: &str,
        (name, binary): (&str, &str),
        files: &[(&str, &str)],
        ids: &[(&str, &str)],
    ) -> String {
        let case = (name.to_owned(), binary.to_owned());
        let cases: BTreeSet<Case> = [case.clone()].into();
        let executed = [(case.clone(), BTreeSet::new())].into();
        let resources = ids
            .iter()
            .map(|(path, id)| ((*path).to_owned(), (*id).to_owned()))
            .collect();
        tree_digests(label, &cases, &executed, files, &resources)[&case].clone()
    }

    /// R4-2 (CLOUD-2904, round 4): a crate's shared items are the same for
    /// every case of it, so the second case of a binary keys the first case's
    /// module file it calls into.
    ///
    /// Fails by: the shared items cached per binary over the first case's
    /// crate minus that case's own file, which the second case then lacks.
    #[test]
    fn a_later_case_keys_an_earlier_cases_module_it_calls() {
        let tree = |label: &str, value: &str| {
            let first = (String::from("a::ta"), String::from("fix::it"));
            let second = (String::from("b::tb"), String::from("fix::it"));
            let cases: BTreeSet<Case> = [first.clone(), second.clone()].into();
            let executed = [
                (first.clone(), BTreeSet::new()),
                (second.clone(), BTreeSet::new()),
            ]
            .into();
            let a = format!("pub fn helper() -> u8 {{ {value} }}\n#[test]\nfn ta() {{}}\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod a;\nmod b;\n"),
                    ("tests/it/a.rs", &a),
                    (
                        "tests/it/b.rs",
                        "#[test]\nfn tb() { assert_eq!(crate::a::helper(), 1); }\n",
                    ),
                ],
                &std::collections::BTreeMap::new(),
            )[&second]
                .clone()
        };
        assert_ne!(tree("schema-r4-2-a", "1"), tree("schema-r4-2-b", "2"));
    }

    /// R4-3 (CLOUD-2904, round 4): a test in a nested module of an
    /// integration file keys a helper function of the module enclosing it.
    ///
    /// Fails by: the enclosing module's functions dropped from the test's
    /// text and its own file left out of the crate's shared items.
    #[test]
    fn a_nested_integration_test_keys_its_enclosing_modules_helper() {
        let tree = |label: &str, value: &str| {
            let n = format!(
                "fn helper() -> u8 {{ {value} }}\nmod inner {{\n    #[test]\n    \
                 fn t() {{ assert_eq!(super::helper(), 1); }}\n}}\n"
            );
            crate_case(
                label,
                ("n::inner::t", "fix::it"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod n;\n"),
                    ("tests/it/n.rs", &n),
                ],
                &[],
            )
        };
        assert_ne!(tree("schema-r4-3-a", "1"), tree("schema-r4-3-b", "2"));
    }

    /// R4-4 (CLOUD-2904, round 4): a file an integration test includes at
    /// compile time is keyed by content.
    ///
    /// Fails by: includes recorded only in probed files, never in `tests/`.
    #[test]
    fn an_integration_tests_include_keys_the_case() {
        let tree = |label: &str, id: &str| {
            crate_case(
                label,
                ("s::t", "fix::it"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod s;\n"),
                    (
                        "tests/it/s.rs",
                        "#[test]\nfn t() { assert_eq!(include_str!(\"data.txt\"), \"x\"); }\n",
                    ),
                ],
                &[("tests/it/data.txt", id)],
            )
        };
        assert_ne!(tree("schema-r4-4-a", "1"), tree("schema-r4-4-b", "2"));
        let nested = render_in(
            "pub fn f() -> bool { assert_eq!(include_str!(\"x.txt\"), \"\"); true }\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("src/lib.rs"),
        );
        assert_eq!(
            nested.compiled.probe_includes,
            [(0, [String::from("src/x.txt")].into())].into(),
            "an include in a macro's arguments, in a probed file"
        );
        // Another macro beside it is no include: `format!("y.txt")` names no
        // file the build reads (CLOUD-2789, the include name is the predicate).
        let beside = render_in(
            "pub fn f() -> bool { assert_eq!(include_str!(\"x.txt\"), format!(\"y.txt\")); true }\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("src/lib.rs"),
        );
        assert_eq!(
            beside.compiled.probe_includes,
            [(0, [String::from("src/x.txt")].into())].into(),
            "a non-include macro in a macro's arguments"
        );
    }

    /// R4-5 (CLOUD-2904, round 4): a case whose function no source names as
    /// listed (an `rstest` case, a macro's test, a `mod.rs` module) still
    /// keys what its file names, as a found case keys what its own text does.
    ///
    /// Fails by: an unfound case's file starting no walk, so a `const` it
    /// names in the crate under test is unkeyed.
    #[test]
    fn an_unfound_case_keys_what_its_file_names() {
        let tree = |label: &str, value: &str| {
            let lib = format!("pub const LIMIT: u8 = {value};\npub fn f() {{}}\n");
            crate_case(
                label,
                ("r::t::case_1", "fix::it"),
                &[
                    ("src/lib.rs", &lib),
                    ("tests/it/main.rs", "mod r;\n"),
                    (
                        "tests/it/r.rs",
                        "#[rstest]\n#[case(1)]\nfn t(#[case] n: u8) { assert_eq!(n, fix::LIMIT); }\n",
                    ),
                ],
                &[],
            )
        };
        assert_ne!(tree("schema-r4-5-a", "1"), tree("schema-r4-5-b", "2"));
    }

    /// R4-6 (CLOUD-2904, round 4): a single-file target's own module beside
    /// it, not named `common`, is keyed.
    ///
    /// Fails by: a single-file target's crate read as its `tests/<target>/`
    /// directory and `tests/common/` alone.
    #[test]
    fn a_single_file_targets_own_module_keys_the_case() {
        let tree = |label: &str, value: &str| {
            let support = format!("pub fn v() -> u8 {{ {value} }}\n");
            crate_case(
                label,
                ("t", "fix::foo"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    (
                        "tests/foo.rs",
                        "mod support;\n#[test]\nfn t() { assert_eq!(support::v(), 1); }\n",
                    ),
                    ("tests/support.rs", &support),
                ],
                &[],
            )
        };
        assert_ne!(tree("schema-r4-6-a", "1"), tree("schema-r4-6-b", "2"));
    }

    /// R4-17 (CLOUD-2904, round 4): a `#[path]` module of a test crate and a
    /// file it `include!`s are keyed.
    ///
    /// Fails by: a `#[path]` module outside the walked directories, or an
    /// `include!`d file, unkeyed (`tests/policy_modules.rs`,
    /// `tests/it/fuzz_corpus.rs`).
    #[test]
    fn a_test_crates_path_module_and_include_key_the_case() {
        let pathed = |label: &str, value: &str| {
            let helpers = format!("pub fn v() -> u8 {{ {value} }}\n");
            crate_case(
                label,
                ("t", "fix::pm"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    (
                        "tests/pm.rs",
                        "#[path = \"shared/helpers.rs\"]\nmod helpers;\n\
                         #[test]\nfn t() { assert_eq!(helpers::v(), 1); }\n",
                    ),
                    ("tests/shared/helpers.rs", &helpers),
                ],
                &[],
            )
        };
        assert_ne!(
            pathed("schema-r4-17-a", "1"),
            pathed("schema-r4-17-b", "2"),
            "the #[path] module"
        );
        let included = |label: &str, id: &str| {
            crate_case(
                label,
                ("fz::t", "fix::it"),
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod fz;\n"),
                    (
                        "tests/it/fz.rs",
                        "include!(\"../../fuzz/p.rs\");\n#[test]\nfn t() { assert!(prop()); }\n",
                    ),
                ],
                &[("fuzz/p.rs", id)],
            )
        };
        assert_ne!(
            included("schema-r4-17-c", "1"),
            included("schema-r4-17-d", "2"),
            "the include!d file"
        );
    }

    /// S3 (CLOUD-2904, round 3): a test's text carries the items of every
    /// module enclosing it that it reaches, so an edit to a top-level `const`
    /// a test in `mod tests` names moves the test's text, while an edit to a
    /// top-level function, the code under test, does not.
    ///
    /// Fails by: only the test's own module's items keyed, or an enclosing
    /// module's functions keyed as helpers (an edit to the code under test
    /// moves every case in the file).
    #[test]
    fn a_tests_text_carries_its_enclosing_modules_items() {
        let source = |value: &str, code: &str| {
            format!(
                "const TOP: u8 = {value};\nfn code() -> u8 {{ {code} }}\nmod tests {{\n    \
                 #[test]\n    fn t() {{ assert_eq!(super::TOP, super::code()); }}\n}}\n"
            )
        };
        let held = test_texts(&source("1", "1"));
        assert_ne!(test_texts(&source("2", "1"))["t"], held["t"], "TOP");
        assert_eq!(
            test_texts(&source("1", "2"))["t"],
            held["t"],
            "the code under test"
        );
    }

    /// S4 (CLOUD-2904, round 3): what a case's own test text names starts the
    /// skeleton walk, so an edit to a `const` a test names directly, which no
    /// function the case ran names, moves the case.
    ///
    /// Fails by: only the functions a case ran starting the walk.
    #[test]
    fn what_a_test_names_directly_keys_its_case() {
        let t = (String::from("tests::t"), String::from("fix"));
        let cases: BTreeSet<Case> = [t.clone()].into();
        let executed = [(t.clone(), BTreeSet::new())].into();
        let none = std::collections::BTreeMap::new();
        // IN ANOTHER FILE (round 4 #18): one beside the test is in the test's
        // own text already ([`test_texts`]), which kept this case green with
        // the walk from that text removed.
        let lib = "pub mod config;\n#[cfg(test)]\nmod tests {\n    #[test]\n    \
                   fn t() { assert_eq!(crate::config::LIMIT, 1); }\n}\n";
        let digest = |label: &str, value: &str| {
            let config = format!("pub const LIMIT: u8 = {value};\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[("src/config.rs", &config), ("src/lib.rs", lib)],
                &none,
            )[&t]
                .clone()
        };
        assert_ne!(digest("schema-own-a", "1"), digest("schema-own-b", "2"));
    }

    /// S5/S6 (CLOUD-2904, round 3): an impl in a shared module answers to its
    /// trait and methods too, so a trait impl for `()` or `str` a case calls
    /// by method is taken.
    ///
    /// Fails by: an impl answering only to its self type's names (`()` names
    /// none, and `str` is not what the case writes).
    #[test]
    fn a_shared_impl_answers_to_its_trait_and_methods() {
        let unit = [String::from("fn t() { ().go(); }")];
        let common = |value: &str| {
            format!(
                "pub trait Tr {{ fn go(&self) -> u8; }}\n\
                 impl Tr for () {{ fn go(&self) -> u8 {{ {value} }} }}\n"
            )
        };
        assert_ne!(
            common_reached(&common("1"), &unit),
            common_reached(&common("2"), &unit),
            "impl Tr for ()"
        );
        let text = [String::from("fn t() { \"a\".shout(); }")];
        let shout = |value: &str| {
            format!(
                "pub trait Shout {{ fn shout(&self) -> u8; }}\n\
                 impl Shout for str {{ fn shout(&self) -> u8 {{ {value} }} }}\n"
            )
        };
        assert_ne!(
            common_reached(&shout("1"), &text),
            common_reached(&shout("2"), &text),
            "impl Shout for str"
        );
        // BY ITS TRAIT'S NAME ALONE (round 4 #22): a foreign trait's impl for
        // `()`, named by no method the text calls and no self-type name.
        let named = [String::from(
            "fn t() { let _ = <() as Display>::to_string(&()); }",
        )];
        let display = |value: &str| {
            format!(
                "impl Display for () {{ fn fmt(&self, f: &mut F) -> R {{ write!(f, \"{value}\") }} }}\n"
            )
        };
        assert_ne!(
            common_reached(&display("a"), &named),
            common_reached(&display("b"), &named),
            "impl Display for (), named by its trait"
        );
    }

    /// R4-9 (CLOUD-2904, round 4): a function or an item that reads where it
    /// is (`file!`, `module_path!`, `type_name`) is keyed with its file, so
    /// one moved whole to another file moves.
    ///
    /// Fails by: such text keyed on its tokens alone, which a move keeps.
    #[test]
    fn text_reading_its_file_or_module_is_keyed_with_it() {
        let source = "pub fn f() -> &'static str { module_path!() }\n\
                      pub const P: &str = file!();\n";
        let render =
            |file: &str| render_in(source, &[], &BTreeSet::new(), Some(0), &FileScope::of(file));
        let (a, b) = (render("src/a.rs"), render("src/b.rs"));
        assert_ne!(a.probes, b.probes, "module_path! in a function");
        let digests = |rendered: &Rendered| -> BTreeSet<String> {
            rendered
                .items
                .iter()
                .filter(|(name, _)| bare(name) == "P")
                .map(|(_, digest)| digest.clone())
                .collect()
        };
        assert_ne!(digests(&a), digests(&b), "file! in a const");
    }

    /// R4-7 (CLOUD-2904, round 4): a method call's trait in scope is keyed
    /// through `use super::*`, through a glob of another module's `pub use`,
    /// and from a `macro_rules!` body expanded in the caller's module.
    ///
    /// Fails by: a call reaching only its own module's `use`s, so swapping
    /// the trait an imported glob or a macro's expansion brings into scope
    /// moved no case.
    #[test]
    fn a_trait_brought_into_scope_by_a_glob_or_a_macro_keys_the_call() {
        let run = case("scoped");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [2].into())].into();
        let none = std::collections::BTreeMap::new();
        let traits = "mod t1 { pub trait Tr { fn go(&self) -> u8; } impl Tr for u8 { fn go(&self) -> u8 { 1 } } }\n\
                      mod t2 { pub trait Tr { fn go(&self) -> u8; } impl Tr for u8 { fn go(&self) -> u8 { 2 } } }\n";
        let digest = |label: &str, scoped: &str| {
            let lib = format!("{traits}{scoped}");
            tree_digests(label, &cases, &executed, &[("src/lib.rs", &lib)], &none)[&run].clone()
        };
        for (shape, scoped) in [
            (
                "use super::*",
                "mod m {{ use crate::{T}::Tr; pub mod child {{ use super::*; \
                 pub fn f() -> u8 {{ 0u8.go() }} }} }}\n",
            ),
            (
                "a prelude glob",
                "mod prelude {{ pub use crate::{T}::Tr; }}\n\
                 mod m {{ use crate::prelude::*; pub fn f() -> u8 {{ 0u8.go() }} }}\n",
            ),
            (
                "a macro body",
                "mod m {{ use crate::{T}::Tr; macro_rules! call {{ () => {{ 0u8.go() }} }} \
                 pub fn f() -> u8 {{ call!() }} }}\n",
            ),
        ] {
            let render = |which: &str| {
                scoped
                    .replace("{T}", which)
                    .replace("{{", "{")
                    .replace("}}", "}")
            };
            assert_ne!(
                digest(&format!("schema-r4-7-{}-a", shape.len()), &render("t1")),
                digest(&format!("schema-r4-7-{}-b", shape.len()), &render("t2")),
                "{shape}"
            );
        }
    }

    /// R4-21 (CLOUD-2904, round 4): a glob `use` a function's module holds is
    /// reached by every mention the function makes, so a case that ran it
    /// moves when the glob changes what a name resolves to.
    ///
    /// Fails by: a mention not reaching its module's glob `use`s.
    #[test]
    fn a_modules_glob_use_keys_a_case_that_ran_its_function() {
        let run = case("glob");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [2].into())].into();
        let none = std::collections::BTreeMap::new();
        let digest = |label: &str, from: &str| {
            let lib = format!(
                "mod a {{ pub fn helper() -> u8 {{ 1 }} }}\nmod b {{ pub fn helper() -> u8 {{ 2 }} }}\n\
                 mod m {{ use crate::{from}::*; pub fn f() -> u8 {{ helper() }} }}\n"
            );
            tree_digests(label, &cases, &executed, &[("src/lib.rs", &lib)], &none)[&run].clone()
        };
        assert_ne!(digest("schema-r4-21-a", "a"), digest("schema-r4-21-b", "b"));
    }

    /// R4-10 (CLOUD-2904, round 4): a function under `#[cfg(test)]` or an
    /// `rstest` fixture is a helper of the test beside it, not a test.
    ///
    /// Fails by: any attribute naming `test` read as a test's, so such a
    /// helper was dropped from the text of the test calling it.
    #[test]
    fn a_cfg_test_helper_or_fixture_is_its_tests_helper() {
        let texts = |value: &str| {
            test_texts(&format!(
                "mod tests {{\n    #[cfg(test)]\n    fn helper() -> u8 {{ {value} }}\n    \
                 #[rstest::fixture]\n    fn fx() -> u8 {{ 0 }}\n    #[test]\n    \
                 fn t() {{ assert_eq!(helper(), fx()); }}\n    #[tokio::test]\n    async fn u() {{}}\n}}\n"
            ))
        };
        let held = texts("1");
        assert!(held.contains_key("t") && held.contains_key("u"), "{held:?}");
        assert!(
            !held.contains_key("helper") && !held.contains_key("fx"),
            "{held:?}"
        );
        assert_ne!(held["t"], texts("2")["t"], "the cfg(test) helper");
    }

    /// S7 (CLOUD-2904, round 3): what a test module's own items name reaches
    /// the shared module, so a `static` a test calls through, which names a
    /// `common` helper, takes that helper.
    ///
    /// Fails by: only the test's and its helpers' words reaching `common`.
    #[test]
    fn a_test_modules_items_reach_the_shared_module() {
        let t = (String::from("x::t"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [t.clone()].into();
        let executed = [(t.clone(), BTreeSet::new())].into();
        let none = std::collections::BTreeMap::new();
        let digest = |label: &str, value: &str| {
            let common = format!("pub fn helper() -> u8 {{ {value} }}\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod common;\nmod x;\n"),
                    ("tests/it/common/mod.rs", &common),
                    (
                        "tests/it/x.rs",
                        "use crate::common::helper;\nstatic CALL: fn() -> u8 = helper;\n\
                         #[test]\nfn t() { assert_eq!(CALL(), 1); }\n",
                    ),
                ],
                &none,
            )[&t]
                .clone()
        };
        assert_ne!(digest("schema-items-a", "1"), digest("schema-items-b", "2"));
    }

    /// S8 (CLOUD-2904, round 3): every mention reaches its module's `use`s,
    /// so swapping the trait a module imports moves the case calling its
    /// method there, though nothing names the trait.
    ///
    /// Fails by: a `use` reached only through the name it binds.
    #[test]
    fn swapping_a_modules_trait_import_moves_its_cases() {
        let run = case("run");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [0].into())].into();
        let source = |from: &str| {
            format!(
                "pub fn run(x: u8) -> u8 {{ x.go() }}\nuse {from}::Ext;\n\
                 mod a {{ pub trait Ext {{ fn go(&self) -> u8; }} }}\n\
                 mod b {{ pub trait Ext {{ fn go(&self) -> u8; }} }}\n"
            )
        };
        assert_ne!(
            source_digests(&cases, &executed, &source("a"))[&run],
            source_digests(&cases, &executed, &source("b"))[&run]
        );
    }

    /// S9/S15 (CLOUD-2904, round 3): a case that runs a `#[track_caller]`
    /// function or reaches a macro expanding `line!()` is keyed on where the
    /// functions it ran sit, so a line added above the caller moves it.
    ///
    /// Fails by: only the callee's or the macro's own position keyed.
    #[test]
    fn a_callers_position_keys_a_case_observing_it() {
        let runs = case("runs");
        let cases: BTreeSet<Case> = [runs.clone()].into();
        let executed = [(runs.clone(), [0, 1].into())].into();
        let tracked = |gap: &str| {
            format!(
                "#[track_caller]\npub fn here() -> u32 {{ std::panic::Location::caller().line() }}\n\
                 {gap}pub fn caller() -> u32 {{ here() }}\n"
            )
        };
        assert_ne!(
            source_digests(&cases, &executed, &tracked(""))[&runs],
            source_digests(&cases, &executed, &tracked("\n"))[&runs],
            "a track_caller callee"
        );
        let one = [(runs.clone(), [0].into())].into();
        let expanded = |gap: &str| {
            format!(
                "macro_rules! at {{ () => {{ line!() }} }}\n{gap}pub fn caller() -> u32 {{ at!() }}\n"
            )
        };
        assert_ne!(
            source_digests(&cases, &one, &expanded(""))[&runs],
            source_digests(&cases, &one, &expanded("\n"))[&runs],
            "a macro expanding line!()"
        );
    }

    /// S10/S14 (CLOUD-2904, round 3): a skeleton item keys spacing inside a
    /// macro's token tree, and one observing its position keys its whole
    /// text, so a line added inside it moves the case naming it.
    ///
    /// Fails by: a skeleton item keyed on its tokens alone.
    #[test]
    fn a_skeleton_item_keys_token_tree_spacing_and_its_inner_lines() {
        let names = case("names");
        let cases: BTreeSet<Case> = [names.clone()].into();
        let executed = [(names.clone(), [0].into())].into();
        let spaced =
            |op: &str| format!("pub fn names() -> u8 {{ X }}\nconst X: u8 = m!(1 {op} 2);\n");
        assert_ne!(
            source_digests(&cases, &executed, &spaced("+="))[&names],
            source_digests(&cases, &executed, &spaced("+ ="))[&names],
            "spacing in a token tree"
        );
        let inner = |gap: &str| {
            format!("pub fn names() -> u32 {{ L }}\nconst L: u32 = {{\n{gap}    line!()\n}};\n")
        };
        assert_ne!(
            source_digests(&cases, &executed, &inner(""))[&names],
            source_digests(&cases, &executed, &inner("\n"))[&names],
            "a line inside the const"
        );
    }

    /// S11 (CLOUD-2904, round 3): an item an attribute registers is keyed into
    /// every case, and an exported symbol answers to its export name.
    ///
    /// Fails by: a `#[global_allocator]` reached by no name, or a static
    /// exported as `table` reached only as `T`.
    #[test]
    fn a_registered_or_exported_item_is_keyed_where_it_is_reached() {
        let run = case("run");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [0].into())].into();
        let allocator = |value: &str| {
            format!(
                "pub fn run() -> u8 {{ 1 }}\n#[global_allocator]\nstatic A: Alloc = Alloc({value});\n"
            )
        };
        assert_ne!(
            source_digests(&cases, &executed, &allocator("1"))[&run],
            source_digests(&cases, &executed, &allocator("2"))[&run],
            "the global allocator"
        );
        let exported = |value: &str| {
            format!(
                "pub fn run() -> u8 {{ unsafe {{ table }} }}\n\
                 unsafe extern \"C\" {{ static table: u8; }}\n\
                 #[unsafe(export_name = \"table\")]\nstatic T: u8 = {value};\n"
            )
        };
        assert_ne!(
            source_digests(&cases, &executed, &exported("1"))[&run],
            source_digests(&cases, &executed, &exported("2"))[&run],
            "the static exported as table"
        );
    }

    /// S13 (CLOUD-2904, round 3): the schema applies a package's flat scoping,
    /// so a private item of a package holding a `#[path]` module is keyed at
    /// the package, not at its module, though the module holding it is not
    /// the one the `#[path]` widens.
    ///
    /// Fails by: the production line setting [`FileScope::flat`] dropped (the
    /// suite stayed green without it; with `helper` in the root module, the
    /// widened module alone keyed it at the package).
    #[test]
    fn the_schema_scopes_a_moved_package_flat() {
        let root = crate::scratch::scratch("schema-flat-write");
        let work = crate::scratch::scratch("schema-flat-work");
        for tree in [&root, &work] {
            std::fs::create_dir_all(tree.join("p/src")).unwrap();
            std::fs::write(tree.join("p/Cargo.toml"), "[package]\nname = \"p\"\n").unwrap();
            std::fs::write(
                tree.join("p/src/lib.rs"),
                "#[path = \"x.rs\"]\nmod x;\nmod inner {\n    pub const fn helper() -> u8 { 1 }\n    const fn hidden() -> u8 { 1 }\n}\npub fn f() -> bool { inner::helper() == 1 }\n",
            )
            .unwrap();
            std::fs::write(tree.join("p/src/x.rs"), "pub fn g() {}\n").unwrap();
        }
        let mutant = Listed {
            file: String::from("p/src/lib.rs"),
            ..listed("BinaryOperator", "!=", (7, 38), (7, 40))
        };
        let schema =
            write_schema(&root, &work, &[mutant], &BTreeSet::new(), &BTreeSet::new()).unwrap();
        assert!(
            schema.items.contains_key(&format!("hidden{DEFINED_IN}p")),
            "{:?}",
            schema.items.keys().collect::<Vec<_>>()
        );
        assert!(
            !schema
                .items
                .contains_key(&format!("hidden{DEFINED_IN}p{DEFINED_IN}src::inner"))
        );
    }

    /// An impl answers to its header's unqualified names, and its members'
    /// own names in an associated position only ([`associated_names`]); a
    /// `use` to each leaf's last segment or rename, and to the
    /// module a glob globs; an item macro to each name after an item keyword,
    /// or to every name when it has none.
    ///
    /// Fails by: an impl answering to a member body or a path's qualifier, a
    /// `use` to the path it imports from, or a `thread_local!` to its type.
    #[test]
    fn an_impl_a_use_and_an_item_macro_answer_to_what_they_bind() {
        let source = "impl<T: Bound> std::fmt::Display for Known<T> where T: Other {\n\
                          const C: u8 = 1;\n\
                          fn fmt(&self) -> String { String::new() }\n\
                      }\n\
                      use a::{b::C as D, e, f::{self}, g::*};\n\
                      thread_local! { static X: u8 = y(); pub static mut Z: u8 = 0; }\n\
                      mutants!(alpha, beta);\n";
        let names: Vec<Vec<String>> = items_of(source).iter().map(item_names).collect();
        let owned = |list: &[&str]| {
            list.iter()
                .map(|name| (*name).to_owned())
                .collect::<Vec<_>>()
        };
        assert_eq!(
            names,
            [
                owned(&["Bound", "Display", "Known", "Other", "T"]),
                owned(&["D", "e", "f", "g"]),
                owned(&["X", "Z"]),
                owned(&["alpha", "beta", "mutants"]),
            ]
        );
        let associated: Vec<Vec<String>> = items_of(source).iter().map(associated_names).collect();
        assert_eq!(
            associated,
            [owned(&["C", "fmt"]), owned(&[]), owned(&[]), owned(&[])]
        );
    }

    /// An item keyword whose next token is not a name names nothing: the
    /// token between ends the wait, so a later identifier is not the item's.
    ///
    /// Fails by: the trivia-or-keyword guard read as always true (shard
    /// 4/16's survivor), so `y` of `type = y` reads as a name the macro binds.
    #[test]
    fn an_item_keyword_not_followed_by_a_name_names_nothing() {
        let names: Vec<Vec<String>> = items_of("m! { static X: u8 = 0; type = y; }\n")
            .iter()
            .map(item_names)
            .collect();
        assert_eq!(names, [vec![String::from("X")]]);
    }

    /// A member of an impl or trait answers to its own name in an associated
    /// position only; a free item answers to it freely.
    ///
    /// Fails by: `is_member` read as false, or `associated_names`' member arm
    /// never taken (shard 0/8's survivors), so a member's name is free and a
    /// local of that spelling moves every case naming it (CLOUD-2904).
    #[test]
    fn a_member_answers_to_its_name_in_an_associated_position_only() {
        let source = "impl Host { fn here(&self) {} }\n\
                      trait Kind { fn kind(&self); }\n\
                      fn free() {}\n";
        let functions: Vec<ast::Item> =
            batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
                .tree()
                .syntax()
                .descendants()
                .filter_map(ast::Item::cast)
                .filter(|item| matches!(item, ast::Item::Fn(_)))
                .collect();
        let free: Vec<Vec<String>> = functions.iter().map(item_names).collect();
        let associated: Vec<Vec<String>> = functions.iter().map(associated_names).collect();
        let one = |name: &str| vec![String::from(name)];
        assert_eq!(free, [vec![], vec![], one("free")]);
        assert_eq!(associated, [one("here"), one("kind"), vec![]]);
    }

    /// `pub` is the workspace, a restricted `pub(..)` the package, and
    /// `pub(self)` or no visibility the module.
    ///
    /// Fails by: the `words == "pub"` test inverted (shard 0/8's survivor), so
    /// a `pub` item is keyed to its package and a `pub(crate)` one to the
    /// workspace.
    #[test]
    fn a_visibility_bounds_where_its_item_is_seen() {
        let seen: Vec<Visible> =
            items_of("pub fn a() {}\npub(crate) fn b() {}\npub(self) fn c() {}\nfn d() {}\n")
                .iter()
                .map(visibility)
                .collect();
        assert_eq!(
            seen,
            [
                Visible::Workspace,
                Visible::Package,
                Visible::Module,
                Visible::Module
            ]
        );
    }

    /// A package-wide definition is seen from any module of its own package
    /// and from no other package.
    ///
    /// Fails by: the package comparison inverted (shard 7/8's survivor), so a
    /// `pub(crate)` item is reached only from the packages that cannot see it.
    #[test]
    fn a_package_wide_definition_is_seen_from_its_package_only() {
        let definition = format!("helper{DEFINED_IN}batten");
        let from = |package: &str| format!("helper{MENTIONED_IN}{package}{MENTIONED_IN}m::n");
        assert!(visible_from(&from("batten"), &definition));
        assert!(!visible_from(&from("batten_core"), &definition));
    }

    /// A `#[path = "…"]` attribute names its file as written; any other
    /// attribute names none.
    ///
    /// Fails by: `path_attr` answering a fixed path (shard 0/8's survivor),
    /// so every `#[path]` module includes a file that is not its own.
    #[test]
    fn a_path_attribute_names_the_file_it_writes() {
        let named: Vec<Option<String>> =
            items_of("#[path = \"a/b.rs\"]\nmod x;\n#[cfg(test)]\nmod y;\n")
                .iter()
                .filter_map(|item| match item {
                    ast::Item::Module(module) => ast::HasAttrs::attrs(module).next(),
                    _ => None,
                })
                .map(|attr| path_attr(&attr))
                .collect();
        assert_eq!(named, [Some(String::from("a/b.rs")), None]);
    }

    /// A `#[path]` module inside an inline module names a file under that
    /// module's directory as well as beside its file.
    ///
    /// Fails by: the inline-module guard inverted (shard 0/8's uncovered
    /// mutant), so a nested `#[path]` file is matched under its module path
    /// and its names are scoped to the wrong module.
    #[test]
    fn a_nested_path_module_includes_its_inline_modules_directory() {
        let root = crate::scratch::scratch("schema-nested-path-module");
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/lib.rs"),
            "mod outer {\n    #[path = \"p.rs\"]\n    mod inner;\n}\n",
        )
        .unwrap();
        let files = BTreeSet::from([String::from("src/lib.rs")]);
        assert_eq!(
            included_sources(&root, &files),
            BTreeSet::from([String::from("src/outer/p.rs"), String::from("src/p.rs")])
        );
    }

    /// A type-like item a module or type path wants is taken; one no such
    /// path names, or a function a type path happens to spell, is not.
    ///
    /// Fails by: the `a_type` disjointness inverted (shard 0/8's uncovered
    /// mutant), so a type is taken by every path but its own.
    #[test]
    fn a_type_is_taken_by_a_type_path_naming_it() {
        let items = items_of("struct Shape;\nfn shape() {}\n");
        let (shape, function) = (Shared::of(&items[0]), Shared::of(&items[1]));
        let none = BTreeSet::new();
        let wanted = |name: &str| BTreeSet::from([String::from(name)]);
        assert!(shape.answers(&none, &wanted("Shape")));
        assert!(!shape.answers(&none, &wanted("Other")));
        assert!(!function.answers(&none, &wanted("shape")));
    }

    /// Every `use` is taken, a named one too: a trait it imports is called by
    /// method with no name of it written (CLOUD-2904's soundness review). Its
    /// leaf takes any item, and its path before the leaf a module or type
    /// only; a glob has no leaf, so its whole path is a module's.
    ///
    /// Replaces shard 3/8's `a_use_answers_to_its_bindings_and_a_glob_is_always_taken`
    /// (CLOUD-2789), which pinned a named `use` taken only when its bound name
    /// was wanted: the under-invalidation the review found.
    ///
    /// Fails by: a named `use` taken only by its bound name, a leaf read as a
    /// module (so a function it imports is never taken), or a path segment
    /// read as any item (so `use batten::x` takes `fn batten`).
    #[test]
    fn a_use_is_always_taken_by_its_leaves_and_its_path() {
        /// What one `use` answers to, takes by any item and takes by a type.
        type Taken = (Option<BTreeSet<String>>, BTreeSet<String>, BTreeSet<String>);
        let shared: Vec<Taken> = items_of("use a::b;\nuse a::*;\nuse a::c as _;\n")
            .iter()
            .map(|item| {
                let it = Shared::of(item);
                (it.names, it.mentions, it.types)
            })
            .collect();
        let set = |names: &[&str]| -> BTreeSet<String> {
            names.iter().map(|name| (*name).to_owned()).collect()
        };
        assert_eq!(
            shared,
            [
                (None, set(&["b"]), set(&["a"])),
                (None, set(&[]), set(&["a"])),
                (None, set(&["c"]), set(&["a"])),
            ]
        );
    }

    /// An impl, a macro, an item macro, an extern block and an extern crate
    /// are keyed workspace-wide: no visibility bounds what reaches them.
    ///
    /// Fails by: their arm deleted (shard 3/8's survivor), so each falls to
    /// its absent visibility and is keyed to its module (CLOUD-2789).
    #[test]
    fn an_impl_or_a_macro_is_visible_workspace_wide() {
        let seen: Vec<Visible> = items_of(
            "impl T {}\nmacro_rules! m { () => {} }\nmacro n() {}\nm!();\n\
             extern \"C\" {}\nextern crate core;\n",
        )
        .iter()
        .map(visibility)
        .collect();
        assert_eq!(seen, [Visible::Workspace; 6]);
    }

    /// A traced case keys on the files it touched, an absent one and a
    /// directory's listing included, and on nothing else; an untraced case
    /// keys on every non-Rust file.
    ///
    /// Fails by: a traced case keyed on the untraced digest (an unread config
    /// edit moves it), a read path dropped (its edit reuses a stale verdict), an
    /// absent path keyed on nothing (a file appearing moves nothing), or a
    /// directory keyed on its own entry only (an added sibling moves nothing).
    #[test]
    fn a_traced_case_keys_on_what_it_touched_and_an_untraced_one_on_every_file() {
        let root = crate::scratch::scratch("schema-read-digests");
        let dirs = std::collections::BTreeMap::new();
        let none = std::collections::BTreeMap::new();
        let (traced, untraced) = (case("traced"), case("untraced"));
        let cases: BTreeSet<Case> = [traced.clone(), untraced.clone()].into();
        let read = [(
            traced.clone(),
            [
                String::from("fixture.txt"),
                String::from("missing.toml"),
                String::from("dir"),
            ]
            .into(),
        )]
        .into();
        let digests = |resources: &[(&str, &str)], all: &str| {
            let resources = resources
                .iter()
                .map(|(path, id)| ((*path).to_owned(), (*id).to_owned()))
                .collect();
            let depends = Depends {
                read: &read,
                resources: &resources,
                untraced: all,
                ..depends(&[])
            };
            case_digests(&root, &cases, &dirs, &none, &depends)
        };
        let base = [("fixture.txt", "1"), ("mutants.toml", "1"), ("dir/a", "1")];
        let held = digests(&base, "all-1");
        let config = digests(
            &[("fixture.txt", "1"), ("mutants.toml", "2"), ("dir/a", "1")],
            "all-2",
        );
        assert_eq!(
            config[&traced], held[&traced],
            "it never touched mutants.toml"
        );
        assert_ne!(
            config[&untraced], held[&untraced],
            "untraced keys on every file"
        );
        let fixture = digests(
            &[("fixture.txt", "2"), ("mutants.toml", "1"), ("dir/a", "1")],
            "all-1",
        );
        assert_ne!(fixture[&traced], held[&traced], "a file it read changed");
        let appeared = digests(
            &[("missing.toml", "1"), ("fixture.txt", "1"), ("dir/a", "1")],
            "all-1",
        );
        assert_ne!(
            appeared[&traced], held[&traced],
            "a path it probed for now exists"
        );
        let sibling = digests(
            &[("fixture.txt", "1"), ("dir/a", "1"), ("dir/b", "1")],
            "all-1",
        );
        assert_ne!(
            sibling[&traced], held[&traced],
            "a directory it read gained an entry"
        );
        let edited = digests(&[("fixture.txt", "1"), ("dir/a", "2")], "all-1");
        assert_eq!(
            edited[&traced], held[&traced],
            "a listing is names, not contents"
        );
    }

    /// The trace reader resolves each touched path against the descriptor
    /// strace printed, keeps the tree's own paths relative, and refuses a
    /// trace it cannot read whole.
    ///
    /// Fails by: a relative path kept unresolved, `target/` or a system path
    /// read as an input, a resumed line's result dropped, or a `.git` read, an
    /// unresolvable path or an undecoded escape answered as a partial set.
    #[test]
    fn a_trace_names_the_tree_paths_a_case_touched_or_nothing() {
        let tree = [std::path::PathBuf::from("/w")];
        let whole = |body: &str| {
            format!(
                "100 execve(\"/usr/bin/t\", [\"t\"], 0x7ff /* 1 vars */) = 0\n{body}\
                 101 +++ exited with 0 +++\n100 --- SIGCHLD {{si_signo=SIGCHLD}} ---\n\
                 100 +++ exited with 0 +++\n"
            )
        };
        let lines = "100 openat(AT_FDCWD</w/crates/batten>, \"tests/x.toml\", O_RDONLY) = 3</w/crates/batten/tests/x.toml>\n\
                     100 newfstatat(AT_FDCWD</w>, \"absent.toml\", 0x7ff, 0) = -1 ENOENT (No such file or directory)\n\
                     101 openat(AT_FDCWD</tmp>, \"/etc/ld.so.cache\", O_RDONLY) = 3</etc/ld.so.cache>\n\
                     101 openat(AT_FDCWD</w>, \"target/debug/x\", O_RDONLY) = 4</w/target/debug/x>\n\
                     102 <... openat resumed>) = 5</w/a/../b.txt>\n";
        assert_eq!(
            read_trace(Some(&whole(lines)), &tree),
            Ok(["crates/batten/tests/x.toml", "absent.toml", "b.txt"]
                .map(String::from)
                .into())
        );
        let git = "100 openat(AT_FDCWD</w>, \".git/index\", O_RDONLY) = 3</w/.git/index>\n";
        assert_eq!(
            read_trace(Some(&whole(git)), &tree),
            Err(Untraced::GitRead),
            "a .git read depends on every file"
        );
        let bare = "100 stat(\"relative\", 0x7ff) = 0\n";
        assert_eq!(
            read_trace(Some(&whole(bare)), &tree),
            Err(Untraced::Unreadable),
            "no directory to resolve against"
        );
        // `\x01` decodes since CLOUD-2835; `\q` is an escape strace never writes.
        let escaped = "100 openat(AT_FDCWD</w>, \"a\\q\", O_RDONLY) = 3</w/a>\n";
        assert_eq!(
            read_trace(Some(&whole(escaped)), &tree),
            Err(Untraced::Unreadable),
            "an escape this reader does not decode"
        );
        // A DETACHED TRACER'S PARTIAL TRACE IS NO TRACE: without the case's own
        // exit the tracer may still be writing, or never attached at all.
        let unfinished = whole(lines).replace("100 +++ exited with 0 +++\n", "");
        assert_eq!(
            read_trace(Some(&unfinished), &tree),
            Err(Untraced::Unfinished),
            "the case's exit is missing"
        );
        let child_only = format!(
            "100 execve(\"/usr/bin/t\", [], 0x7ff) = 0\n{lines}101 +++ exited with 0 +++\n"
        );
        assert_eq!(
            read_trace(Some(&child_only), &tree),
            Err(Untraced::Unfinished),
            "only a child's exit is no whole trace"
        );
        assert_eq!(
            read_trace(Some(""), &tree),
            Err(Untraced::Unfinished),
            "an empty trace says nothing"
        );
        // strace pads a short pid to five columns.
        let padded = whole(lines)
            .lines()
            .map(|line| line.replacen(' ', "   ", 1) + "\n")
            .collect::<String>();
        assert_eq!(
            read_trace(Some(&padded), &tree),
            read_trace(Some(&whole(lines)), &tree),
            "a padded pid column reads as the plain one"
        );
        let killed =
            whole(lines).replace("100 +++ exited with 0 +++", "100 +++ killed by SIGKILL +++");
        assert!(
            read_trace(Some(&killed), &tree).is_ok(),
            "a case killed by a signal finished"
        );
    }

    /// T6 (CLOUD-2904): an unread trace is recorded with its reason, never
    /// failed and never silent. `read_trace` answers `unfinished` over no text
    /// and over a trace with no root exit line, `unreadable` over a whole
    /// trace it cannot resolve, and `git-read` over a `.git` read;
    /// `record_trace` writes that reason and no `read`, and over a whole trace
    /// it writes `read` and no reason.
    ///
    /// Fails by: an unread trace recorded with no reason (an untraced case
    /// silently keys on every non-Rust file), a reason named for another, or a
    /// readable trace recorded as untraced.
    #[test]
    fn an_unread_trace_is_recorded_with_its_reason() {
        let tree = std::path::Path::new("/w");
        let whole = |body: &str| {
            format!(
                "100 execve(\"/usr/bin/t\", [\"t\"], 0x7ff) = 0\n{body}100 +++ exited with 0 +++\n"
            )
        };
        let read = "100 openat(AT_FDCWD</w>, \"a.toml\", O_RDONLY) = 3</w/a.toml>\n";
        let git = "100 openat(AT_FDCWD</w>, \".git/HEAD\", O_RDONLY) = 3</w/.git/HEAD>\n";
        let bare = "100 stat(\"relative\", 0x7ff) = 0\n";
        let unfinished = whole(read).replace("100 +++ exited with 0 +++\n", "");
        let roots = [tree.to_path_buf()];
        assert_eq!(
            read_trace(None, &roots),
            Err(Untraced::Unfinished),
            "no text"
        );
        for (text, reason) in [
            (unfinished.as_str(), "unfinished"),
            (whole(bare).as_str(), "unreadable"),
            (whole(git).as_str(), "git-read"),
        ] {
            let dir = crate::scratch::scratch("schema-record-trace");
            record_trace(&dir, Some(text), tree).unwrap();
            assert_eq!(
                crate::fsio::read_to_string(dir.join(UNTRACED)).unwrap(),
                reason
            );
            assert!(!dir.join(READ).exists(), "{reason}: no read listing");
        }
        let dir = crate::scratch::scratch("schema-record-trace-none");
        record_trace(&dir, None, tree).unwrap();
        assert_eq!(
            crate::fsio::read_to_string(dir.join(UNTRACED)).unwrap(),
            "unfinished"
        );
        let dir = crate::scratch::scratch("schema-record-trace-whole");
        record_trace(&dir, Some(&whole(read)), tree).unwrap();
        assert_eq!(
            crate::fsio::read_to_string(dir.join(READ)).unwrap(),
            "a.toml\n"
        );
        assert!(!dir.join(UNTRACED).exists(), "a traced case has no reason");
    }

    /// T5 (CLOUD-2904): the sweep reports its untraced cases by reason, in one
    /// classed line of counts with every reason's zero, and each way a case
    /// comes to be untraced maps to its reason.
    ///
    /// Fails by: an untraced case read as traced or counted under another
    /// reason, a reason left out of the line, or a traced case counted.
    #[test]
    fn the_sweep_reports_untraced_cases_by_reason() {
        let base = crate::scratch::scratch("schema-untraced-reasons");
        let record = |key: &str, untraced: Option<&str>| {
            let dir = base.join(key);
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(dir.join("case"), format!("{key}\tbin")).unwrap();
            std::fs::write(dir.join(DONE), "0").unwrap();
            match untraced {
                Some(reason) => std::fs::write(dir.join(UNTRACED), reason).unwrap(),
                None => std::fs::write(dir.join(READ), "a.toml\n").unwrap(),
            }
            dir
        };
        let mut dirs: Vec<std::path::PathBuf> = Untraced::ALL
            .iter()
            .map(|reason| record(reason.name(), Some(reason.name())))
            .collect();
        dirs.push(record("traced", None));
        let identity = Identity {
            probes: &[],
            sites: &[],
            mutant_fns: &std::collections::BTreeMap::new(),
            file_fns: &std::collections::BTreeMap::new(),
            classic: &BTreeSet::new(),
        };
        let reach = collect_dirs(dirs, &identity).unwrap();
        assert_eq!(
            untraced_line(&reach.untraced),
            "mutate schema: untraced 6 case(s): git-read 1, nested 1, no-tree 1, \
             tracer-absent 1, unfinished 1, unreadable 1"
        );
        assert_eq!(
            untraced_line(&std::collections::BTreeMap::new()),
            "mutate schema: untraced 0 case(s): git-read 0, nested 0, no-tree 0, \
             tracer-absent 0, unfinished 0, unreadable 0"
        );
        assert_eq!(untraced_reason(false, false, true), Some(Untraced::NoTree));
        assert_eq!(untraced_reason(true, true, false), Some(Untraced::Nested));
        assert_eq!(
            untraced_reason(true, false, false),
            Some(Untraced::TracerAbsent)
        );
        assert_eq!(untraced_reason(true, false, true), None, "traced");
        for reason in Untraced::ALL {
            assert_eq!(Untraced::parsed(reason.name()), Some(reason));
        }
        assert_eq!(Untraced::parsed("other"), None);
    }

    /// A handed-back mutant is judged by each case that ran its enclosing
    /// function or names its function through a chain of items; with neither
    /// to go on, by every case.
    ///
    /// Fails by: a const fn's caller through a const missed (its mutant judged
    /// by no case and read uncovered), an unrelated case selected, or a mutant
    /// with nothing to go on narrowed to nothing.
    /// Fails by: an `_` read as ending a name (`*c == '_'` as `!=` in
    /// `function_ident` or in `token_names`' capture), or a captured name that
    /// opens with `_` refused and one that opens with a digit taken (`c ==
    /// '_'` as `!=` on the capture's first character).
    #[test]
    fn an_underscore_is_part_of_a_name_and_may_open_one() {
        assert_eq!(function_ident("Foo::read_all").as_deref(), Some("read_all"));
        let parse = batten_facts::source::rust_parse(
            "fn f() { g(\"{_x} {a_b} {1y}\"); }\n",
            ra_ap_syntax::Edition::Edition2024,
        );
        let names = names_in(parse.tree().syntax());
        for name in ["_x", "a_b", "f", "g"] {
            assert!(names.contains(name), "{name} in {names:?}");
        }
        assert!(!names.contains("1y"), "{names:?}");
        assert!(!names.contains("a"), "{names:?}");
    }

    /// Fails by: the build's census never written, so a run reports no count
    /// of what it built and how long that took (CLOUD-2789).
    #[test]
    fn the_build_announces_its_counts_and_its_time() {
        let mut out = Vec::new();
        announce_built(&mut out, (13_869, 2_180, 281), 695).unwrap();
        assert_eq!(
            String::from_utf8(out).unwrap(),
            "mutate schema: 13869 mutant(s), 2180 unviable, 281 classic, built in 695s\n"
        );
    }

    /// CLOUD-2789: the control covers the cases a hand-back judged here can
    /// observe, and none for one judged elsewhere.
    ///
    /// Fails by: the hand-backs' cases answered empty (a mutant missed at
    /// 34c6e4d1f), so a case only a hand-back reaches runs unmutated nowhere
    /// and a red one is read as the mutant's kill.
    #[test]
    fn the_control_covers_the_cases_a_judged_handback_observes() {
        let schema = Schema {
            probes: vec![String::from("f-body")],
            mutant_fns: [(0, String::from("f-body"))].into(),
            probed: [String::from("src/lib.rs")].into(),
            ..Schema::default()
        };
        let body = case("body");
        let reach = Reach {
            executed: [(body.clone(), BTreeSet::from([0]))].into(),
            ..Reach::default()
        };
        let base = std::path::Path::new("/nonexistent-batten-handed-cases");
        let mutants = [listed("FnValue", "0", (1, 1), (1, 2))];
        let (listed_reach, seconds, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let judging = Judging {
            work: base,
            target: base,
            scratch: base,
            root: base,
            mutants: &mutants,
            reach: &listed_reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: base,
            red: &Red::new(),
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let classic = BTreeSet::from([0]);
        assert_eq!(
            handed_cases(&judging, true, &classic, (&schema, &reach)),
            Some(BTreeSet::from([body])),
            "the case that ran the hand-back's function"
        );
        assert_eq!(
            handed_cases(&judging, false, &classic, (&schema, &reach)),
            Some(BTreeSet::new()),
            "a hand-back judged elsewhere asks nothing of this control"
        );
    }

    #[test]
    fn a_handed_back_mutant_is_judged_by_the_cases_that_can_observe_it() {
        assert_eq!(function_ident("Foo::bar").as_deref(), Some("bar"));
        assert_eq!(
            function_ident("<impl Display for Foo>::fmt").as_deref(),
            Some("fmt")
        );
        assert_eq!(function_ident("two").as_deref(), Some("two"));
        let mentions: std::collections::BTreeMap<String, BTreeSet<String>> = [
            (
                String::from("CHAIN"),
                BTreeSet::from([String::from("seed")]),
            ),
            (String::from("OTHER"), BTreeSet::from([String::from("u8")])),
        ]
        .into();
        assert_eq!(
            mentioners("seed", &mentions),
            BTreeSet::from([String::from("seed"), String::from("CHAIN")])
        );
        let schema = Schema {
            probes: vec![
                String::from("f-uses-chain"),
                String::from("f-plain"),
                String::from("f-body"),
            ],
            names: vec![
                BTreeSet::from([String::from("CHAIN")]),
                BTreeSet::from([String::from("u8")]),
                BTreeSet::new(),
            ],
            mutant_fns: [(2, String::from("f-body"))].into(),
            mentions,
            probed: [String::from("src/lib.rs")].into(),
            ..Schema::default()
        };
        let (chain, plain, body) = (case("chain"), case("plain"), case("body"));
        let reach = Reach {
            executed: [
                (chain.clone(), BTreeSet::from([0])),
                (plain.clone(), BTreeSet::from([1])),
                (body.clone(), BTreeSet::from([2])),
            ]
            .into(),
            ..Reach::default()
        };
        let nowhere = std::path::Path::new("/nonexistent-batten-handback-root");
        let named = |function: Option<&str>| {
            let mut mutant = listed("FnValue", "0", (1, 1), (1, 2));
            mutant.function = function.map(|name| Function {
                function_name: name.to_owned(),
                return_type: String::new(),
                span: Some(mutant.span),
            });
            mutant
        };
        assert_eq!(
            handback_cases(nowhere, 0, &named(Some("seed")), &schema, &reach),
            Some(BTreeSet::from([chain.clone()])),
            "the case naming CHAIN observes seed"
        );
        assert_eq!(
            handback_cases(nowhere, 2, &named(None), &schema, &reach),
            Some(BTreeSet::from([body])),
            "the case that ran its enclosing function"
        );
        assert_eq!(
            handback_cases(nowhere, 1, &named(None), &schema, &reach),
            None,
            "nothing to go on"
        );
        // CLOUD-2911: in a file built without probes, a case calling the
        // function directly is in no record, so every case judges it.
        let mut blind = named(Some("seed"));
        blind.file = String::from("src/unprobed.rs");
        assert_eq!(
            handback_cases(nowhere, 0, &blind, &schema, &reach),
            None,
            "an unprobed file's hand-back is judged by every case"
        );
    }

    /// Fails by: a `#[test]` that calls the mutant's function directly left
    /// out of its hand-back's cases. A test function carries no probe, so
    /// only its own text says it observes the function (CLOUD-2789); a test
    /// naming only a longer identifier sharing the prefix does not.
    #[test]
    fn a_test_naming_the_function_observes_its_hand_back() {
        let root = crate::scratch::scratch("schema-handback-direct");
        std::fs::create_dir_all(root.join("src")).expect("the source dir");
        std::fs::write(
            root.join("src/lib.rs"),
            "fn seed() {}\n#[cfg(test)]\nmod tests {\n    #[test]\n    fn direct() { super::seed(); }\n    #[test]\n    fn aside() { let seedling = 1; }\n}\n",
        )
        .expect("the source");
        let schema = Schema {
            probes: vec![String::from("f-other")],
            names: vec![BTreeSet::new()],
            probed: [String::from("src/lib.rs")].into(),
            ..Schema::default()
        };
        let (other, direct, aside) = (
            case("other"),
            (String::from("tests::direct"), String::from("lib")),
            (String::from("tests::aside"), String::from("lib")),
        );
        let reach = Reach {
            executed: [
                (other, BTreeSet::from([0])),
                (direct.clone(), BTreeSet::new()),
                (aside, BTreeSet::new()),
            ]
            .into(),
            ..Reach::default()
        };
        let mut mutant = listed("FnValue", "0", (1, 1), (1, 2));
        mutant.function = Some(Function {
            function_name: String::from("seed"),
            return_type: String::new(),
            span: Some(mutant.span),
        });
        assert_eq!(
            handback_cases(&root, 0, &mutant, &schema, &reach),
            Some(BTreeSet::from([direct])),
        );
    }

    /// A shared test module keys a case on what the case reaches by name, and
    /// on nothing else of the file.
    ///
    /// Fails by: the whole file keyed (an unreached helper's edit moves the
    /// digest), a reached helper dropped, a helper reached only through
    /// another missed, or a reached type's `impl` left out.
    #[test]
    fn a_case_is_keyed_on_the_shared_helpers_it_reaches() {
        let test = [String::from("fn t() { let r = repo(); r.run(); }")];
        let common = |helper: &str, other: &str, method: &str| {
            format!(
                "use std::path::Path;\npub fn repo() -> Repo {{ Repo(scratch()) }}\n\
                 fn scratch() -> u8 {{ {helper} }}\npub struct Repo(u8);\n\
                 impl Repo {{ pub fn run(&self) {{ {method} }} }}\n\
                 pub fn other() -> u8 {{ {other} }}\n"
            )
        };
        let base = common_reached(&common("1", "1", "()"), &test);
        assert_eq!(
            base,
            common_reached(&common("1", "2", "()"), &test),
            "an unreached helper does not move the key"
        );
        assert_ne!(
            base,
            common_reached(&common("2", "1", "()"), &test),
            "a helper reached through another moves it"
        );
        assert_ne!(
            base,
            common_reached(&common("1", "1", "let _ = 0;"), &test),
            "a reached type's method moves it"
        );
        // A helper reached only through an item AFTER it in the file, so the
        // first pass skips it and only a second takes it.
        let ordered = |body: &str| format!("fn a() -> u8 {{ {body} }}\nfn b() -> u8 {{ a() }}\n");
        let through = [String::from("fn t() { b(); }")];
        assert_ne!(
            common_reached(&ordered("1"), &through),
            common_reached(&ordered("2"), &through),
            "a helper reached on a later pass moves it"
        );
    }

    /// The reach is a closure, so a helper declared ABOVE the item that names
    /// it is taken on a later pass, not missed by the one pass that found it.
    ///
    /// Fails by: the walk stopping after the first pass that took anything.
    #[test]
    fn a_helper_declared_before_its_caller_is_reached() {
        let test = [String::from("fn t() { repo(); }")];
        let common = |helper: &str| {
            format!(
                "fn scratch() -> u8 {{ {helper} }}
pub fn repo() -> u8 {{ scratch() }}
"
            )
        };
        assert_ne!(
            common_reached(&common("1"), &test),
            common_reached(&common("2"), &test),
            "a helper reached through a later item moves the key"
        );
    }

    /// A handed-back verdict is read from the outcome file that names the
    /// mutant, never the run's exit; unviable wins; a survivor no case observed
    /// is uncovered; a mutant no file names is an error, never a kill.
    ///
    /// Fails by: an `--re` that matched nothing read as a kill (exit 0 with no
    /// outcome line), an unviable mutant read as caught, an unobserved survivor
    /// read as missed, or — lap 27's measured case — a target `caught.txt`
    /// names read as missed because an extra field mutant in the same run
    /// survived and the run exited 2.
    #[test]
    fn a_handed_back_verdict_is_read_from_the_outcome_files() {
        use super::super::Outcome::{Failed, Passed, TimedOut};
        let output = crate::scratch::scratch("schema-handback-verdict");
        let outcomes = output.join("mutants.out");
        std::fs::create_dir_all(&outcomes).unwrap();
        std::fs::write(outcomes.join("caught.txt"), "src/lib.rs:2:7: kill\n").unwrap();
        std::fs::write(outcomes.join("unviable.txt"), "src/lib.rs:9:1: dead\n").unwrap();
        std::fs::write(outcomes.join("missed.txt"), "src/lib.rs:4:1: live\n").unwrap();
        std::fs::write(outcomes.join("timeout.txt"), "src/lib.rs:6:1: slow\n").unwrap();
        let verdict =
            |outcome, name, unobserved| handback_verdict(outcome, &output, name, unobserved);
        assert_eq!(verdict(Passed, "src/lib.rs:2:7: kill", false), "caught");
        assert_eq!(
            verdict(Failed(Some(2)), "src/lib.rs:2:7: kill", false),
            "caught",
            "a caught target beside a missed extra"
        );
        assert_eq!(verdict(Passed, "src/lib.rs:5:1: absent", false), "error");
        assert_eq!(
            verdict(Failed(Some(2)), "src/lib.rs:5:1: absent", false),
            "error"
        );
        assert_eq!(
            verdict(TimedOut, "src/lib.rs:5:1: absent", false),
            "timeout"
        );
        assert_eq!(verdict(Passed, "src/lib.rs:9:1: dead", false), "unviable");
        assert_eq!(
            verdict(Failed(Some(2)), "src/lib.rs:4:1: live", false),
            "missed"
        );
        assert_eq!(
            verdict(Failed(Some(2)), "src/lib.rs:4:1: live", true),
            "uncovered"
        );
        assert_eq!(
            verdict(Failed(Some(3)), "src/lib.rs:6:1: slow", false),
            "timeout"
        );
    }

    /// A run selects its cases' own packages; a case whose binary went
    /// unrecorded, or none recorded at all, falls back to the mutant's package.
    ///
    /// Fails by: an unrecorded binary's empty package kept as `-p ""`, or the
    /// fallback taken only when every binary went unrecorded.
    #[test]
    fn a_run_selects_its_cases_packages_or_the_mutants_when_one_is_unrecorded() {
        let mut mutant = listed("BinaryOperator", "!=", (2, 7), (2, 9));
        mutant.package = String::from("other");
        let packages = |cases: &[(&str, &str)]| {
            let cases: BTreeSet<Case> = cases
                .iter()
                .map(|(name, binary)| ((*name).to_owned(), (*binary).to_owned()))
                .collect();
            let args = nextest_args(&mutant, &cases);
            args.windows(2)
                .filter(|pair| pair[0] == "-p")
                .map(|pair| pair[1].clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(packages(&[("t", "batten")]), ["batten"]);
        assert_eq!(packages(&[("t", "batten"), ("u", "")]), ["other"]);
        assert_eq!(packages(&[("u", "")]), ["other"]);
    }

    /// The binary ids a nextest `binaries-only` document lists, and none from
    /// a document that is not one.
    ///
    /// Fails by: a binary read off anything but `rust-binaries`' keys, or a
    /// malformed document read as listing nothing rather than unreadable.
    #[test]
    fn the_recorded_binaries_are_the_documents_rust_binaries() {
        let document = r#"{"rust-build-meta":{},"rust-binaries":{"batten":{"binary-id":"batten"},"batten::cli":{"binary-id":"batten::cli"}}}"#;
        assert_eq!(
            reuse_ids(document),
            Some(BTreeSet::from([
                String::from("batten"),
                String::from("batten::cli")
            ]))
        );
        assert_eq!(reuse_ids("not json"), None);
        assert_eq!(reuse_ids("{}"), None, "no `rust-binaries` is no record");
    }

    /// The originals are shown to the judging only where every run of it
    /// reuses the build: a case of a binary the reuse record does not hold
    /// would be built, from the originals, with no switch in it.
    ///
    /// Fails by: originals shown while a run builds, so every mutant that run
    /// judges survives (165 survived against 18 caught on a #1276 shard).
    #[test]
    fn originals_are_shown_only_where_no_judging_run_builds() {
        let reuse = Reuse {
            binaries: std::path::PathBuf::from("/r/binaries.json"),
            metadata: std::path::PathBuf::from("/r/cargo-metadata.json"),
            ids: BTreeSet::from([String::from("batten")]),
        };
        let case = |name: &str, binary: &str| (name.to_owned(), binary.to_owned());
        let reach = std::collections::BTreeMap::from([
            (0, BTreeSet::from([case("a", "batten")])),
            (1, BTreeSet::from([case("b", "batten::it")])),
        ]);
        assert!(reuse_holds_all(&reuse, &[0], &reach), "every case held");
        assert!(
            !reuse_holds_all(&reuse, &[0, 1], &reach),
            "one case in a binary it does not hold"
        );
        assert!(reuse_holds_all(&reuse, &[], &reach), "nothing judged");
    }

    /// Where every judging run reuses the build, the judging sees each
    /// rendered file's original text until the showing drops; where none is
    /// recorded, the rendering stands.
    ///
    /// Fails by: the originals never shown (bootstrap shard 7/8 at 34c6e4d1f
    /// survived `shown_over` as `Ok(None)`), so a case reading its crate's
    /// source reads the schema's switches and fails under every mutant.
    #[test]
    fn the_judging_sees_the_originals_while_it_reuses_the_build() {
        let base = crate::scratch::scratch("schema-shown-over");
        let (root, work) = (base.join("root"), base.join("work"));
        let file = "crates/p/src/m.rs";
        for (dir, text) in [(&root, "original"), (&work, "rendered")] {
            std::fs::create_dir_all(dir.join("crates/p/src")).unwrap();
            std::fs::write(dir.join(file), text).unwrap();
        }
        let mutants = [Listed {
            file: file.to_owned(),
            ..listed("BinaryOperator", "!=", (2, 7), (2, 9))
        }];
        let reach = std::collections::BTreeMap::from([(0, BTreeSet::from([case("a::f")]))]);
        let reuse = Reuse {
            binaries: std::path::PathBuf::from("/r/binaries.json"),
            metadata: std::path::PathBuf::from("/r/cargo-metadata.json"),
            ids: BTreeSet::from([case("a::f").1]),
        };
        let (seconds, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let (red, control) = (Red::new(), Control::new());
        let judging = |reuse| Judging {
            work: &work,
            target: &base,
            scratch: &base,
            root: &root,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &base,
            red: &red,
            control: &control,
            reuse,
            threads: None,
        };
        let schema = Schema {
            files: [(file.to_owned(), Rendered::default())].into(),
            ..Schema::default()
        };
        let contents = || std::fs::read_to_string(work.join(file)).unwrap();
        let shown = shown_over(&judging(Some(&reuse)), &[0], &schema).unwrap();
        assert!(shown.is_some(), "every run reuses the build");
        assert_eq!(contents(), "original");
        drop(shown);
        assert_eq!(contents(), "rendered", "the rendering goes back");
        assert!(
            shown_over(&judging(None), &[0], &schema).unwrap().is_none(),
            "no reuse record, no showing"
        );
        assert_eq!(contents(), "rendered");
    }

    /// The control run names each case it found red beside the count, by
    /// label and its failure's first line.
    ///
    /// A control report over `cases`, each passed or failed with `failure`
    /// (`<type>|<message>`), as nextest writes one.
    fn control_report(cases: &[(&str, Option<&str>)]) -> String {
        let mut xml = String::from("<testsuites><testsuite name=\"batten::it\">");
        for (name, failure) in cases {
            let _ = write!(
                xml,
                "<testcase name=\"{name}\" classname=\"batten::it\" time=\"0.1\">"
            );
            if let Some((kind, message)) = failure.and_then(|failure| failure.split_once('|')) {
                let _ = write!(xml, "<failure type=\"{kind}\" message=\"{message}\"/>");
            }
            xml.push_str("</testcase>");
        }
        xml.push_str("</testsuite></testsuites>");
        xml
    }

    fn control_ran(outcome: super::super::Outcome) -> super::super::Ran {
        super::super::Ran {
            outcome,
            output: String::new(),
            stdout: String::new(),
        }
    }

    const BOUND_ABORT: &str = "test abort|process aborted with signal 15 (SIGTERM)";

    /// One control batch over `batch`, each of its runs answered in turn by
    /// `runs`, and every (cases, fail-fast) it was asked to run.
    fn control_over(
        batch: &[&str],
        runs: Vec<(super::super::Outcome, String)>,
    ) -> (Red, Vec<(BTreeSet<Case>, bool)>) {
        let batch: BTreeSet<Case> = batch.iter().map(|name| case(name)).collect();
        let mut runs = runs.into_iter();
        let mut asked = Vec::new();
        let (red, _) = control_batch(&batch, &mut |open, fail_fast| {
            asked.push((open.clone(), fail_fast));
            let (outcome, xml) = runs.next().expect("no run past the ones scripted");
            (Ok(control_ran(outcome)), Some(xml))
        })
        .unwrap();
        (red, asked)
    }

    /// Each control batch is kept as it ends: a run that fails in a later
    /// batch, as a kill does, leaves every batch before it kept.
    ///
    /// Fails by: the batches' seconds kept once, after the last batch, so a
    /// shard restarted mid-control relaunched to "control ran 10213 of the
    /// 10213 case(s), 0 journaled".
    #[test]
    fn each_control_batch_is_kept_as_it_ends() {
        let batches: Vec<BTreeSet<Case>> = vec![[case("a")].into(), [case("b")].into()];
        let mut asked = 0;
        let mut kept: Vec<Vec<Case>> = Vec::new();
        let ended = control_batches(
            batches,
            &mut |_, _| {
                asked += 1;
                if asked == 1 {
                    (
                        Ok(control_ran(super::super::Outcome::Passed)),
                        Some(control_report(&[("a", None)])),
                    )
                } else {
                    (Err(anyhow::anyhow!("killed in flight")), None)
                }
            },
            &mut |times| {
                kept.push(times.keys().cloned().collect());
                Ok(())
            },
        );
        assert!(ended.is_err(), "the second batch's run failed");
        assert_eq!(kept, vec![vec![case("a")]], "the first batch was kept");
    }

    /// THE CONTROL'S BOUND IS NEVER A CASE'S VERDICT (CLOUD-2936): a case the
    /// bound's signal ended runs again without fail-fast, and its own pass is
    /// its verdict.
    ///
    /// Fails by: a `test abort` from the bound's `SIGTERM` filed control red,
    /// which reported a 0.03 s pure case red on one control and green on the
    /// next over identical code.
    #[test]
    fn a_case_the_control_bound_ended_runs_again_and_is_not_red() {
        let (red, asked) = control_over(
            &["fast", "pure"],
            vec![
                (
                    super::super::Outcome::TimedOut,
                    control_report(&[("fast", None), ("pure", Some(BOUND_ABORT))]),
                ),
                (
                    super::super::Outcome::Passed,
                    control_report(&[("pure", None)]),
                ),
            ],
        );
        assert!(red.is_empty(), "{red:?}");
        assert_eq!(
            asked,
            vec![
                ([case("fast"), case("pure")].into(), true),
                ([case("pure")].into(), false),
            ]
        );
    }

    /// Fails by: a case the bound ended twice treated as green, or a third
    /// run: two bounds is the most a control batch costs.
    #[test]
    fn a_case_the_control_bound_ends_twice_is_red() {
        let (red, asked) = control_over(
            &["slow"],
            vec![
                (
                    super::super::Outcome::TimedOut,
                    control_report(&[("slow", Some(BOUND_ABORT))]),
                ),
                (
                    super::super::Outcome::TimedOut,
                    control_report(&[("slow", Some(BOUND_ABORT))]),
                ),
            ],
        );
        assert!(red.contains_key(&case("slow")), "{red:?}");
        assert_eq!(asked.len(), 2);
    }

    /// ONLY THE BOUND'S SIGNAL, ONLY WHEN THE BOUND FIRED: a panic in a run
    /// its bound ended, a crash by another signal, and a `SIGTERM` abort in a
    /// run that ended on its own are each the case's own red, run once.
    ///
    /// Fails by: any red the bound did not cause given a second run.
    #[test]
    fn a_red_the_bound_did_not_cause_is_red_on_the_first_run() {
        let (red, asked) = control_over(
            &["panics", "crashes"],
            vec![(
                super::super::Outcome::TimedOut,
                control_report(&[
                    ("panics", Some("test failure|thread panicked")),
                    (
                        "crashes",
                        Some("test abort|process aborted with signal 11 (SIGSEGV)"),
                    ),
                ]),
            )],
        );
        assert_eq!(red.len(), 2, "{red:?}");
        assert_eq!(asked.len(), 1);
        let (red, asked) = control_over(
            &["own"],
            vec![(
                super::super::Outcome::Failed(Some(100)),
                control_report(&[("own", Some(BOUND_ABORT))]),
            )],
        );
        assert!(red.contains_key(&case("own")), "{red:?}");
        assert_eq!(asked.len(), 1);
    }

    /// Fails by: a bare count ("1 case(s) red under the judge") naming no
    /// case, or a failure's whole text printed (rule 4).
    #[test]
    fn the_control_names_each_red_case() {
        let red: Red = [
            (
                (String::from("tests::one"), String::from("fix")),
                String::from("left != right\nat crates/fix/src/lib.rs:3"),
            ),
            (
                (String::from("two"), String::from("fix::it")),
                String::from("timed out"),
            ),
        ]
        .into();
        assert_eq!(
            control_red_lines(&red),
            "mutate schema: control run found 2 case(s) red under the judge\n\
             control-red\tfix tests::one\tleft != right\n\
             control-red\tfix::it two\ttimed out\n"
        );
        assert_eq!(
            control_red_lines(&Red::new()),
            "mutate schema: control run found 0 case(s) red under the judge\n"
        );
    }

    /// A judging run reuses the binaries the build recorded when every case's
    /// binary is among them, narrowing by binary in the filterset since nextest
    /// refuses cargo's selection flags beside `--binaries-metadata`; otherwise
    /// it builds as before.
    ///
    /// Fails by: a reused run carrying a flag nextest refuses beside it (every
    /// run an error), a reused run selecting no binary (every case filtered
    /// out, every mutant missed), or a case outside the record run on reused
    /// binaries that do not hold it (no case selected, a vacuous pass).
    #[test]
    fn a_judging_run_reuses_the_build_only_when_it_holds_every_case() {
        let mutant = listed("BinaryOperator", "!=", (2, 7), (2, 9));
        let reuse = Reuse {
            binaries: std::path::PathBuf::from("/r/binaries.json"),
            metadata: std::path::PathBuf::from("/r/cargo-metadata.json"),
            ids: BTreeSet::from([String::from("batten"), String::from("batten::cli")]),
        };
        let cases = |list: &[(&str, &str)]| -> BTreeSet<Case> {
            list.iter()
                .map(|(name, binary)| ((*name).to_owned(), (*binary).to_owned()))
                .collect()
        };
        let target = std::path::Path::new("/t");
        let held = judge_args(
            &mutant,
            &cases(&[("t", "batten::cli")]),
            target,
            Some(&reuse),
        );
        for refused in ["-p", "--cargo-profile", "--target-dir", "--test", "--lib"] {
            assert!(
                !held.iter().any(|arg| arg == refused),
                "{refused} in {held:?}"
            );
        }
        let filter = held.windows(2).find(|pair| pair[0] == "-E").unwrap()[1].clone();
        assert_eq!(filter, "(binary_id(=batten::cli) & test(=t))");
        assert!(
            held.windows(2)
                .any(|pair| pair[0] == "--binaries-metadata" && pair[1] == "/r/binaries.json")
        );
        assert!(
            held.windows(2)
                .any(|pair| pair[0] == "--cargo-metadata" && pair[1] == "/r/cargo-metadata.json")
        );
        for outside in [&[("t", "other::x")][..], &[("t", "batten"), ("u", "")][..]] {
            let built = judge_args(&mutant, &cases(outside), target, Some(&reuse));
            assert!(
                !built.iter().any(|arg| arg == "--binaries-metadata"),
                "{built:?}"
            );
            assert!(built.iter().any(|arg| arg == "--target-dir"), "{built:?}");
        }
        let unrecorded = judge_args(&mutant, &cases(&[("t", "batten")]), target, None);
        assert!(!unrecorded.iter().any(|arg| arg == "--binaries-metadata"));
    }

    /// An error ending exactly where a probe region ends is outside it.
    ///
    /// Fails by: a region read as closed at its end, which unprobes a file
    /// for an error that is not the probe's.
    #[test]
    fn an_error_at_a_probe_regions_end_does_not_unprobe_its_file() {
        let source = "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n";
        let rendered = render(
            source,
            &[(0, &listed("BinaryOperator", "!=", (2, 7), (2, 9)))],
            &BTreeSet::new(),
            Some(0),
        );
        let at = rendered.probe_regions[0].end;
        let schema = Schema {
            files: [(String::from("src/m.rs"), rendered)].into(),
            ..Schema::default()
        };
        let message = format!(
            "{{\"reason\":\"compiler-message\",\"message\":{{\"level\":\"error\",\"message\":\"e\",\
             \"spans\":[{{\"is_primary\":true,\"file_name\":\"src/m.rs\",\"byte_start\":{at}}}]}}}}"
        );
        assert!(unviable(&schema, &message).unprobe.is_empty());
    }

    /// A `const fn` inside a `const fn` drops its own `const`, not its
    /// container's.
    ///
    /// Fails by: an enclosing function's `const` taken for the innermost one.
    #[test]
    fn a_nested_const_fn_drops_its_own_const() {
        let source = "const fn g() -> u8 {\n    const fn f(a: u8) -> bool {\n        a == 1\n    }\n    1\n}\n";
        let rendered = render_all(source, &[listed("BinaryOperator", "!=", (3, 11), (3, 13))]);
        assert!(
            rendered.text.starts_with("const fn g()"),
            "{}",
            rendered.text
        );
        assert!(
            rendered.text.contains("\n    fn f(a: u8)"),
            "{}",
            rendered.text
        );
    }

    /// Only a seal over this very tree skips the reach run.
    ///
    /// Fails by: a seal over another tree honoured.
    #[test]
    fn only_a_seal_over_this_tree_skips_reach() {
        let base = crate::scratch::scratch("schema-reach-sealed");
        assert!(!sealed_over(&base, "t1"), "no seal yet");
        std::fs::write(base.join(SEALED), "t1").unwrap();
        assert!(sealed_over(&base, "t1"));
        assert!(!sealed_over(&base, "t2"), "a seal over another tree");
    }

    /// The resource digest moves with a non-Rust file a run may read, and not
    /// with a Rust source, which the probes already key.
    ///
    /// Fails by: a constant digest, which reuses a verdict over a changed
    /// fixture.
    #[test]
    fn the_resource_digest_moves_with_a_fixture_and_not_a_source() {
        let base = crate::scratch::scratch("schema-resource-digest");
        crate::gitwrite::init_on_main(&base).unwrap();
        std::fs::write(base.join("notes.md"), "one\n").unwrap();
        std::fs::write(base.join("lib.rs"), "fn f() {}\n").unwrap();
        let paths = [String::from("notes.md"), String::from("lib.rs")];
        crate::gitwrite::commit_paths(&base, &paths, "base").unwrap();
        let held = resource_digest(&base).unwrap();
        std::fs::write(base.join("notes.md"), "two\n").unwrap();
        let moved = resource_digest(&base).unwrap();
        assert_ne!(moved, held, "a fixture changed");
        std::fs::write(base.join("lib.rs"), "fn g() {}\n").unwrap();
        assert_eq!(
            resource_digest(&base).unwrap(),
            moved,
            "a source is the probes'"
        );
    }

    /// The files a reused run needs from the build: every test binary the
    /// nextest document lists and every binary a case launches through
    /// `CARGO_BIN_EXE_*`, each relative to the target it lives in; none when
    /// one lies outside that target, which a pack could not put back.
    ///
    /// Fails by: a launched binary left out (a case spawns a path that is not
    /// there and fails, read as a kill), a test binary left out (its cases
    /// select nothing and pass vacuously), or a path outside the target packed
    /// where a restore would write it somewhere else.
    #[test]
    fn the_packed_binaries_are_the_tests_and_what_they_launch() {
        let document = r#"{"rust-build-meta":{"target-directory":"/t","non-test-binaries":{"batten":[{"name":"batten","kind":"bin","path":"debug/batten"}]}},"rust-binaries":{"batten":{"binary-path":"/t/debug/deps/batten-1"},"batten::it":{"binary-path":"/t/debug/deps/it-2"}}}"#;
        let (target, files) = packed_paths(document).unwrap();
        assert_eq!(target, std::path::PathBuf::from("/t"));
        assert_eq!(
            files,
            ["debug/batten", "debug/deps/batten-1", "debug/deps/it-2"]
                .map(std::path::PathBuf::from)
        );
        let outside = r#"{"rust-build-meta":{"target-directory":"/t"},"rust-binaries":{"x":{"binary-path":"/elsewhere/x-1"}}}"#;
        assert_eq!(packed_paths(outside), None);
        assert_eq!(packed_paths("not json"), None);
    }

    /// A packed build is put back and reused only over the rendered tree it
    /// was built from; over any other tree nothing is restored and the run
    /// records afresh.
    ///
    /// Fails by: binaries of another rendering trusted (every mutant judged
    /// against switches the tree no longer has), or a matching pack not put
    /// back (every shard rebuilds, which the reach job exists to spare).
    #[test]
    fn a_packed_build_is_restored_only_over_the_tree_it_was_built_from() {
        let state = crate::scratch::scratch("schema-reuse-pack");
        let target = state.join("tree").join("target");
        std::fs::create_dir_all(target.join("debug").join("deps")).unwrap();
        std::fs::write(target.join("debug/deps/batten-1"), "test binary").unwrap();
        std::fs::write(target.join("debug/batten"), "launched").unwrap();
        let document = format!(
            r#"{{"rust-build-meta":{{"target-directory":"{}","non-test-binaries":{{"batten":[{{"name":"batten","kind":"bin","path":"debug/batten"}}]}}}},"rust-binaries":{{"batten":{{"binary-path":"{}"}}}}}}"#,
            target.display(),
            target.join("debug/deps/batten-1").display()
        );
        let dir = state.join("reuse");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("binaries.json"), &document).unwrap();
        std::fs::write(dir.join("cargo-metadata.json"), "{}").unwrap();
        pack(
            &state,
            &document,
            (
                "tree-1",
                &Known::default(),
                &std::collections::BTreeMap::new(),
            ),
        )
        .unwrap();
        std::fs::remove_dir_all(&target).unwrap();
        assert!(restore(&state, "tree-2").is_none(), "another rendering");
        assert!(!target.join("debug/batten").exists(), "nothing put back");
        let reuse = restore(&state, "tree-1").expect("its own rendering");
        assert_eq!(reuse.ids, BTreeSet::from([String::from("batten")]));
        assert_eq!(
            std::fs::read_to_string(target.join("debug/deps/batten-1")).unwrap(),
            "test binary"
        );
        assert_eq!(
            std::fs::read_to_string(target.join("debug/batten")).unwrap(),
            "launched"
        );
    }

    /// A rendered tree the recorded build was made from is taken as built,
    /// with no cargo run; any other tree, or no record, is built as always.
    ///
    /// Fails by: a build skipped over a rendering that differs (binaries of
    /// another switch set judged), or a matching one built again (every shard
    /// pays the build the reach job paid).
    #[test]
    fn a_rendered_tree_the_reach_job_built_is_not_built_again() {
        let root = crate::scratch::scratch("schema-prebuilt-root");
        let work = crate::scratch::scratch("schema-prebuilt-work");
        let state = crate::scratch::scratch("schema-prebuilt-state");
        let known = Known::default();
        assert!(
            prebuilt(&root, &work, &state, &[], &known)
                .unwrap()
                .is_none(),
            "no record"
        );
        write_schema(&root, &work, &[], &BTreeSet::new(), &BTreeSet::new()).unwrap();
        let rendered = tree_digest(&work).unwrap();
        std::fs::create_dir_all(state.join("reuse")).unwrap();
        std::fs::write(state.join("reuse").join(PACKED_TREE), "another").unwrap();
        assert!(
            prebuilt(&root, &work, &state, &[], &known)
                .unwrap()
                .is_none(),
            "another rendering"
        );
        std::fs::write(state.join("reuse").join(PACKED_TREE), &rendered).unwrap();
        assert!(
            prebuilt(&root, &work, &state, &[], &known)
                .unwrap()
                .is_none(),
            "no record of what its build scripts wrote"
        );
        std::fs::write(state.join("reuse").join(PACKED_BUILT), "{}").unwrap();
        let built = prebuilt(&root, &work, &state, &[], &known)
            .unwrap()
            .expect("its own rendering");
        assert!(built.unviable.is_empty() && built.handed.is_empty());
    }

    /// A pack the reach job made over a listing with unviable and handed-back
    /// mutants is taken by a shard that restored it with no verdict journal,
    /// as under CI (CLOUD-2850): the sets it was rendered with are packed
    /// beside it, so the shard renders the very tree the binaries came from.
    ///
    /// Fails by: the shard rendering with every mutant switched (no journal
    /// tells it which were refused), missing the pack, and rebuilding cold
    /// (CLOUD-2789: 2,177 unviable on #1276, 12 rounds that never finished);
    /// or the packed sets dropped from what the build reports.
    #[test]
    fn a_pack_over_refused_mutants_is_taken_with_no_journal() {
        let root = crate::scratch::scratch("schema-packed-known-root");
        let work = crate::scratch::scratch("schema-packed-known-work");
        let state = crate::scratch::scratch("schema-packed-known-state");
        for dir in [&root, &work] {
            std::fs::create_dir_all(dir.join("crates/x/src")).unwrap();
            std::fs::write(dir.join("crates/x/src/lib.rs"), "pub mod m;\n").unwrap();
            std::fs::write(
                dir.join("crates/x/src/m.rs"),
                "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n",
            )
            .unwrap();
        }
        let mutants: Vec<Listed> = ["!=", ">", "<"]
            .map(|replacement| {
                let mut mutant = listed("BinaryOperator", replacement, (2, 7), (2, 9));
                mutant.file = String::from("crates/x/src/m.rs");
                mutant
            })
            .to_vec();
        let rendered_with = Known {
            unviable: BTreeSet::from([0]),
            handed: BTreeSet::from([1]),
            unprobed: BTreeSet::new(),
        };
        let skip = BTreeSet::from([0, 1]);
        write_schema(&root, &work, &mutants, &skip, &rendered_with.unprobed).unwrap();
        let rendered = tree_digest(&work).unwrap();
        let target = state.join("target");
        std::fs::create_dir_all(target.join("debug/deps")).unwrap();
        std::fs::write(target.join("debug/deps/x-1"), "test binary").unwrap();
        let document = format!(
            r#"{{"rust-build-meta":{{"target-directory":"{}"}},"rust-binaries":{{"x":{{"binary-path":"{}"}}}}}}"#,
            target.display(),
            target.join("debug/deps/x-1").display()
        );
        pack(
            &state,
            &document,
            (
                &rendered,
                &rendered_with,
                &std::collections::BTreeMap::new(),
            ),
        )
        .unwrap();
        assert!(!state.join("verdicts").exists(), "no journal");
        // WHAT A CI SHARD KNOWS: nothing, since it reads no journal.
        let known = Known::default();
        let built = prebuilt(&root, &work, &state, &mutants, &known)
            .unwrap()
            .expect("the pack's own rendering");
        assert_eq!(built.unviable, rendered_with.unviable);
        assert_eq!(built.handed, rendered_with.handed);
        assert_eq!(tree_digest(&work).unwrap(), rendered);
    }

    /// A run that restored the packed build keys what its build scripts wrote
    /// as packed, with no `OUT_DIR` on its own disk; and one that can name it
    /// nowhere refuses, never keying it on the whole tree.
    ///
    /// Fails by: the output read off this disk alone, so a fresh container
    /// keyed every case including it on the whole tree and carried 0 of its
    /// imported reach records (CLOUD-2904); or a missing output widened.
    #[test]
    fn a_restored_build_keys_its_outputs_as_packed_or_refuses() {
        let work = crate::scratch::scratch("schema-built-work");
        let state = crate::scratch::scratch("schema-built-state");
        let target = state.join("target");
        std::fs::create_dir_all(&target).unwrap();
        std::fs::write(work.join("lib.rs"), "pub fn f() {}\n").unwrap();
        let built = format!("{BUILT}crates/x");
        let mut schema = Schema::default();
        schema
            .compiled
            .item_includes
            .insert(String::from("TABLE"), BTreeSet::from([built.clone()]));
        let dir = state.join("reuse");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(PACKED_TREE), tree_digest(&work).unwrap()).unwrap();
        std::fs::write(
            dir.join(PACKED_BUILT),
            serde_json::to_string(&std::collections::BTreeMap::from([(
                built.clone(),
                String::from("out-1"),
            )]))
            .unwrap(),
        )
        .unwrap();
        let outputs = build_outputs((&work, &target, &state), &[], &schema).unwrap();
        assert_eq!(outputs.get(&built).map(String::as_str), Some("out-1"));
        std::fs::remove_file(dir.join(PACKED_BUILT)).unwrap();
        let refused = build_outputs((&work, &target, &state), &[], &schema).unwrap_err();
        assert!(
            refused.to_string().contains("no build output for crates/x"),
            "{refused:#}"
        );
    }

    /// A restored pack is the clean build to every case, whatever wrote the
    /// target since it was packed: a build writing a binary in place (a
    /// hand-back judged in place compiles its mutant into the schema build's
    /// target) changes neither the pack nor what a restore puts back.
    ///
    /// Fails by: the pack hard-linked to the target, so the in-place build
    /// rewrote it too, or a restore that keeps a file already there (the null
    /// re-run at 639b0bbb5 judged with a `units.rs` field deleted, and its
    /// control found `shape_names_docs_and_pointers_are_read` red).
    #[test]
    fn a_restored_pack_is_the_clean_build_whatever_wrote_the_target_since() {
        let work = crate::scratch::scratch("schema-pack-work");
        let state = crate::scratch::scratch("schema-pack-state");
        std::fs::write(work.join("lib.rs"), "pub fn f() {}\n").unwrap();
        let target = state.join("target");
        let binary = target.join("debug/deps/x-1");
        std::fs::create_dir_all(binary.parent().unwrap()).unwrap();
        std::fs::write(&binary, "the clean build").unwrap();
        let document = format!(
            r#"{{"rust-build-meta":{{"target-directory":"{}"}},"rust-binaries":{{"x":{{"binary-path":"{}"}}}}}}"#,
            target.display(),
            binary.display()
        );
        let dir = state.join("reuse");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("binaries.json"), &document).unwrap();
        std::fs::write(dir.join("cargo-metadata.json"), "{}").unwrap();
        let tree = tree_digest(&work).unwrap();
        pack(
            &state,
            &document,
            (&tree, &Known::default(), &std::collections::BTreeMap::new()),
        )
        .unwrap();
        // IN PLACE, as a build writes its output: the same file, truncated.
        std::fs::write(&binary, "a hand-back's mutant").unwrap();
        assert_eq!(
            std::fs::read_to_string(dir.join(PACKED).join("debug/deps/x-1")).unwrap(),
            "the clean build",
            "the pack keeps what was packed"
        );
        restore(&state, &tree).expect("the pack over this rendering");
        assert_eq!(
            std::fs::read_to_string(&binary).unwrap(),
            "the clean build",
            "a restore puts the clean build back"
        );
    }

    /// A judging run reuses a pack over its own rendering without asking cargo
    /// to record it again, and says so.
    ///
    /// Fails by: the restored pack dropped (every judging run rebuild-checks
    /// the build a shard took as made), or a pack over another rendering put
    /// back.
    #[test]
    fn a_pack_over_this_rendering_is_announced_as_reused() {
        let work = crate::scratch::scratch("schema-announce-work");
        let state = crate::scratch::scratch("schema-announce-state");
        std::fs::write(work.join("lib.rs"), "pub fn f() {}\n").unwrap();
        let target = state.join("target");
        std::fs::create_dir_all(target.join("debug/deps")).unwrap();
        std::fs::write(target.join("debug/deps/x-1"), "test binary").unwrap();
        let document = format!(
            r#"{{"rust-build-meta":{{"target-directory":"{}"}},"rust-binaries":{{"x":{{"binary-path":"{}"}}}}}}"#,
            target.display(),
            target.join("debug/deps/x-1").display()
        );
        let dir = state.join("reuse");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("binaries.json"), &document).unwrap();
        std::fs::write(dir.join("cargo-metadata.json"), "{}").unwrap();
        let tree = tree_digest(&work).unwrap();
        pack(
            &state,
            &document,
            (&tree, &Known::default(), &std::collections::BTreeMap::new()),
        )
        .unwrap();
        let mut out = Vec::new();
        let reuse = announce_reuse(&work, &target, (&[], &Known::default()), &state, &mut out)
            .unwrap()
            .expect("the packed build's binaries");
        assert_eq!(reuse.ids, BTreeSet::from([String::from("x")]));
        assert_eq!(
            String::from_utf8(out).unwrap(),
            "mutate schema: judging runs reuse the packed build's binaries\n"
        );
    }

    /// The clean build is recorded for every judging run to reuse, and packed
    /// with the sets its tree was rendered with, which a shard reads back.
    ///
    /// Fails by: nothing recorded (every judging run rebuild-checks, and no
    /// shard has a pack to take), or the pack missing the rendered sets (a CI
    /// shard renders every refused mutant switched and rebuilds cold).
    #[test]
    fn the_clean_build_is_recorded_and_packed_with_its_sets() {
        let work = crate::scratch::scratch("schema-record-work");
        let state = crate::scratch::scratch("schema-record-state");
        std::fs::create_dir_all(work.join("src")).unwrap();
        std::fs::write(
            work.join("Cargo.toml"),
            "[package]\nname = \"p\"\nversion = \"0.0.0\"\nedition = \"2021\"\n\n[workspace]\n",
        )
        .unwrap();
        std::fs::write(work.join("src/lib.rs"), "#[test]\nfn t() {}\n").unwrap();
        let target = state.join("target");
        let mut mutant = listed("FnValue", "()", (1, 1), (1, 2));
        mutant.package = String::from("p");
        let unprobed = BTreeSet::from([String::from("src/lib.rs")]);
        let known = Known::of(&BTreeSet::from([3]), &BTreeSet::from([4]), &unprobed);
        let reuse = record_reuse((&work, &target, &state), &[mutant], ("tree-1", &known))
            .expect("the clean build's binaries");
        assert_eq!(reuse.ids, BTreeSet::from([String::from("p")]));
        let dir = state.join("reuse");
        assert_eq!(
            std::fs::read_to_string(dir.join(PACKED_TREE)).unwrap(),
            "tree-1"
        );
        let packed: Known =
            serde_json::from_str(&std::fs::read_to_string(dir.join(PACKED_KNOWN)).unwrap())
                .unwrap();
        assert_eq!(packed.unviable, BTreeSet::from([3]));
        assert_eq!(packed.handed, BTreeSet::from([4]));
        assert_eq!(packed.unprobed, unprobed);
    }

    /// The clean build's listing inherits no `NEXTEST_*` or `MUTANT_*`, though
    /// it sets no env of its own, and keeps everything else.
    ///
    /// Fails by: the sweep's `NEXTEST_PROFILE=mutants` reaching the listing,
    /// which nextest refuses over a tree that declares no such profile, so no
    /// reuse record is written and every judging run builds cold (CLOUD-2897).
    #[test]
    fn the_record_listing_inherits_no_nextest_or_mutant_variable() {
        let inherited = ["NEXTEST_PROFILE", "MUTANT_SHARD", "PATH", "CARGO_HOME"]
            .map(String::from)
            .to_vec();
        assert_eq!(
            RECORD_SCRUB(inherited.into_iter(), &[]),
            ["NEXTEST_PROFILE", "MUTANT_SHARD"]
        );
    }

    /// A shard judges only its own ids, from the whole listing's build: its
    /// switched mutants, its hand-backs and its unviable count, partitioning
    /// the listing with every other shard; no shard judges everything.
    ///
    /// Fails by: a shard judging another's mutant (two shards pay for one,
    /// and their journals race), one judged by no shard (a survivor never
    /// seen), or a shard's report counting the whole listing's unviable.
    #[test]
    fn a_shard_judges_only_its_ids() {
        let todo = vec![0, 2, 3, 4, 5, 8];
        let classic = BTreeSet::from([7, 10]);
        let unviable = BTreeSet::from([1, 6, 9]);
        let keys: Vec<String> = (0..11).map(|id| format!("site {id}")).collect();
        let scope = |shard| Scope {
            shard,
            phase: Phase::Judge,
        };
        // Each expectation from the key rule: shard 1 of 3 holds the ids whose
        // key's blake3 falls there.
        let ours = |id: &u32| shard_index(&keys[*id as usize], 3) == 1;
        // The rule itself spreads them, or every partition check below holds
        // of a rule that sends every key to one shard.
        let spread: BTreeSet<usize> = keys.iter().map(|key| shard_index(key, 3)).collect();
        assert_eq!(
            spread,
            BTreeSet::from([0, 1, 2]),
            "the keys fall in every shard"
        );
        let (mine, handed, dead) =
            scope(Some((1, 3))).slice(&keys, todo.clone(), &classic, &unviable);
        assert_eq!(mine, todo.iter().copied().filter(ours).collect::<Vec<_>>());
        assert_eq!(handed, classic.iter().copied().filter(ours).collect());
        assert_eq!(dead, unviable.iter().filter(|id| ours(id)).count());
        let mut every: Vec<u32> = Vec::new();
        let mut every_handed = BTreeSet::new();
        let mut every_dead = 0;
        for k in 0..3 {
            let (mine, handed, dead) =
                scope(Some((k, 3))).slice(&keys, todo.clone(), &classic, &unviable);
            every.extend(mine);
            every_handed.extend(handed);
            every_dead += dead;
        }
        every.sort_unstable();
        assert_eq!(every, todo, "the shards partition the judged ids");
        assert_eq!(every_handed, classic);
        assert_eq!(every_dead, unviable.len());
        let (all, all_handed, all_dead) =
            scope(None).slice(&keys, todo.clone(), &classic, &unviable);
        assert_eq!((all, all_handed, all_dead), (todo, classic, unviable.len()));
    }

    /// The phase is the whole sweep unless `reach` is named; anything else
    /// named is a usage error, never read as the whole sweep.
    ///
    /// Fails by: a misspelt phase judging everything in a job meant only to
    /// build and reach (every shard's work paid twice), or `reach` ignored.
    #[test]
    fn the_phase_is_reach_only_when_named() {
        assert_eq!(phase_parsed(None), Ok(Phase::Judge));
        assert_eq!(phase_parsed(Some("")), Ok(Phase::Judge));
        assert_eq!(phase_parsed(Some("reach")), Ok(Phase::Reach));
        assert!(phase_parsed(Some("reached")).is_err());
    }

    /// A reach-phase sweep answers success once the reach run is sealed, judges
    /// nothing and hands nothing back, so the shards' judging is the verdict.
    ///
    /// Fails by: a reach job read as a verdict (red for a survivor it never
    /// judged, or green standing in for the shards), or one listing hand-backs.
    #[test]
    fn a_reach_phase_sweep_answers_success_once_sealed() {
        let mut out = Vec::new();
        let swept = reach_sealed(&mut out, &Reach::default()).unwrap();
        assert_eq!(exit_of(swept.code), crate::exit::ExitCode::Success);
        assert!(swept.classic.is_empty());
        let said = String::from_utf8(out).unwrap();
        assert!(said.contains("sealed"), "{said}");
    }

    /// A deleted resource keys apart from an emptied one, and one that cannot
    /// be read is could-not-look, never hashed as empty bytes.
    ///
    /// Fails by: a deleted fixture and an emptied one keying alike (a verdict
    /// reused across the difference), or an unreadable path digested as empty
    /// (a verdict reused over content nobody read).
    #[test]
    fn an_unreadable_resource_is_could_not_look_and_a_deleted_one_is_not_empty() {
        let base = crate::scratch::scratch("schema-resource-unreadable");
        crate::gitwrite::init_on_main(&base).unwrap();
        std::fs::write(base.join("notes.md"), "one\n").unwrap();
        crate::gitwrite::commit_paths(&base, &[String::from("notes.md")], "base").unwrap();
        std::fs::write(base.join("notes.md"), "").unwrap();
        let emptied = resource_digest(&base).unwrap();
        std::fs::remove_file(base.join("notes.md")).unwrap();
        let deleted = resource_digest(&base).unwrap();
        assert_ne!(deleted, emptied, "absent is not empty");
        std::fs::create_dir(base.join("notes.md")).unwrap();
        std::fs::write(base.join("notes.md").join("inner"), "x").unwrap();
        let refused = resource_digest(&base).expect_err("a path that cannot be read");
        assert!(format!("{refused:#}").contains("notes.md"), "{refused:#}");
    }

    /// A file's bytes are hashed when read, an absent one as absent, and any
    /// other read failure refuses the digest.
    ///
    /// Fails by: a failed read hashed as empty bytes, or an absent file keyed
    /// as an empty one.
    #[test]
    fn a_file_that_cannot_be_read_refuses_its_digest() {
        let hashed = |read: std::io::Result<&[u8]>| {
            let mut hasher = blake3::Hasher::new();
            hash_file(&mut hasher, b"f", read, std::path::Path::new("f"))
                .map(|()| hasher.finalize().to_hex().to_string())
        };
        let empty = hashed(Ok(&[])).unwrap();
        let absent = hashed(Err(std::io::ErrorKind::NotFound.into())).unwrap();
        assert_ne!(absent, empty);
        assert!(hashed(Err(std::io::ErrorKind::PermissionDenied.into())).is_err());
    }

    /// A journal line that cannot be written is said, with how many failed,
    /// and the verdict it held still stands.
    ///
    /// Fails by: a failed write dropped silently (the next sweep re-judges
    /// work this one believed journaled), or the verdict lost with it.
    #[test]
    fn a_journal_line_that_cannot_be_written_is_said() {
        let base = crate::scratch::scratch("schema-journal-unwritable");
        let store = base.join("verdicts");
        std::fs::create_dir_all(&store).unwrap();
        let mutants = [listed("BinaryOperator", "!=", (2, 7), (2, 9))];
        let (reach, seconds, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let red = Red::new();
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &store,
            red: &red,
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let mut out = Vec::new();
        let verdicts = judge_all(&judging, &[0], 1, &mut out);
        assert_eq!(verdicts, [(0, Verdict::Uncovered)], "the verdict stands");
        let said = String::from_utf8(out).unwrap();
        assert!(
            said.contains("1 journal line(s) could not be written"),
            "{said}"
        );
    }

    /// A passing control is journaled under its own case and digest: one
    /// case's journaled control is never another's, nor a case's whose
    /// digest moved, and a case with no digest has none.
    ///
    /// Fails by: every case's control keyed alike, so a case whose control
    /// never ran here reads another's seconds, skips its control and is
    /// judged against a baseline it never had (CLOUD-2789).
    #[test]
    fn a_journaled_control_answers_only_its_own_case_and_digest() {
        let base = crate::scratch::scratch("schema-control-key");
        let (own, other, digestless) = (case("own"), case("other"), case("bare"));
        let (reach, seconds, red) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            Red::new(),
        );
        let control = Control::new();
        let digests = |own_digest: &str| -> std::collections::BTreeMap<Case, String> {
            [
                (own.clone(), own_digest.to_owned()),
                (other.clone(), String::from("d2")),
            ]
            .into()
        };
        macro_rules! judging {
            ($cache:expr, $digests:expr) => {
                Judging {
                    work: &base,
                    target: &base,
                    scratch: &base,
                    root: &base,
                    mutants: &[],
                    reach: &reach,
                    seconds: &seconds,
                    cache: $cache,
                    digests: $digests,
                    store: &base,
                    red: &red,
                    control: &control,
                    reuse: None,
                    threads: None,
                }
            };
        }
        let held = digests("d1");
        let empty = std::collections::BTreeMap::new();
        let key = control_key(&judging!(&empty, &held), &own).unwrap();
        assert_ne!(
            Some(&key),
            control_key(&judging!(&empty, &held), &other).as_ref()
        );
        assert_eq!(control_key(&judging!(&empty, &held), &digestless), None);
        let cache = [(key, format!("{CONTROLLED}1.5"))].into();
        let journaled = judging!(&cache, &held);
        assert_eq!(journaled_control(&journaled, &own), Some(1.5));
        assert_eq!(journaled_control(&journaled, &other), None);
        assert_eq!(journaled_control(&journaled, &digestless), None);
        let moved = digests("d3");
        assert_eq!(journaled_control(&judging!(&cache, &moved), &own), None);
    }

    /// A run asked for every case's outcome is never cut at its first
    /// failure, and a fail-fast one is.
    ///
    /// Fails by: `--no-fail-fast` passed to a fail-fast run (it runs on past
    /// the kill it was asked to stop at) or withheld from a run that must see
    /// every case (the cases after the first failure read as undecided)
    /// (CLOUD-2789).
    #[test]
    fn only_a_run_asking_for_every_outcome_is_not_cut_at_its_first_failure() {
        let base = crate::scratch::scratch("schema-judge-argv");
        let mutants = [listed("BinaryOperator", "!=", (2, 7), (2, 9))];
        let (reach, seconds, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let (red, control) = (Red::new(), Control::new());
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &base,
            red: &red,
            control: &control,
            reuse: None,
            threads: Some(3),
        };
        let cases: BTreeSet<Case> = [case("a")].into();
        let cut = |fail_fast| {
            judge_argv(&judging, &mutants[0], &cases, fail_fast)
                .iter()
                .any(|arg| arg == "--no-fail-fast")
        };
        assert!(!cut(true), "a fail-fast run stops at its first failure");
        assert!(cut(false), "a run for every outcome is never cut short");
        let argv = judge_argv(&judging, &mutants[0], &cases, true);
        assert!(
            argv.windows(2).any(|pair| pair == ["--test-threads", "3"]),
            "{argv:?}"
        );
    }

    /// A run is bounded by five times its cases' measured time, never under
    /// the floor, plus its startup; an unmeasured case counts its default.
    ///
    /// Fails by: the multiplier, the floor or the startup dropped, or an
    /// unmeasured case counted as free.
    #[test]
    fn a_run_is_bounded_by_its_own_cases_time() {
        let (quick, slow) = (case("quick"), case("slow"));
        let seconds = [(quick.clone(), 0.5), (slow.clone(), 10.0)].into();
        let bound = |cases: &[&Case]| {
            case_bound(&cases.iter().map(|c| (*c).clone()).collect(), &seconds).as_secs_f64()
        };
        assert!((bound(&[&quick]) - 50.0).abs() < 1e-9, "the floor");
        assert!((bound(&[&quick, &slow]) - 82.5).abs() < 1e-9, "5x 10.5 s");
        let unmeasured = case("unmeasured");
        let many: Vec<Case> = (0..5).map(|n| case(&format!("u{n}"))).collect();
        let refs: Vec<&Case> = many.iter().chain([&unmeasured]).collect();
        assert!((bound(&refs) - 60.0).abs() < 1e-9, "six at 1 s each");
    }

    /// An error on a probe unprobes its file, even inside a mutant's branch.
    #[test]
    fn an_error_on_a_probe_unprobes_its_file() {
        let source = "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n";
        let rendered = render(
            source,
            &[(0, &listed("BinaryOperator", "!=", (2, 7), (2, 9)))],
            &BTreeSet::new(),
            Some(0),
        );
        let at = rendered.probe_regions[0].start + 2;
        let schema = Schema {
            files: [(String::from("src/m.rs"), rendered)].into(),
            ..Schema::default()
        };
        let message = format!(
            "{{\"reason\":\"compiler-message\",\"message\":{{\"level\":\"error\",\"message\":\"e\",\
             \"spans\":[{{\"is_primary\":true,\"file_name\":\"src/m.rs\",\"byte_start\":{at}}}]}}}}"
        );
        let refused = unviable(&schema, &message);
        assert_eq!(refused.unprobe, [String::from("src/m.rs")].into());
        assert!(refused.owned.is_empty() && refused.stray.is_empty());
    }

    #[test]
    fn only_a_stored_unviable_verdict_skips_a_build() {
        let keys = [Some("k1"), None, Some("k2"), Some("k3")].map(|k| k.map(String::from));
        let cache = [
            (String::from("k1"), String::from("unviable")),
            (String::from("k2"), String::from("caught")),
        ]
        .into();
        assert_eq!(cached_unviable(&keys, &cache), [0].into());
    }

    /// The report names every verdict but a kill, counts each, and exits 2 on
    /// a survivor and 0 when every mutant was caught.
    #[test]
    fn a_report_names_each_survivor_and_counts_every_verdict() {
        let state = crate::scratch::scratch("schema-report");
        let mutants: Vec<Listed> = ["m0", "m1", "m2"]
            .map(|name| {
                let mut mutant = listed("FnValue", "true", (1, 1), (1, 2));
                mutant.name = String::from(name);
                mutant
            })
            .into();
        let mut out = Vec::new();
        let verdicts = [
            (0, Verdict::Caught),
            (1, Verdict::Missed),
            (2, Verdict::Uncovered),
        ];
        let none = (&Red::new(), &std::collections::BTreeMap::new());
        let code = report(&mut out, &mutants, &verdicts, none, (4, 5), &state, 7).unwrap();
        let said = String::from_utf8(out).unwrap();
        assert_eq!(code, 2);
        assert!(
            said.contains("missed\tm1\n") && said.contains("uncovered\tm2\n"),
            "{said}"
        );
        assert!(!said.contains("\tm0"), "{said}");
        assert!(
            said.contains(
                "{\"caught\": 1, \"missed\": 1, \"uncovered\": 1}, 4 unviable, 5 classic, in 7s"
            ),
            "{said}"
        );
        let mut out = Vec::new();
        let none = (&Red::new(), &std::collections::BTreeMap::new());
        let code = report(&mut out, &mutants, &verdicts[..1], none, (0, 0), &state, 7).unwrap();
        assert_eq!(code, 0);
        // A HANG DECIDED NOTHING: could-not-look, never a pass.
        let mut out = Vec::new();
        let hung = [(0, Verdict::Caught), (1, Verdict::Timeout)];
        let code = report(&mut out, &mutants, &hung, none, (0, 0), &state, 7).unwrap();
        let said = String::from_utf8(out).unwrap();
        assert_eq!(code, 3, "{said}");
        assert!(said.contains("timeout\tm1\n"), "{said}");
        // A RED CASE IS LISTED WITH ITS LINE, AN UNJUDGED MUTANT NAMES IT, AND
        // THE EXIT IS 2 EVEN WHEN EVERY MUTANT WAS CAUGHT.
        let case = (String::from("tests::red"), String::from("fix"));
        let red: Red = [(case.clone(), String::from("red first"))].into();
        let blame = [(1, [case].into())].into();
        let mut out = Vec::new();
        let poisoned = [(0, Verdict::Caught), (1, Verdict::Unjudged)];
        let code = report(
            &mut out,
            &mutants,
            &poisoned,
            (&red, &blame),
            (0, 0),
            &state,
            7,
        )
        .unwrap();
        let said = String::from_utf8(out).unwrap();
        assert_eq!(code, 2, "{said}");
        for line in [
            "baseline-red\tfix tests::red\tred first\n",
            "unjudged (baseline-red: fix tests::red)\tm1\n",
            "{\"caught\": 1, \"unjudged\": 1}",
            "mutate schema: 1 baseline-red case(s), 1 unjudged mutant(s)\n",
        ] {
            assert!(said.contains(line), "{line:?} in {said}");
        }
        let mut out = Vec::new();
        let code = report(
            &mut out,
            &mutants,
            &verdicts[..1],
            (&red, none.1),
            (0, 0),
            &state,
            7,
        );
        assert_eq!(code.unwrap(), 2, "a red case alone keeps the exit non-zero");
    }

    /// Fails by: an unjudged mutant with no red case beside it left out of
    /// the closing count, so a sweep that judged nothing of it says nothing.
    #[test]
    fn an_unjudged_mutant_alone_is_counted() {
        let state = crate::scratch::scratch("schema-report-unjudged");
        let mutants: Vec<Listed> = ["m0", "m1"]
            .map(|name| {
                let mut mutant = listed("FnValue", "true", (1, 1), (1, 2));
                mutant.name = String::from(name);
                mutant
            })
            .into();
        let mut out = Vec::new();
        let unjudged = [(0, Verdict::Caught), (1, Verdict::Unjudged)];
        let none = (&Red::new(), &std::collections::BTreeMap::new());
        report(&mut out, &mutants, &unjudged, none, (0, 0), &state, 7).unwrap();
        let said = String::from_utf8(out).unwrap();
        assert!(
            said.contains("mutate schema: 0 baseline-red case(s), 1 unjudged mutant(s)\n"),
            "{said}"
        );
    }

    /// Each case's own recorded outcome against a mutant decides it or narrows
    /// its run: a recorded kill is a kill with no run, every case recorded
    /// passing is a survivor with no run, and a case recorded passing is left
    /// out of the run the rest still owe.
    ///
    /// Fails by: a recorded kill run again, a mutant whose every case passed
    /// run again, or a recorded pass not narrowing the run.
    #[test]
    fn a_recorded_outcome_per_case_decides_or_narrows_a_mutant() {
        /// An id no other case's run uses, so its kept log is this case's.
        const ERRING: u32 = 90_017;
        let base = crate::scratch::scratch("schema-judge-pairs");
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(
            base.join("src/lib.rs"),
            "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n",
        )
        .unwrap();
        let mutant = in_function(
            listed("BinaryOperator", "!=", (2, 7), (2, 9)),
            (1, 1),
            (3, 2),
        );
        let a: Case = (String::from("a"), String::from("batten"));
        let b: Case = (String::from("b"), String::from("batten"));
        let cases: BTreeSet<Case> = [a.clone(), b.clone()].into();
        let digests = std::collections::BTreeMap::new();
        let pair = |case: &Case| pair_key(&base, &mutant, case, &digests).unwrap();
        let mutants = [mutant.clone()];
        let judged_by = |cache: std::collections::BTreeMap<String, String>| {
            let (reach, seconds) = Default::default();
            let store = base.join("verdicts");
            let judging = Judging {
                work: &base,
                target: &base,
                scratch: &base,
                root: &base,
                mutants: &mutants,
                reach: &reach,
                seconds: &seconds,
                cache: &cache,
                digests: &digests,
                store: &store,
                red: &Red::new(),
                control: &Control::new(),
                reuse: None,
                threads: None,
            };
            let hints = std::sync::Mutex::new(std::collections::BTreeMap::new());
            let journal = std::sync::Mutex::new(Journal::default());
            judge(&judging, ERRING, &mutant, &cases, &hints, &journal)
        };
        let judged = |cache: std::collections::BTreeMap<String, String>| {
            let judged = judged_by(cache);
            (judged.verdict, judged.skipped)
        };
        let caught = String::from("caught");
        let passed = String::from(PASSED);
        assert!(
            judged_by([(pair(&b), caught.clone())].into()).held_kill,
            "a recorded kill is counted as decided by a held kill pair"
        );
        assert!(
            !judged_by([(pair(&a), passed.clone()), (pair(&b), passed.clone())].into()).held_kill,
            "every case recorded passing is no held kill"
        );
        assert_eq!(
            judged([(pair(&b), caught)].into()),
            (Verdict::Caught, 2),
            "a recorded kill decides it"
        );
        assert_eq!(
            judged([(pair(&a), passed.clone()), (pair(&b), passed.clone())].into()),
            (Verdict::Missed, 2),
            "every case recorded passing"
        );
        let (verdict, skipped) = judged([(pair(&a), passed)].into());
        assert_eq!(skipped, 1, "the recorded pass is left out of the run");
        assert!(
            !matches!(verdict, Verdict::Caught | Verdict::Missed),
            "the open case was run, and here no run can start: {verdict:?}"
        );
        // Fails by: an erring run's words dropped rather than kept.
        let kept = base
            .parent()
            .unwrap()
            .join("errors")
            .join(format!("{ERRING}.log"));
        assert!(kept.is_file(), "{} is kept", kept.display());
        assert_eq!(journaled_kill(Verdict::Caught, Some(&a)), Some(&a));
        assert_eq!(journaled_kill(Verdict::Timeout, Some(&a)), None);
        assert_ne!(pair(&a), pair(&b), "each case is its own pair");
    }

    /// Each way a judging run can end, judged from its process outcome and its
    /// report alone.
    ///
    /// Fails by: a caught mutant filed a timeout or a miss, a timeout filed a
    /// kill, a run with no report or a report missing a case read as a miss, or
    /// a passing run's cases dropped.
    #[test]
    fn a_run_is_judged_from_its_report_and_its_exit() {
        use super::super::Outcome;
        let pair = |name: &str, binary: &str| (String::from(name), String::from(binary));
        let a = pair("tests::a", "batten");
        let b = pair("m::b", "batten::it");
        let cases: BTreeSet<Case> = [a.clone(), b.clone()].into();
        let caught = junit_cases(JUNIT_FIXTURE).expect("XML");
        let (verdict, killer, passed) =
            verdict_of_run(Outcome::Failed(Some(100)), Some(&caught), &cases, "");
        assert_eq!((verdict, killer), (Verdict::Caught, Some(b.clone())));
        assert!(passed.contains(&a) && !passed.contains(&b), "{passed:?}");
        let timed = [(a.clone(), CaseEnd::Passed), (b.clone(), CaseEnd::TimedOut)];
        assert_eq!(
            verdict_of_run(Outcome::Failed(Some(100)), Some(&timed), &cases, "").0,
            Verdict::Timeout
        );
        assert_eq!(
            verdict_of_run(Outcome::TimedOut, None, &cases, "").0,
            Verdict::Timeout
        );
        let clean = [(a.clone(), CaseEnd::Passed), (b.clone(), CaseEnd::Passed)];
        let missed = verdict_of_run(Outcome::Passed, Some(&clean), &cases, "");
        assert_eq!((missed.0, missed.2.len()), (Verdict::Missed, 2));
        // Could-not-look: no report, an empty one, or one missing a case.
        assert_eq!(
            verdict_of_run(Outcome::Passed, None, &cases, "").0,
            Verdict::Error
        );
        assert_eq!(
            verdict_of_run(Outcome::Passed, Some(&[]), &cases, "").0,
            Verdict::Error
        );
        assert_eq!(
            verdict_of_run(Outcome::Passed, Some(&clean[..1]), &cases, "").0,
            Verdict::Error
        );
        assert_eq!(
            verdict_of_run(Outcome::Failed(Some(101)), Some(&clean), &cases, "").0,
            Verdict::Error
        );
    }

    /// A run the judge's bound ended, with no report, is caught by the case
    /// its own output reports failed first (CLOUD-2908, CLOUD-2909).
    ///
    /// Fails by: the bound read before the output, so a kill that a hanging
    /// sibling held past the bound is filed a timeout; a `FAIL` of a case the
    /// run did not select, or a `PASS`, read as the kill.
    #[test]
    fn a_kill_held_past_the_bound_by_a_hanging_sibling_is_caught() {
        use super::super::Outcome;
        let pair = |name: &str, binary: &str| (String::from(name), String::from(binary));
        let a = pair("tests::a", "batten");
        let b = pair("m::b", "batten::it");
        let cases: BTreeSet<Case> = [a.clone(), b.clone()].into();
        let said = "        START             batten tests::a\n        \
                    PASS [   0.004s] batten tests::other\n        \
                    FAIL [   0.600s] batten::it m::b\n        \
                    SLOW [> 60.000s] batten tests::a\n";
        let (verdict, killer, _) = verdict_of_run(Outcome::TimedOut, None, &cases, said);
        assert_eq!((verdict, killer), (Verdict::Caught, Some(b.clone())));
        let foreign = "        FAIL [   0.600s] batten tests::other\n";
        assert_eq!(
            verdict_of_run(Outcome::TimedOut, None, &cases, foreign),
            (Verdict::Timeout, None, Vec::new())
        );
        let passed = "        PASS [   0.600s] batten::it m::b\n";
        assert_eq!(
            verdict_of_run(Outcome::TimedOut, None, &cases, passed),
            (Verdict::Timeout, None, vec![b.clone()])
        );
        // A REPORT, WHEN ONE WAS WRITTEN, names the passes, not the output.
        let reported = [(a.clone(), CaseEnd::Passed)];
        assert_eq!(
            verdict_of_run(Outcome::TimedOut, Some(&reported), &cases, passed),
            (Verdict::Timeout, None, vec![a])
        );
    }

    /// No case's cut is a kill by its hang.
    fn no_hang(_: &Case) -> bool {
        false
    }

    /// Every run a scripted judge was handed, with its `fail_fast`, in order.
    type Asked = std::rc::Rc<std::cell::RefCell<Vec<(BTreeSet<Case>, bool)>>>;

    /// A run's [`Turn`].
    fn turn(verdict: Verdict, killer: Option<Case>, passed: &[Case], hung: &[Case]) -> Turn {
        Turn {
            verdict,
            killer,
            passed: passed.to_vec(),
            hung: hung.to_vec(),
        }
    }

    /// A scripted judge: each run's [`Turn`] by the cases and `fail_fast` it
    /// was handed, and every run it was handed, in order.
    fn scripted(
        answers: Vec<((BTreeSet<Case>, bool), Turn)>,
    ) -> (
        impl FnMut(&BTreeSet<Case>, bool) -> anyhow::Result<Turn>,
        Asked,
    ) {
        let asked = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let log = std::rc::Rc::clone(&asked);
        let run = move |cases: &BTreeSet<Case>, fail_fast: bool| {
            log.borrow_mut().push((cases.clone(), fail_fast));
            answers
                .iter()
                .find(|(given, _)| given.0 == *cases && given.1 == fail_fast)
                .map(|(_, answer)| answer.clone())
                .ok_or_else(|| anyhow::anyhow!("unscripted run {cases:?} {fail_fast}"))
        };
        (run, asked)
    }

    fn near(left: f64, right: f64) -> bool {
        (left - right).abs() < 1e-9
    }

    /// No case is cut before twenty seconds, so a killer that fails only after
    /// an internal wait of ten (`exec.rs`'s `PIPE_DRAIN_TIMEOUT`) still fails;
    /// a slow case is cut at five times its seconds; a first run is bounded by
    /// five times its cases' seconds and one floor; a second run by its cases'
    /// cuts end to end (CLOUD-2911).
    ///
    /// Fails by: a floor below a case's internal waits, so a kill is filed a
    /// timeout (review of `c8ccefd87`, major 1); the floor applied per case in
    /// the first run, so a hundred 0.1 s cases are bounded at 2,030 s; or a
    /// second run bounded below its cases' cuts end to end.
    #[test]
    fn no_case_is_cut_before_it_can_fail_at_its_own_pace() {
        let (slow, quick, unmeasured) = (case("slow"), case("quick"), case("new"));
        let seconds = [(slow.clone(), 10.0), (quick.clone(), 0.4)].into();
        assert!(near(case_limit(&slow, &seconds), 50.0), "5x 10 s");
        assert!(near(case_limit(&quick, &seconds), 20.0), "the floor");
        assert!(near(case_limit(&unmeasured, &seconds), 20.0), "unmeasured");
        assert!(
            case_limit(&quick, &seconds) > 10.0,
            "past PIPE_DRAIN_TIMEOUT"
        );
        let hundred: BTreeSet<Case> = (0..100).map(|n| case(&format!("c{n}"))).collect();
        let tenth = hundred.iter().map(|one| (one.clone(), 0.1)).collect();
        assert!(
            near(first_bound(&hundred, &tenth), 101.0),
            "30 + 5x 10 s + 20 + 1"
        );
        let both: BTreeSet<Case> = [quick, unmeasured].into();
        assert!(
            near(second_bound(&both, &seconds), 72.0),
            "30 + 2 x (20 + 1)"
        );
        assert!(near(
            run_bound(&both, &seconds, true),
            first_bound(&both, &seconds)
        ));
        assert!(near(run_bound(&both, &seconds, false), 72.0));
    }

    /// A humantime period in seconds, whole or fractional, in one unit or
    /// several; anything else reads as none (CLOUD-2911).
    ///
    /// Fails by: a unit read at the wrong scale; a multi-part or fractional
    /// period read as none, so a consumer's tighter cut is lost; or a bare
    /// number read as one.
    #[test]
    fn a_period_reads_as_its_seconds() {
        assert_eq!(period_seconds("500ms"), Some(0.5));
        assert_eq!(period_seconds("10s"), Some(10.0));
        assert_eq!(period_seconds(" 2m "), Some(120.0));
        assert_eq!(period_seconds("1h"), Some(3600.0));
        assert_eq!(period_seconds("1.5s"), Some(1.5));
        assert_eq!(period_seconds("1m 30s"), Some(90.0));
        assert_eq!(period_seconds("1m30s"), Some(90.0));
        assert_eq!(period_seconds("2min"), Some(120.0));
        assert_eq!(period_seconds("3secs"), Some(3.0));
        assert_eq!(period_seconds("10"), None);
        assert_eq!(period_seconds("10d"), None);
        assert_eq!(period_seconds("s"), None);
        assert_eq!(period_seconds(""), None);
    }

    /// A judging run selects each case by its binary and name, so a same-named
    /// case in another selected binary never runs; a case whose binary went
    /// unrecorded by its name; and a batch is cut by those filters' bytes
    /// (CLOUD-2911).
    ///
    /// Fails by: a selection by name alone, so a twin runs uncut and
    /// uncharged, as often as four times; `binary_id(=)` written for an
    /// unrecorded binary, which nextest refuses; or a batch sized by the old,
    /// shorter filter, past one argument.
    #[test]
    fn a_run_selects_each_case_by_its_binary_and_name() {
        let cases: BTreeSet<Case> = [
            (String::from("m::a"), String::from("batten::it")),
            (String::from("m::b"), String::new()),
        ]
        .into();
        assert_eq!(
            pair_filterset(&cases),
            "(binary_id(=batten::it) & test(=m::a)) | test(=m::b)"
        );
        assert_eq!(pair_filterset(&BTreeSet::new()), "none()");
        let mutant = listed("BinaryOperator", "!=", (2, 7), (2, 9));
        let args = nextest_args(&mutant, &cases);
        let filter = args.windows(2).find(|pair| pair[0] == "-E").unwrap()[1].clone();
        assert_eq!(filter, pair_filterset(&cases));
    }

    /// Each case a judging run selects is cut at its own limit, by binary and
    /// name, with its own grace; the consumer's own overrides, the judging
    /// profile's and then the default profile's, in either form, come first;
    /// a profile-level `slow-timeout` that cuts sooner still cuts; and a run
    /// with no limits writes no override (CLOUD-2911).
    ///
    /// Fails by: a cut placed ahead of a consumer's own per-test
    /// `slow-timeout`, shadowing a looser one (review of `c8ccefd87`, major
    /// 4); the default profile's overrides outranked; an override form
    /// dropped; a cut looser than the profile's; or the grace left at
    /// nextest's ten seconds.
    #[test]
    fn each_case_is_cut_behind_the_consumers_own_overrides() {
        let config = |toml: &str, limits: &[(&Case, f64)]| {
            let work = crate::scratch::scratch("schema-judge-config-limits");
            std::fs::create_dir_all(work.join(".config")).unwrap();
            std::fs::write(work.join(".config").join("nextest.toml"), toml).unwrap();
            let text = judge_config(&work, &work.join("store"), limits).expect("config");
            let doc: toml_edit::DocumentMut = text.parse().expect("toml");
            let rows: Vec<(String, String)> = doc
                .get("profile")
                .and_then(|p| p.get("mutants"))
                .and_then(|p| p.get("overrides"))
                .and_then(toml_edit::Item::as_array_of_tables)
                .into_iter()
                .flatten()
                .map(|row| {
                    let filter = row["filter"].as_str().unwrap_or_default().to_owned();
                    let cut = row
                        .get("slow-timeout")
                        .map(|cut| cut.to_string().split_whitespace().collect::<String>())
                        .unwrap_or_default();
                    (filter, cut)
                })
                .collect();
            rows
        };
        let (a, b) = (case("m::a"), (String::from("m::a"), String::from("other")));
        let ours =
            |millis: &str| format!("{{period=\"{millis}\",terminate-after=1,grace-period=\"1s\"}}");
        let row = |filter: &str, cut: &str| (filter.to_owned(), cut.to_owned());
        let consumer = "[profile.mutants]\nslow-timeout = { period = \"5s\", terminate-after = 2 }\n\
                        [[profile.mutants.overrides]]\nfilter = \"test(=m::a)\"\n\
                        slow-timeout = { period = \"60s\", terminate-after = 2 }\n\
                        [[profile.default.overrides]]\nfilter = \"test(=held)\"\nretries = 1\n";
        assert_eq!(
            config(consumer, &[(&a, 50.0), (&b, 4.0)]),
            [
                row("test(=m::a)", "{period=\"60s\",terminate-after=2}"),
                row("test(=held)", ""),
                row("(binary_id(=batten::it) & test(=m::a))", &ours("10000ms")),
                row("(binary_id(=other) & test(=m::a))", &ours("4000ms")),
            ]
        );
        let inline = "[profile.mutants]\noverrides = [{ filter = \"test(=held)\", retries = 1 }]\n";
        assert_eq!(
            config(inline, &[(&a, 20.0)]),
            [
                row("test(=held)", ""),
                row("(binary_id(=batten::it) & test(=m::a))", &ours("20000ms")),
            ]
        );
        let inherited =
            "[profile.default]\nslow-timeout = { period = \"3s\", terminate-after = 3 }\n";
        assert_eq!(
            config(inherited, &[(&a, 50.0)]),
            [row(
                "(binary_id(=batten::it) & test(=m::a))",
                &ours("9000ms")
            )]
        );
        let unbounded = "[profile.mutants]\nslow-timeout = \"5s\"\n";
        assert_eq!(
            config(unbounded, &[(&a, 50.0)]),
            [row(
                "(binary_id(=batten::it) & test(=m::a))",
                &ours("50000ms")
            )]
        );
        let unrecorded = (String::from("m::u"), String::new());
        assert_eq!(
            config("", &[(&unrecorded, 20.0)]),
            [row("test(=m::u)", &ours("20000ms"))]
        );
        let tables = "[[profile.mutants.overrides]]\nfilter = \"test(=held)\"\nretries = 1\n";
        assert_eq!(config(tables, &[]), [row("test(=held)", "")]);
    }

    /// Every mutant's run cuts its cases and the control's never: the wiring
    /// `judge_run` takes from `BATTEN_MUTANT`, and the config each gets
    /// (CLOUD-2911).
    ///
    /// Fails by: a mutant's run handed no cuts, so a hung case holds it to its
    /// bound; or the control cut, filing a slow baseline case red.
    #[test]
    fn a_judging_run_is_cut_and_the_control_is_not() {
        assert!(cuts("7"));
        assert!(!cuts(NULL_MUTANT));
        let work = crate::scratch::scratch("schema-run-config");
        std::fs::create_dir_all(work.join(".config")).unwrap();
        std::fs::write(work.join(".config").join("nextest.toml"), "").unwrap();
        let mutants = [listed("BinaryOperator", "!=", (2, 7), (2, 9))];
        let (reach, cache, digests) = (
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
            std::collections::BTreeMap::new(),
        );
        let seconds = [(case("m::slow"), 10.0)].into();
        let red = Red::new();
        let judging = Judging {
            work: &work,
            target: &work,
            scratch: &work,
            root: &work,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &work,
            red: &red,
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let cases: BTreeSet<Case> = [case("m::slow")].into();
        let store = work.join("store");
        let judged = run_config(&judging, &store, &cases, cuts("7")).expect("config");
        assert!(
            judged.contains("(binary_id(=batten::it) & test(=m::slow))"),
            "{judged}"
        );
        assert!(judged.contains("50000ms"), "{judged}");
        let control = run_config(&judging, &store, &cases, cuts(NULL_MUTANT)).expect("config");
        assert!(!control.contains("slow-timeout"), "{control}");
    }

    /// The rows a judging run's report holds for cases it did not select are
    /// dropped (CLOUD-2911).
    ///
    /// Fails by: such a row's failure read as this mutant's kill, or its cut
    /// as a hang among this run's cases.
    #[test]
    fn only_the_selected_cases_rows_are_read() {
        let mine = case("m::a");
        let twin = (String::from("m::a"), String::from("other"));
        let rows = vec![(mine.clone(), CaseEnd::Passed), (twin, CaseEnd::Failed)];
        assert_eq!(
            selected(rows, &[mine.clone()].into()),
            [(mine, CaseEnd::Passed)]
        );
    }

    /// The cases a report says nextest cut at their own limit are its hung
    /// cases, and no other: a pass or a failure is never one, and a run with
    /// no report has none (CLOUD-2911).
    ///
    /// Fails by: no case read as hung, so a cut case is run again forever; or
    /// a passed or failed case read as hung.
    #[test]
    fn the_hung_cases_are_the_ones_nextest_cut() {
        let (cut, ok, red) = (case("cut"), case("ok"), case("red"));
        let report = [
            (ok, CaseEnd::Passed),
            (cut.clone(), CaseEnd::TimedOut),
            (red, CaseEnd::Failed),
        ];
        assert_eq!(hung_in(Some(&report)), [cut]);
        assert!(hung_in(None).is_empty());
    }

    /// A killer sorted behind ten fast hangs still has its turn: the first run
    /// stops at the first cut, and the second runs the other nine hangs to
    /// their cuts and the killer after them, all within its bound
    /// (CLOUD-2911, review of `c8ccefd87`, major 2).
    ///
    /// Fails by: a cut read as the mutant's verdict, so the cases a cut left
    /// unrun never run; the second run stopped at a cut again; or a second
    /// run bounded below its cases' cuts end to end, which ends before the
    /// killer starts.
    #[test]
    fn a_killer_behind_many_fast_hangs_is_still_caught() {
        let hangs: Vec<Case> = (0..10).map(|n| case(&format!("a{n}"))).collect();
        let killer = case("z_killer");
        let batch: BTreeSet<Case> = hangs.iter().cloned().chain([killer.clone()]).collect();
        let rest: BTreeSet<Case> = hangs[1..].iter().cloned().chain([killer.clone()]).collect();
        let seconds = std::collections::BTreeMap::new();
        // On one thread the nine hangs run to their cuts, then the killer.
        let serial = STARTUP_SECONDS + 9.0 * (20.0 + CUT_GRACE_SECONDS) + 1.0;
        assert!(
            serial <= second_bound(&rest, &seconds),
            "{serial} s within the bound"
        );
        let (mut run, asked) = scripted(vec![
            (
                (batch.clone(), true),
                turn(Verdict::Timeout, None, &[], &hangs[..1]),
            ),
            (
                (rest.clone(), false),
                turn(Verdict::Caught, Some(killer.clone()), &[], &hangs[1..]),
            ),
        ]);
        let decided = decide(std::slice::from_ref(&batch), &mut run, &no_hang, |_| {});
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Caught, Some(killer))
        );
        assert_eq!(*asked.borrow(), [(batch, true), (rest, false)]);
    }

    /// On one thread, or under the runner's cap, a first run can spend its
    /// whole bound before its cut lands, and the second run over what it left
    /// still runs: no budget left over from the first ever refuses it
    /// (CLOUD-2911, review of `c8ccefd87`, majors 3 and 5).
    ///
    /// Fails by: a second run funded only from what the first run left, which
    /// a serial or capped first run spends to nothing, refused; or the cases
    /// a cut left never run.
    #[test]
    fn a_killer_behind_a_hang_on_one_thread_is_still_caught() {
        let (done, hang, left, killer) = (case("a"), case("b"), case("c"), case("z"));
        let batch: BTreeSet<Case> =
            [done.clone(), hang.clone(), left.clone(), killer.clone()].into();
        let rest: BTreeSet<Case> = [left.clone(), killer.clone()].into();
        let (mut run, asked) = scripted(vec![
            (
                (batch.clone(), true),
                turn(Verdict::Timeout, None, &[done], std::slice::from_ref(&hang)),
            ),
            (
                (rest.clone(), false),
                turn(Verdict::Caught, Some(killer.clone()), &[left], &[]),
            ),
        ]);
        let decided = decide(std::slice::from_ref(&batch), &mut run, &no_hang, |_| {});
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Caught, Some(killer))
        );
        assert_eq!(asked.borrow().len(), 2);
    }

    /// A case the mutant hangs, cut with nothing killing, is a timeout, and no
    /// pass of its batch is journaled; a run the bound ended with no case cut
    /// keeps no pass and runs nothing again; a batch every case of which
    /// passes, or that ends in a kill with no cut, hands on its passes; and a
    /// clean batch beside a cut one keeps its own (CLOUD-2911).
    ///
    /// Fails by: a genuine hang filed a survivor; a sibling of a cut case
    /// journaled passed, so the next sweep runs the hang alone, sees it pass,
    /// and files a reusable survivor; a run that reported nothing run again;
    /// or a clean batch's passes lost, a killed one's above all.
    #[test]
    fn a_genuine_hang_stays_a_timeout_and_its_batch_keeps_no_pass() {
        let (hang, ok) = (case("hang"), case("ok"));
        let batch: BTreeSet<Case> = [hang.clone(), ok.clone()].into();
        let decided_with = |answer: Turn| {
            let (mut run, asked) = scripted(vec![((batch.clone(), true), answer)]);
            let mut passes = Vec::new();
            let decided = decide(std::slice::from_ref(&batch), &mut run, &no_hang, |case| {
                passes.push(case.clone());
            });
            let runs = asked.borrow().len();
            (
                decided
                    .map(|(verdict, killer, _)| (verdict, killer))
                    .expect("runs"),
                passes,
                runs,
            )
        };
        let cut = turn(
            Verdict::Timeout,
            None,
            std::slice::from_ref(&ok),
            std::slice::from_ref(&hang),
        );
        assert_eq!(decided_with(cut), ((Verdict::Timeout, None), Vec::new(), 1));
        for passed in [vec![ok.clone(), hang.clone()], Vec::new()] {
            let uncut = turn(Verdict::Timeout, None, &passed, &[]);
            assert_eq!(
                decided_with(uncut),
                ((Verdict::Timeout, None), Vec::new(), 1)
            );
        }
        let clean = turn(Verdict::Missed, None, &[hang.clone(), ok.clone()], &[]);
        assert_eq!(
            decided_with(clean),
            ((Verdict::Missed, None), vec![hang.clone(), ok.clone()], 1)
        );
        let killed = turn(
            Verdict::Caught,
            Some(hang.clone()),
            std::slice::from_ref(&ok),
            &[],
        );
        assert_eq!(
            decided_with(killed),
            ((Verdict::Caught, Some(hang.clone())), vec![ok.clone()], 1)
        );
        let (first, second): (BTreeSet<Case>, BTreeSet<Case>) =
            ([case("fine")].into(), batch.clone());
        let (mut run, _) = scripted(vec![
            (
                (first.clone(), true),
                turn(Verdict::Missed, None, &[case("fine")], &[]),
            ),
            (
                (second.clone(), true),
                turn(
                    Verdict::Timeout,
                    None,
                    std::slice::from_ref(&ok),
                    std::slice::from_ref(&hang),
                ),
            ),
        ]);
        let mut passes = Vec::new();
        let decided = decide(&[first, second], &mut run, &no_hang, |case| {
            passes.push(case.clone());
        });
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Timeout, None)
        );
        assert_eq!(passes, [case("fine")]);
        let rest: BTreeSet<Case> = [ok.clone()].into();
        let (mut run, _) = scripted(vec![
            (
                (batch.clone(), true),
                turn(Verdict::Timeout, None, &[], std::slice::from_ref(&hang)),
            ),
            (
                (rest, false),
                turn(Verdict::Caught, Some(ok.clone()), &[], &[]),
            ),
        ]);
        let mut passes = Vec::new();
        let decided = decide(std::slice::from_ref(&batch), &mut run, &no_hang, |case| {
            passes.push(case.clone());
        });
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Caught, Some(ok))
        );
        assert!(passes.is_empty(), "a kill after a cut keeps no pass");
    }

    /// A hang in one batch decides only when no later batch kills: the runs
    /// go on past it, and a later kill outranks it (CLOUD-2911).
    ///
    /// Fails by: a cut ending the mutant's judging, so a kill in a later batch
    /// is filed a timeout; or a hang with no kill filed a survivor.
    #[test]
    fn a_later_kill_outranks_an_earlier_hang() {
        let (hang, ok, killer) = (case("hang"), case("ok"), case("killer"));
        let runs: Vec<BTreeSet<Case>> = vec![
            [hang.clone()].into(),
            [ok.clone()].into(),
            [killer.clone()].into(),
        ];
        let script = |last: Turn| {
            scripted(vec![
                (
                    (runs[0].clone(), true),
                    turn(Verdict::Timeout, None, &[], std::slice::from_ref(&hang)),
                ),
                (
                    (runs[1].clone(), true),
                    turn(Verdict::Missed, None, std::slice::from_ref(&ok), &[]),
                ),
                ((runs[2].clone(), true), last),
            ])
        };
        let (mut run, _) = script(turn(Verdict::Caught, Some(killer.clone()), &[], &[]));
        let decided = decide(&runs, &mut run, &no_hang, |_| {});
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Caught, Some(killer))
        );
        let (mut run, _) = script(turn(Verdict::Missed, None, &[], &[]));
        assert_eq!(
            decide(&runs, &mut run, &no_hang, |_| {})
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Timeout, None)
        );
    }

    /// A mutant every case of which hangs is bounded per mutant by
    /// construction: each batch runs at most twice, first over the batch and
    /// then over the cases its first run left, so the runs' bounds sum to no
    /// more than each batch's first bound and its second bound over the whole
    /// batch (CLOUD-2911).
    ///
    /// Fails by: a third run of a batch, or one per hung case, so a mutant
    /// hanging every case runs without end; or a second run that never ends a
    /// batch.
    #[test]
    fn a_mutant_hanging_every_case_is_bounded_per_mutant() {
        let batches: Vec<BTreeSet<Case>> = (0..3)
            .map(|b| (0..4).map(|n| case(&format!("b{b}c{n}"))).collect())
            .collect();
        let seconds = std::collections::BTreeMap::new();
        let asked: Asked = std::rc::Rc::default();
        let log = std::rc::Rc::clone(&asked);
        // EVERY RUN CUTS ITS FIRST CASE, OR ALL WITHOUT FAIL-FAST.
        let mut run = move |cases: &BTreeSet<Case>, fail_fast: bool| {
            log.borrow_mut().push((cases.clone(), fail_fast));
            let hung: Vec<Case> = if fail_fast {
                cases.iter().take(1).cloned().collect()
            } else {
                cases.iter().cloned().collect()
            };
            Ok(turn(Verdict::Timeout, None, &[], &hung))
        };
        let decided = decide(&batches, &mut run, &no_hang, |_| {});
        assert_eq!(
            decided
                .map(|(verdict, killer, _)| (verdict, killer))
                .expect("runs"),
            (Verdict::Timeout, None)
        );
        let fast: Vec<bool> = asked.borrow().iter().map(|(_, fast)| *fast).collect();
        assert_eq!(fast, [true, false, true, false, true, false]);
        let bound: f64 = batches
            .iter()
            .map(|batch| first_bound(batch, &seconds) + second_bound(batch, &seconds))
            .sum();
        let ran: f64 = asked
            .borrow()
            .iter()
            .map(|(cases, fast)| run_bound(cases, &seconds, *fast))
            .sum();
        assert!(ran <= bound, "{ran} s of runs within {bound} s");
        // EACH SECOND RUN HOLDS ONLY WHAT ITS FIRST LEFT: three of four cases.
        for (cases, fast) in asked.borrow().iter() {
            assert_eq!(cases.len(), if *fast { 4 } else { 3 });
        }
    }

    /// A case cut under a mutant killed it by the hang only when its control
    /// passed within a fifth of its limit: a fast case whose control took
    /// 0.5 s, or a slow one well inside five times its seconds, did; a control
    /// past a fifth of the limit, or none at all, did not (CLOUD-2911).
    ///
    /// Fails by: every cut read as a kill, so a mutant that slows a case
    /// beyond its limit is filed caught; or no cut ever a kill, so a case that
    /// waits on the event a mutant suppresses is a timeout every sweep.
    #[test]
    fn a_cut_is_a_kill_by_hang_only_when_its_control_passed_in_time() {
        let (fast, slow, unrun) = (case("fast"), case("slow"), case("unrun"));
        let seconds = [(fast.clone(), 0.5), (slow.clone(), 10.0)].into();
        let control = |passed: &[(&Case, f64)]| -> Control {
            passed
                .iter()
                .map(|(case, s)| ((*case).clone(), *s))
                .collect()
        };
        assert!(
            hang_kill(&fast, &control(&[(&fast, 0.5)]), &seconds),
            "0.5 s of 20 s"
        );
        assert!(
            hang_kill(&fast, &control(&[(&fast, 4.0)]), &seconds),
            "exactly a fifth"
        );
        assert!(
            !hang_kill(&fast, &control(&[(&fast, 4.1)]), &seconds),
            "past a fifth"
        );
        assert!(
            hang_kill(&slow, &control(&[(&slow, 10.0)]), &seconds),
            "10 s of 50 s"
        );
        assert!(!hang_kill(&slow, &control(&[(&slow, 10.5)]), &seconds));
        assert!(
            !hang_kill(&unrun, &control(&[(&fast, 0.5)]), &seconds),
            "no control"
        );
    }

    /// A fast-passing case that hangs under a mutant is caught by the hang,
    /// with no second run; a case whose control was slow, or that has none,
    /// stays a timeout (CLOUD-2911, shard 0's `exec.rs` `detached` and
    /// `lease.rs` `stop` cases).
    ///
    /// Fails by: a case waiting on the event a mutant suppresses filed a
    /// timeout, exiting 3 on every sweep; or a slow control's cut filed a
    /// kill.
    #[test]
    fn a_fast_case_that_hangs_under_the_mutant_is_caught_by_the_hang() {
        let (waits, other) = (case("a_waits"), case("z_other"));
        let batch: BTreeSet<Case> = [waits.clone(), other.clone()].into();
        let rest: BTreeSet<Case> = [other.clone()].into();
        let script = || {
            scripted(vec![
                (
                    (batch.clone(), true),
                    turn(Verdict::Timeout, None, &[], std::slice::from_ref(&waits)),
                ),
                (
                    (rest.clone(), false),
                    turn(Verdict::Missed, None, std::slice::from_ref(&other), &[]),
                ),
            ])
        };
        let (mut run, asked) = script();
        let caught = |case: &Case| case.0 == "a_waits";
        let decided = decide(std::slice::from_ref(&batch), &mut run, &caught, |_| {});
        assert_eq!(
            decided.expect("runs"),
            (Verdict::Caught, Some(waits.clone()), true)
        );
        assert_eq!(asked.borrow().len(), 1, "a kill by hang ends the mutant");
        let (mut run, asked) = script();
        let decided = decide(std::slice::from_ref(&batch), &mut run, &no_hang, |_| {});
        assert_eq!(decided.expect("runs"), (Verdict::Timeout, None, false));
        assert_eq!(asked.borrow().len(), 2);
    }

    /// The control run's passing times are its report's passed cases in the
    /// batch, and no failed, cut or foreign one (CLOUD-2911).
    ///
    /// Fails by: a failed or cut case given a control time, so its cut under a
    /// mutant reads as a kill; or a case outside the batch timed.
    #[test]
    fn the_control_times_are_the_batchs_passing_cases() {
        let xml = r#"<testsuites><testsuite name="batten::it">
            <testcase name="m::ok" classname="batten::it" time="0.25"/>
            <testcase name="m::red" classname="batten::it" time="0.5"><failure type="test failure"/></testcase>
            <testcase name="m::cut" classname="batten::it" time="20.0"><failure type="test timeout"/></testcase>
            <testcase name="m::listed" classname="batten::it" time="0.1"/>
            <testcase name="m::foreign" classname="batten::it" time="0.1"/>
        </testsuite></testsuites>"#;
        let batch: BTreeSet<Case> = ["m::ok", "m::red", "m::cut", "m::listed"].map(case).into();
        let red: Red = [(case("m::listed"), String::from("red"))].into();
        let times = control_times(xml, &batch, &red);
        assert_eq!(times, [(case("m::ok"), 0.25)].into());
    }

    /// A judging run's fixture scratch and temp start empty, whatever the run
    /// before it left there, with its fixture root made (CLOUD-2911).
    ///
    /// Fails by: a run of the cases a cut left reading what the cut run's
    /// children wrote after its cleanup.
    #[test]
    fn a_run_starts_from_a_clean_scratch() {
        let base = crate::scratch::scratch("schema-judge-scratch-fresh");
        let (scratch, work) = (base.join("judge"), base.join("mirror"));
        let stale_own = scratch.join("7").join("fixtures");
        let stale_temp = judge_temp(&work, "7");
        for dir in [&stale_own, &stale_temp] {
            std::fs::create_dir_all(dir).unwrap();
            std::fs::write(dir.join("stale"), "left").unwrap();
        }
        let (own, temp) = judge_scratch(&scratch, &work, "7");
        assert_eq!((own.clone(), temp.clone()), (scratch.join("7"), stale_temp));
        assert_eq!(std::fs::read_dir(&temp).unwrap().count(), 0);
        let left: Vec<_> = std::fs::read_dir(&own)
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect();
        assert_eq!(left, ["fixtures"]);
        assert_eq!(std::fs::read_dir(own.join("fixtures")).unwrap().count(), 0);
    }

    /// A stored verdict, a kept survivor's too, is reused without a run and without a second
    /// journal line, a mutant nothing reaches is uncovered and journaled, and
    /// progress is printed every hundred verdicts and at the end.
    ///
    /// Fails by: a reused verdict re-judged (no case reaches it, so it would
    /// read uncovered), or progress printed on the wrong count.
    #[test]
    fn stored_kills_are_reused_and_progress_is_counted_by_hundreds() {
        let base = crate::scratch::scratch("schema-judge-all");
        let source = "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n";
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(base.join("src/lib.rs"), source).unwrap();
        let with = |replacement: &str, name: &str| {
            let mut mutant = in_function(
                listed("BinaryOperator", replacement, (2, 7), (2, 9)),
                (1, 1),
                (3, 2),
            );
            mutant.name = String::from(name);
            mutant
        };
        let mut mutants: Vec<Listed> = (0..101).map(|_| with("!=", "kill")).collect();
        mutants.push(with("<", "hang"));
        mutants.push(with("<=", "none"));
        mutants.push(with(">", "kept-survivor"));
        mutants.push(with(">=", "kept-unreached"));
        let digests = std::collections::BTreeMap::new();
        let nobody = BTreeSet::new();
        let key = |m: &Listed| verdict_key(&base, m, &nobody, &digests).unwrap();
        let cache = [
            (key(&mutants[0]), String::from("caught")),
            (key(&mutants[101]), String::from("timeout")),
            (key(&mutants[103]), String::from("missed")),
            (key(&mutants[104]), String::from("uncovered")),
        ]
        .into();
        let store = base.join("verdicts");
        let reach = std::collections::BTreeMap::new();
        let seconds = std::collections::BTreeMap::new();
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &store,
            red: &Red::new(),
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let todo: Vec<u32> = (0..105).collect();
        let mut out = Vec::new();
        let mut verdicts = judge_all(&judging, &todo, 2, &mut out);
        verdicts.sort_by_key(|(id, _)| *id);
        assert!(verdicts[..101].iter().all(|(_, v)| *v == Verdict::Caught));
        assert_eq!(
            verdicts[101].1,
            Verdict::Uncovered,
            "a stored timeout is judged again, never reused"
        );
        assert_eq!(verdicts[102].1, Verdict::Uncovered);
        assert_eq!(
            verdicts[103].1,
            Verdict::Missed,
            "a kept survivor, not re-judged"
        );
        assert_eq!(verdicts[104].1, Verdict::Uncovered);
        let said = String::from_utf8(out).unwrap();
        let progress: Vec<&str> = said
            .lines()
            .filter(|line| line.starts_with("mutate schema: judged"))
            .map(|line| line.split(" in ").next().unwrap_or_default())
            .collect();
        assert!(
            said.contains("mutate schema: reused 103 of 105 verdict(s)"),
            "{said}"
        );
        assert_eq!(
            progress,
            [
                "mutate schema: judged 100/105",
                "mutate schema: judged 105/105"
            ]
        );
        let journaled = std::fs::read_to_string(&store).unwrap();
        let mut lines: Vec<&str> = journaled.lines().collect();
        lines.sort_unstable();
        let mut expected = [
            journal_line(Some(&key(&mutants[101])), "uncovered", "hang"),
            journal_line(Some(&key(&mutants[102])), "uncovered", "none"),
        ];
        expected.sort_unstable();
        assert_eq!(
            lines,
            expected.iter().map(|l| l.trim_end()).collect::<Vec<_>>()
        );
    }

    /// A RED CASE NEVER KEYS A VERDICT (U4): a mutant only a red case reaches
    /// is unjudged and journaled under the key of the cases that judged it —
    /// none — so a stored verdict keyed over the red case is not reused, and
    /// nothing journaled names the red case as a dependency.
    ///
    /// Fails by: a verdict stored over the red case reused, or the unjudged
    /// line keyed over the red case.
    #[test]
    fn a_red_case_never_keys_a_verdict() {
        let base = crate::scratch::scratch("schema-red-key");
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(
            base.join("src/lib.rs"),
            "fn f(a: u8, b: u8) -> bool {\n    a == b\n}\n",
        )
        .unwrap();
        let mut mutant = in_function(
            listed("BinaryOperator", "!=", (2, 7), (2, 9)),
            (1, 1),
            (3, 2),
        );
        mutant.name = String::from("poisoned");
        let mutants = vec![mutant];
        let red_case = (String::from("tests::red"), String::from("fix"));
        let digests: std::collections::BTreeMap<Case, String> =
            [(red_case.clone(), String::from("d"))].into();
        let reached: BTreeSet<Case> = [red_case.clone()].into();
        let over_red = verdict_key(&base, &mutants[0], &reached, &digests).unwrap();
        let over_green = verdict_key(&base, &mutants[0], &BTreeSet::new(), &digests).unwrap();
        assert_ne!(over_red, over_green);
        let cache = [(over_red, String::from("missed"))].into();
        let store = base.join("verdicts");
        let _ = std::fs::remove_file(&store);
        let reach = [(0, reached)].into();
        let seconds = std::collections::BTreeMap::new();
        let red: Red = [(red_case, String::from("red"))].into();
        let judging = Judging {
            work: &base,
            target: &base,
            scratch: &base,
            root: &base,
            mutants: &mutants,
            reach: &reach,
            seconds: &seconds,
            cache: &cache,
            digests: &digests,
            store: &store,
            red: &red,
            control: &Control::new(),
            reuse: None,
            threads: None,
        };
        let mut out = Vec::new();
        let verdicts = judge_all(&judging, &[0], 1, &mut out);
        assert_eq!(verdicts, [(0, Verdict::Unjudged)]);
        assert!(
            !String::from_utf8(out)
                .unwrap()
                .contains("could not be written"),
            "a journal that took every line reports no failed write"
        );
        assert_eq!(
            std::fs::read_to_string(&store).unwrap(),
            journal_line(Some(&over_green), "unjudged", "poisoned")
        );
    }

    /// Fails by: a mutant credited to an enclosing function rather than the
    /// innermost (a smaller span read as the larger), one on a function's own
    /// bounds dropped, or one past a function's end credited to it.
    #[test]
    fn a_mutant_belongs_to_its_innermost_enclosing_function() {
        let functions = [
            (0..100, String::from("outer")),
            (40..90, String::from("inner")),
        ];
        let placed = [
            (1, 50..60),
            (2, 10..20),
            (3, 95..105),
            (4, 40..90),
            (5, 200..210),
        ];
        assert_eq!(
            innermost(&placed, &functions),
            vec![
                (1, String::from("inner")),
                (2, String::from("outer")),
                (4, String::from("inner")),
            ]
        );
    }

    /// The items of `source`, parsed.
    fn items_of(source: &str) -> Vec<ast::Item> {
        use ast::HasModuleItem as _;
        batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
            .tree()
            .items()
            .collect()
    }

    /// The first token of `source` whose text is `text`.
    fn token_of(source: &str, text: &str) -> ra_ap_syntax::SyntaxToken {
        batten_facts::source::rust_parse(source, ra_ap_syntax::Edition::Edition2024)
            .tree()
            .syntax()
            .descendants_with_tokens()
            .filter_map(ra_ap_syntax::NodeOrToken::into_token)
            .find(|token| token.text() == text)
            .expect("the token is in the source")
    }

    /// Fails by: a named item answering to every word inside it (a struct to
    /// its field types, a module to its functions), which reruns every case
    /// naming any of them.
    #[test]
    fn a_named_item_answers_to_its_own_name_alone() {
        let source = "struct S { f: u8 }\ntrait T { fn m(); }\n\
            macro_rules! mac { () => { other }; }\nmod md { fn inner() {} }\n\
            static G: u8 = 0;\n";
        let names: Vec<Vec<String>> = items_of(source).iter().map(item_names).collect();
        assert_eq!(
            names,
            [["S"], ["T"], ["mac"], ["md"], ["G"]].map(|n| vec![n[0].to_owned()])
        );
    }

    /// Fails by: a `macro` 2.0 definition answering to every word in its
    /// body rather than to its own name.
    #[test]
    fn a_macro_definition_answers_to_its_own_name_alone() {
        let names: Vec<Vec<String>> = items_of("macro m($x:expr) { $x + other }\n")
            .iter()
            .map(item_names)
            .collect();
        assert_eq!(names, [vec![String::from("m")]]);
    }

    /// Fails by: an include rooted at `CARGO_MANIFEST_DIR` read as one no
    /// syntax can name, which keys every case on the whole tree.
    #[test]
    fn an_include_under_the_manifest_dir_names_its_file() {
        let items = items_of("include!(concat!(env!(\"CARGO_MANIFEST_DIR\"), \"/data/x.rs\"));\n");
        let Some(ast::Item::MacroCall(call)) = items.first() else {
            panic!("an item-position macro call: {items:?}");
        };
        assert_eq!(
            include_path(call, "crates/x/src/lib.rs"),
            // IN WHICHEVER PACKAGE COMPILES IT (CLOUD-2927 item 4).
            Some(Included::AnyPackage(String::from("data/x.rs")))
        );
    }

    /// Fails by: a hand-back's journaled verdict not reported as itself.
    #[test]
    fn a_handback_verdict_is_tallied_by_its_name() {
        for (name, verdict) in [
            ("caught", Some(Verdict::Caught)),
            ("missed", Some(Verdict::Missed)),
            ("timeout", Some(Verdict::Timeout)),
            ("uncovered", Some(Verdict::Uncovered)),
            ("unjudged", Some(Verdict::Unjudged)),
            ("anything else", Some(Verdict::Error)),
            ("unviable", None),
        ] {
            assert_eq!(handback_tally(name), verdict, "{name}");
        }
    }

    /// Fails by: a `static` answering to every word inside it (its type, the
    /// function its initialiser calls), which reruns every case naming any.
    #[test]
    fn a_static_answers_to_its_own_name_alone() {
        let source = "static LIMIT: Bound = Bound::new(8);\n";
        let names: Vec<Vec<String>> = items_of(source).iter().map(item_names).collect();
        assert_eq!(names, [vec![String::from("LIMIT")]]);
    }

    /// Fails by: an item-position macro skipped as if it were a call in an
    /// expression, which leaves what it binds owned by nothing.
    #[test]
    fn an_item_position_macro_owns_its_own_tokens() {
        let source = "thread_local! { static X: u8 = 1; }\nconst C: u8 = m!(2);\n";
        let item = owning_item(&token_of(source, "X")).expect("owned");
        assert!(matches!(item, ast::Item::MacroCall(_)), "{item:?}");
        let item = owning_item(&token_of(source, "2")).expect("owned");
        assert!(matches!(item, ast::Item::Const(_)), "{item:?}");
    }

    /// Fails by: a gate credited to a function whose span ends where it
    /// starts, or to an enclosing function rather than the innermost.
    #[test]
    fn a_gate_belongs_to_the_innermost_span_holding_its_start() {
        let source = "fn a() { let value = 1; }\n";
        let token = token_of(source, "value");
        let at = usize::from(token.text_range().start());
        assert!(at > 10, "the fixture places the token past a sum's tie");
        let inner = (7, at..at + 50);
        let outer = (8, 0..at + 60);
        assert!(matches!(
            owner_of(&token, &[outer.clone(), inner]),
            Owner::Probe(7)
        ));
        assert!(matches!(owner_of(&token, &[outer]), Owner::Probe(8)));
        assert!(matches!(
            owner_of(&token, &[(9, 0..at)]),
            Owner::Names(names) if names == [String::from("a")]
        ));
    }

    /// Fails by: a gate on anything but a feature read as one.
    #[test]
    fn only_a_feature_gate_names_a_feature() {
        let gated = "#[cfg(feature = \"x\")]\nfn a() {}\n";
        assert!(names_a_feature(&token_of(gated, "cfg")));
        let plain = "#[cfg(test)]\nfn b() {}\n";
        assert!(!names_a_feature(&token_of(plain, "cfg")));
    }

    /// Fails by: an edit to an unprobed file leaving its key standing (the
    /// build asked again never), or two files sharing one.
    #[test]
    fn an_unprobed_files_key_is_its_path_and_bytes() {
        let root = crate::scratch::scratch("schema-unprobe-key");
        std::fs::write(root.join("a.rs"), "one").unwrap();
        std::fs::write(root.join("b.rs"), "one").unwrap();
        let held = unprobe_key(&root, "a.rs");
        assert!(held.starts_with("unprobe-"), "{held}");
        assert_eq!(held, unprobe_key(&root, "a.rs"));
        assert_ne!(held, unprobe_key(&root, "b.rs"));
        std::fs::write(root.join("a.rs"), "two").unwrap();
        assert_ne!(held, unprobe_key(&root, "a.rs"));
    }

    /// Fails by: two formats naming one key, or a key that is not a digest.
    #[test]
    fn a_formats_key_is_a_digest_of_all_of_it() {
        let plain = Format::default().key();
        assert_eq!(plain.len(), 16);
        assert!(plain.chars().all(|c| c.is_ascii_hexdigit()), "{plain}");
        let featured = Format {
            features: vec![String::from("x")],
            ..Format::default()
        };
        assert_ne!(plain, featured.key());
    }

    /// Fails by: a profile override or a compiler flag left out of the build
    /// key, or a variable that runs no other code moving it.
    #[test]
    fn the_build_flags_are_the_code_generation_variables() {
        let vars = [
            ("RUSTFLAGS", "-Cx"),
            ("CARGO_PROFILE_TEST_OPT_LEVEL", "1"),
            ("CARGO_HOME", "/h"),
            ("PATH", "/bin"),
        ]
        .map(|(k, v)| (std::ffi::OsString::from(k), std::ffi::OsString::from(v)));
        let kept: Vec<String> = build_flags_in(vars.into_iter()).into_keys().collect();
        assert_eq!(kept, ["CARGO_PROFILE_TEST_OPT_LEVEL", "RUSTFLAGS"]);
    }

    /// A leftover is sealed only over the snapshot its context was written
    /// for: once that snapshot is replaced, or where the context never said
    /// which it was, the record is left to be recorded again.
    ///
    /// Fails by: a leftover sealed with digests of a tree it never ran on,
    /// which a later sweep would carry for that tree (CLOUD-2904).
    #[test]
    fn a_leftover_is_sealed_only_over_the_snapshot_it_ran_on() {
        let mut context = seal_context("schema-seal-snapshot-root");
        let moved = crate::scratch::scratch("schema-seal-snapshot-moved");
        record(&moved, "one", "one", Some("0"), &[("100", "0\nf1\n")]);
        std::fs::write(
            moved.join(CONTEXT),
            serde_json::to_string(&context).unwrap(),
        )
        .unwrap();
        std::fs::write(context.root.join("lib.rs"), "fn replaced() {}").unwrap();
        assert_eq!(seal_leftovers(&moved).unwrap(), 0, "the snapshot moved");
        assert!(!moved.join("one").join(DEPENDS).exists());
        context.snapshot = None;
        let unnamed = crate::scratch::scratch("schema-seal-snapshot-unnamed");
        record(&unnamed, "one", "one", Some("0"), &[("100", "0\nf1\n")]);
        std::fs::write(
            unnamed.join(CONTEXT),
            serde_json::to_string(&context).unwrap(),
        )
        .unwrap();
        assert_eq!(seal_leftovers(&unnamed).unwrap(), 0, "no snapshot named");
        let held = crate::scratch::scratch("schema-seal-snapshot-held");
        context.snapshot = Some(tree_digest(&context.root).unwrap());
        record(&held, "one", "one", Some("0"), &[("100", "0\nf1\n")]);
        std::fs::write(held.join(CONTEXT), serde_json::to_string(&context).unwrap()).unwrap();
        assert_eq!(seal_leftovers(&held).unwrap(), 1, "the snapshot held");
        let stale = crate::scratch::scratch("schema-seal-snapshot-stale");
        record(
            &stale,
            "one",
            "one",
            Some("0"),
            &[("100", "0\nf1\n"), (OVER, "t-old")],
        );
        std::fs::write(stale.join(TREE), "t-new").unwrap();
        std::fs::write(
            stale.join(CONTEXT),
            serde_json::to_string(&context).unwrap(),
        )
        .unwrap();
        assert_eq!(
            seal_leftovers(&stale).unwrap(),
            0,
            "a record made over another tree than the context's"
        );
        std::fs::write(stale.join(TREE), "t-old").unwrap();
        assert_eq!(
            seal_leftovers(&stale).unwrap(),
            1,
            "over the context's tree"
        );
    }

    /// Fails by: a source directory named `target` below the root skipped,
    /// so an edit in it moved no tree digest (round 4 #11); or the build's
    /// own `target` at the root read.
    #[test]
    fn only_the_roots_target_is_left_out_of_a_tree_digest() {
        let root = crate::scratch::scratch("schema-tree-digest-target");
        for (path, text) in [("src/target/a.rs", "1"), ("target/out", "1")] {
            std::fs::create_dir_all(root.join(path).parent().unwrap()).unwrap();
            std::fs::write(root.join(path), text).unwrap();
        }
        let held = tree_digest(&root).unwrap();
        std::fs::write(root.join("target/out"), "2").unwrap();
        assert_eq!(tree_digest(&root).unwrap(), held, "the build's target");
        std::fs::write(root.join("src/target/a.rs"), "2").unwrap();
        assert_ne!(
            tree_digest(&root).unwrap(),
            held,
            "a source dir named target"
        );
    }

    /// A file's compile-time inputs fold under its probes' sweep-wide ids:
    /// each local id offset by the file's first.
    ///
    /// Fails by: an include, a position or an observer charged to another
    /// file's probe (CLOUD-2904).
    #[test]
    fn a_folded_files_probe_ids_are_offset_by_its_first() {
        let rendered = Compiled {
            probe_includes: [(1, [String::from("x.rs")].into())].into(),
            positions: [(1, String::from("2:1"))].into(),
            observers: [1].into(),
            ..Compiled::default()
        };
        let mut all = Compiled::default();
        all.fold(&rendered, 3);
        assert_eq!(all.probe_includes.keys().copied().collect::<Vec<_>>(), [4]);
        assert_eq!(all.positions.keys().copied().collect::<Vec<_>>(), [4]);
        assert_eq!(all.observers, [4].into());
    }

    /// Each marker alone makes its holder observe a position: `line!` in a
    /// skeleton item, `#[track_caller]` on a probed function.
    ///
    /// Fails by: an observer recognised only when it carries every marker
    /// (CLOUD-2904).
    #[test]
    fn one_position_marker_alone_makes_an_observer() {
        for item in [
            "const N: u32 = line!();\n",
            "const N: fn() -> u32 = || Location::caller().line();\n",
        ] {
            let alone = render_in(
                item,
                &[],
                &BTreeSet::new(),
                Some(0),
                &FileScope::of("src/lib.rs"),
            );
            assert!(!alone.compiled.observing.is_empty(), "{item}");
        }
        let rendered = render_in(
            "#[track_caller]\npub fn f() {}\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("src/lib.rs"),
        );
        assert_eq!(
            rendered.compiled.observers,
            [0].into(),
            "track_caller alone"
        );
    }

    /// R4-12 (CLOUD-2904, round 4): a marker word in a doc comment or a
    /// string observes nothing, so a line added above its item moves no key.
    ///
    /// Fails by: markers found in an item's doc comments (`Compiled`'s own
    /// docs name `line!` and `track_caller`), which keyed 91% of probed
    /// functions at their position.
    #[test]
    fn a_marker_in_a_doc_comment_observes_nothing() {
        let source = "/// Keyed where `line!()` or `#[track_caller]` reads it.\n\
                      pub struct C {\n    /// `Location::caller` too.\n    pub at: u32,\n}\n\
                      /// Calls `column!()`.\npub fn f() -> &'static str { \"line!\" }\n";
        let render = |text: &str| {
            render_in(
                text,
                &[],
                &BTreeSet::new(),
                Some(0),
                &FileScope::of("src/lib.rs"),
            )
        };
        let held = render(source);
        assert!(held.compiled.observing.is_empty(), "{:?}", held.compiled);
        assert!(held.compiled.observers.is_empty(), "{:?}", held.compiled);
        let moved = render(&format!("\n{source}"));
        assert_eq!(moved.items, held.items, "an item's digest");
        assert_eq!(moved.probes, held.probes, "a function's digest");
    }

    /// An include is charged to the innermost probed function holding it,
    /// and one starting where a function ends is not that function's.
    ///
    /// Fails by: an include charged to its enclosing function over the nested
    /// one, or to the function it follows (CLOUD-2904).
    #[test]
    fn an_include_is_charged_to_the_innermost_function_holding_it() {
        let after = render_in(
            "fn a() {}include!(\"x.rs\");\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("src/lib.rs"),
        );
        assert!(after.compiled.probe_includes.is_empty(), "{after:?}");
        assert!(!after.compiled.item_includes.is_empty());
        let nested = render_in(
            "fn outer() {\n    let _a = 0;\n    let _b = 0;\n    let _c = 0;\n    \
             fn inner() -> &'static str { include_str!(\"x.txt\") }\n}\n",
            &[],
            &BTreeSet::new(),
            Some(0),
            &FileScope::of("src/lib.rs"),
        );
        assert_eq!(
            nested.compiled.probe_includes,
            [(1, [String::from("src/x.txt")].into())].into()
        );
    }

    /// A module's `use`s key only the cases calling methods in that module:
    /// an import edited in `a` moves no case that ran only `b`'s function,
    /// named or glob.
    ///
    /// Fails by: every module's `use` scope sharing one key, or a glob keyed
    /// under the item every case carries (CLOUD-2904).
    #[test]
    fn a_modules_use_moves_only_the_cases_calling_in_it() {
        let run = case("rb");
        let cases: BTreeSet<Case> = [run.clone()].into();
        let executed = [(run.clone(), [1].into())].into();
        let source = |a: &str, b: &str| {
            format!(
                "mod a {{ use {a}; pub fn ra(x: u8) -> u8 {{ x.go() }} }}\n\
                 mod b {{ use {b}; pub fn rb(x: u8) -> u8 {{ x.go() }} }}\n\
                 pub mod t1 {{ pub trait Ext {{ fn go(&self) -> u8; }} pub trait Other {{}} }}\n\
                 pub mod t2 {{ pub trait Ext {{ fn go(&self) -> u8; }} }}\n"
            )
        };
        let held = source_digests(
            &cases,
            &executed,
            &source("crate::t1::Ext", "crate::t1::Ext"),
        );
        assert_eq!(
            source_digests(
                &cases,
                &executed,
                &source("crate::t1::{Ext, Other}", "crate::t1::Ext")
            )[&run],
            held[&run],
            "a named use"
        );
        let globbed = source_digests(&cases, &executed, &source("crate::t1::*", "crate::t1::*"));
        assert_eq!(
            source_digests(&cases, &executed, &source("crate::t2::*", "crate::t1::*"))[&run],
            globbed[&run],
            "a glob use"
        );
    }

    /// A package's custom target roots are its non-default `[lib]` path's
    /// and its `[[bin]]` paths' outside `src/`, read as their Rust files.
    ///
    /// Fails by: the default `src/lib.rs` taken, a `src/` bin walked, or a
    /// non-Rust file kept (CLOUD-2904).
    #[test]
    fn a_packages_custom_roots_are_its_moved_targets_rust_files() {
        let root = crate::scratch::scratch("schema-custom-roots");
        let files = [
            (
                "pkg/Cargo.toml",
                "[lib]\npath = \"lib/lib.rs\"\n[[bin]]\nname = \"x\"\npath = \"bin/x.rs\"\n\
                 [[bin]]\nname = \"y\"\npath = \"src/bin/y.rs\"\n",
            ),
            ("pkg/lib/lib.rs", ""),
            ("pkg/lib/notes.txt", ""),
            ("pkg/bin/x.rs", ""),
            ("pkg/src/bin/y.rs", ""),
        ];
        for (path, text) in files {
            std::fs::create_dir_all(root.join(path).parent().unwrap()).unwrap();
            std::fs::write(root.join(path), text).unwrap();
        }
        assert_eq!(
            custom_root_sources(&root, "pkg"),
            [String::from("pkg/bin/x.rs"), String::from("pkg/lib/lib.rs")].into()
        );
    }

    /// The custom roots are found over the sweep's own snapshot, which the
    /// keys read, not only over a checkout.
    ///
    /// Fails by: a snapshot carrying Rust sources alone, under which no
    /// manifest names a custom root and neither reader finds one (CLOUD-2904).
    #[test]
    fn a_custom_root_is_found_over_the_sweeps_snapshot() {
        let dir = crate::scratch::scratch("schema-custom-roots-snapshot");
        let repo = dir.join("repo");
        let files = [
            (
                "pkg/Cargo.toml",
                "[package]\nname = \"pkg\"\n[lib]\npath = \"lib/lib.rs\"\n",
            ),
            ("pkg/lib/lib.rs", "pub fn l() {}\n"),
        ];
        for (path, text) in files {
            std::fs::create_dir_all(repo.join(path).parent().unwrap()).unwrap();
            std::fs::write(repo.join(path), text).unwrap();
        }
        crate::gitwrite::commit_paths(&repo, &files.map(|(path, _)| path.to_owned()), "fixture")
            .unwrap();
        let snapshot = dir.join("pristine");
        super::super::cover::pristine(&repo, &snapshot).unwrap();
        assert!(custom_target(&snapshot, "pkg"));
        assert_eq!(
            custom_root_sources(&snapshot, "pkg"),
            [String::from("pkg/lib/lib.rs")].into()
        );
    }

    /// Fails by: a binary with no target, or a nested one, walked as a test
    /// crate (CLOUD-2904).
    #[test]
    fn a_binary_without_a_plain_target_has_no_crate_sources() {
        let root = crate::scratch::scratch("schema-crate-sources-none");
        let dirs = [(String::from("p"), String::new())].into();
        assert_eq!(crate_sources(&root, &dirs, "p::", None), None);
        assert_eq!(crate_sources(&root, &dirs, "p::a/b", None), None);
    }

    /// An edit to a sibling module's function no case reaches moves no case:
    /// a file that parses is keyed by what is reached in it, not whole.
    ///
    /// Fails by: every parsed file of the test crate keyed whole (CLOUD-2904).
    #[test]
    fn an_unreached_sibling_function_moves_no_case() {
        let plans = (String::from("plan::plans"), String::from("fix::it"));
        let cases: BTreeSet<Case> = [plans.clone()].into();
        let executed = [(plans.clone(), BTreeSet::new())].into();
        let none = std::collections::BTreeMap::new();
        let tree = |label: &str, unused: &str| {
            let claim =
                format!("pub fn check() -> u8 {{ 1 }}\npub fn unused() -> u8 {{ {unused} }}\n");
            tree_digests(
                label,
                &cases,
                &executed,
                &[
                    ("src/lib.rs", "pub fn f() {}\n"),
                    ("tests/it/main.rs", "mod claim;\nmod plan;\n"),
                    ("tests/it/claim.rs", &claim),
                    (
                        "tests/it/plan.rs",
                        "#[test]\nfn plans() { assert_eq!(crate::claim::check(), 1); }\n",
                    ),
                ],
                &none,
            )[&plans]
                .clone()
        };
        assert_eq!(
            tree("schema-unreached-a", "0"),
            tree("schema-unreached-b", "2")
        );
    }

    /// An impl in a shared module that nothing reached names is not taken:
    /// it answers to its self type, trait and methods only.
    ///
    /// Fails by: an impl taken whatever a case names (CLOUD-2904).
    #[test]
    fn an_impl_nothing_names_is_not_taken() {
        let text = [String::from("fn t() { other(); }")];
        let common = |value: &str| {
            format!(
                "pub struct Foo;\npub trait Tr {{ fn go(&self) -> u8; }}\n\
                 impl Tr for Foo {{ fn go(&self) -> u8 {{ {value} }} }}\npub fn other() {{}}\n"
            )
        };
        assert_eq!(
            common_reached(&common("1"), &text),
            common_reached(&common("2"), &text)
        );
    }

    /// A test's text carries the items of its own module as well as those of
